/*!50003 CREATE*/ /*!50017 */ /*!50003 TRIGGER `bank_transactions_AFTER_INSERT` AFTER INSERT ON `bank_transactions` FOR EACH ROW BEGIN

update chart_of_accounts set CURRENT_BALANCE =(CURRENT_BALANCE - new.AMOUNT) where ACCOUNT_ID=new.PARTY and new.TRANSACTION_TYPE="Credit";
update chart_of_accounts set CURRENT_BALANCE =(CURRENT_BALANCE - new.AMOUNT) where ACCOUNT_ID=new.PARTY and new.TRANSACTION_TYPE="Debit";
update chart_of_accounts set CURRENT_BALANCE =(CURRENT_BALANCE + new.AMOUNT) where ACCOUNT_ID=new.COUNTER_PARTY and new.TRANSACTION_TYPE="Debit";
update chart_of_accounts set CURRENT_BALANCE =(CURRENT_BALANCE + new.AMOUNT) where ACCOUNT_ID=new.COUNTER_PARTY and new.TRANSACTION_TYPE="Credit";

update  chart_of_accounts set AS_OF_DATE=new.TRANSACTION_DATE where ACCOUNT_ID=new.PARTY;
update  chart_of_accounts set AS_OF_DATE=new.TRANSACTION_DATE where ACCOUNT_ID=new.COUNTER_PARTY;

insert into bank_transactions_history(TRANSACTION_DATE,AMOUNT,
BALANCE,COUNTER_PARTY_BALANCE,TRANSACTION_REF,TRANSACTION_TYPE,REASON,MODE,
CREATION_USER_ID,CREATION_TS,
LAST_UPDATE_USER_ID,LAST_UPDATE_TS,CHEQUE_NO,PHONE_NUMBER,PARTY,COUNTER_PARTY,CARD_NO,TRANSACTION_ID,STATUS) 
values(new.TRANSACTION_DATE,new.AMOUNT,
new.BALANCE,new.COUNTER_PARTY_BALANCE,new.TRANSACTION_REF,new.TRANSACTION_TYPE,new.REASON,new.MODE,
new.CREATION_USER_ID,new.CREATION_TS,
new.LAST_UPDATE_USER_ID,new.LAST_UPDATE_TS,new.CHEQUE_NO,
new.PHONE_NUMBER,new.PARTY,new.COUNTER_PARTY,new.CARD_NO,new.TRANSACTION_ID,new.STATUS);

END */;;
DELIMITER ;
