  `AUDIT_ID` int DEFAULT NULL,
  `ACTIVE_S` char(1) DEFAULT 'Y',
  PRIMARY KEY (`ALLOCATION_LINE_ID`),
  KEY `IDX_CREDIT_ALLOC_LINE_BATCH` (`ALLOCATION_BATCH_ID`),
  KEY `IDX_CREDIT_ALLOC_LINE_BILL` (`SALES_BILL_ID`),
