/*!50003 CREATE*/ /*!50017 */ /*!50003 TRIGGER `credit_note_AFTER_INSERT` AFTER INSERT ON `credit_note` FOR EACH ROW BEGIN

DECLARE i DOUBLE DEFAULT 0;

select CURRENT_BALANCE from chart_of_accounts where account_id=63 into i;

insert into till_balance(CURRENT_BALANCE,AMOUNT,AS_OF_DATE,PHARMACY_ID,CREATION_TS,
CREATION_USER_ID,LAST_UPDATE_USER_ID,LAST_UPDATE_TS,TILL_ACCOUNT_ID,
CUSTOMER_NM,BILL_CODE,BILL_DATE,BILL_ID,PREV_BALANCE,ADJUSTED_BALANCE) 
select i-new.amount,(-1*new.amount),new.credit_date,
new.PHARMACY_ID,new.CREATION_TS,new.CREATION_USER_ID,
new.LAST_UPDATE_USER_ID,new.LAST_UPDATE_TS,63,concat(cu.FIRST_NM," ",cu.LAST_NM),
new.BILL_ID,new.credit_date,new.CREDIT_NOTE_ID,i,(i-new.amount)-i 
from credit_note c inner join customer cu on cu.CUSTOMER_ID=c.CUSTOMER_ID
where c.credit_note_id=new.credit_note_id 
and new.PAYMENT_TYPE_ID=1 and (new.bill_type_id="Cash Back" or new.bill_type_id="Cash Payment");

update chart_of_Accounts set CURRENT_BALANCE=CURRENT_BALANCE-new.amount,
AS_OF_DATE=NOW() where ACCOUNT_ID=63 and new.PAYMENT_TYPE_ID=1 
and (new.bill_type_id="Cash Back" or new.bill_type_id="Cash Payment");


END */;;
DELIMITER ;
