/*!50003 CREATE*/ /*!50017 */ /*!50003 TRIGGER `petty_cash_AFTER_INSERT` AFTER INSERT ON `petty_cash` FOR EACH ROW BEGIN

update chart_of_accounts c set c.CURRENT_BALANCE = c.CURRENT_BALANCE+new.AMOUNT where ACCOUNT_ID=new.COUNTER_PARTY_NO; 

update chart_of_accounts c set c.AS_OF_DATE = new.DATE where ACCOUNT_ID=new.COUNTER_PARTY_NO; 

update chart_of_accounts c set c.CURRENT_BALANCE=c.CURRENT_BALANCE-new.AMOUNT where ACCOUNT_ID=new.PARTY_NO;

update chart_of_accounts c set c.AS_OF_DATE = new.DATE where ACCOUNT_ID=new.PARTY_NO; 

insert into petty_cash_history(PETTYCASH_REF,DATE,PARTY_NO,COUNTER_PARTY_NO,
AMOUNT,REFERENCE,BALANCE,CREATION_USER_ID,CREATION_TS,
LAST_UPDATE_USER_ID,LAST_UPDATE_TS,AUDIT_ID) values(new.PETTYCASH_REF,new.DATE,new.PARTY_NO,
new.COUNTER_PARTY_NO,new.AMOUNT,new.REFERENCE,new.BALANCE,new.CREATION_USER_ID,new.CREATION_TS,
new.LAST_UPDATE_USER_ID,new.LAST_UPDATE_TS,new.AUDIT_ID);

END */;;
DELIMITER ;
