/*!50003 CREATE*/ /*!50017 */ /*!50003 TRIGGER `purchase_return_item_AFTER_INSERT` AFTER INSERT ON `purchase_return_item` FOR EACH ROW BEGIN
update stock s inner join invoice i on s.INVOICE_NO = i.grn_no inner join purchase_return pr on pr.invoice_id = i.invoice_id set s.QUANTITY=(s.QUANTITY-(new.RETURN_QUANTITY*s.PACK))
where s.STOCK_ID=new.STOCK_ID;

IF(new.BONUS_RETURN_QTY is not null ) THEN
update stock s inner join invoice i on s.INVOICE_NO = i.GRN_NO 
inner join purchase_return pr on pr.INVOICE_ID = i.INVOICE_ID set s.QUANTITY=(s.QUANTITY-(new.BONUS_RETURN_QTY*s.PACK))
where s.STOCK_ID=new.STOCK_ID ;
END IF;

END */;;
