/*!50003 CREATE*/ /*!50017 */ /*!50003 TRIGGER `sales_AFTER_INSERT` AFTER INSERT ON `sales` FOR EACH ROW BEGIN
DECLARE i DOUBLE DEFAULT 0;

select CURRENT_BALANCE from chart_of_accounts where account_id=63 into i;

insert into till_balance(CURRENT_BALANCE,AMOUNT,AS_OF_DATE,PHARMACY_ID,CREATION_TS,
CREATION_USER_ID,LAST_UPDATE_USER_ID,LAST_UPDATE_TS,TILL_ACCOUNT_ID,
CUSTOMER_NM,BILL_CODE,BILL_DATE,BILL_ID,PREV_BALANCE,ADJUSTED_BALANCE) 
select i+new.CASH_AMOUNT,new.CASH_AMOUNT,new.BILL_DATE,
new.PHARMACY_ID,new.CREATION_TS,new.CREATION_USER_ID,
new.LAST_UPDATE_USER_ID,new.LAST_UPDATE_TS,63,new.CUSTOMER_NM,
new.BILL_CODE,new.BILL_DATE,new.BILL_ID,i,(i+new.CASH_AMOUNT)-i 
where new.CASH_AMOUNT>0 and new.payment_status!='Dummy Bill';

update chart_of_Accounts set CURRENT_BALANCE=CURRENT_BALANCE+new.CASH_AMOUNT,
AS_OF_DATE=NOW() where ACCOUNT_ID=63 and new.CASH_AMOUNT>=0 
and new.payment_status!='Dummy Bill';

END */;;
DELIMITER ;
