/*!50003 CREATE*/ /*!50017 */ /*!50003 TRIGGER `sales_AFTER_DELETE` AFTER DELETE ON `sales` FOR EACH ROW BEGIN

set sql_safe_updates=0;

delete from till_balance where BILL_ID=old.BILL_ID;

update chart_of_Accounts set CURRENT_BALANCE=CURRENT_BALANCE-old.CASH_AMOUNT,
AS_OF_DATE=NOW() where ACCOUNT_ID=63 and old.CASH_AMOUNT>=0;


END */;;
DELIMITER ;
