/*!50003 CREATE*/ /*!50017 */ /*!50003 TRIGGER `sales_items_stock_update` AFTER INSERT ON `sales_items` FOR EACH ROW begin
  update stock s inner join sales ss on new.BILL_ID=ss.BILL_ID set s.QUANTITY= (s.QUANTITY - NEW.SALE_QTY),s.entry_type="Sales Billing",s.BILL_ID=new.BILL_ID where s.STOCK_ID=NEW.STOCK_ID and ss.PAYMENT_STATUS != 'Dummy Bill' 
   and ss.PAYMENT_STATUS != 'Cancel';
   
   update stock s inner join sales ss on new.BILL_ID=ss.BILL_ID set s.QUANTITY= (s.QUANTITY + NEW.SALE_QTY),s.entry_type="Sales Canceling",s.BILL_ID=new.BILL_ID  where s.STOCK_ID=NEW.STOCK_ID and  ss.PAYMENT_STATUS = 'Cancel'; 
 
 END */;;
DELIMITER ;
