update stock s inner join sales ss on new.BILL_ID=ss.BILL_ID set s.QUANTITY= (s.QUANTITY + NEW.SALE_QTY),s.entry_type="Sales Canceling" 
   where s.STOCK_ID=NEW.STOCK_ID and  ss.PAYMENT_STATUS = 'Cancel';
   
END */;;
