/*!50003 CREATE*/ /*!50017 */ /*!50003 TRIGGER `sales_return_item_AFTER_INSERT` AFTER INSERT ON `sales_return_item` FOR EACH ROW BEGIN
update stock s set s.QUANTITY=s.QUANTITY+new.RETURN_QUANTITY where s.ITEM_ID=new.ITEM_ID and 
s.Stock_ID =( select max(Stock_ID) from sales_items i, sales_return t where i.Item_ID = s.Item_ID and i.Item_ID = new.Item_ID 
and i.Bill_ID = t.Bill_ID and t.Sales_Return_ID = new.Sales_Return_ID);
END */;;
DELIMITER ;
