DROP TABLE IF EXISTS `web_absa_transactions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `web_absa_transactions` (
  `ABSA_TRANSACTION_ID` int NOT NULL AUTO_INCREMENT,
  `ORDER_ID` varchar(50) DEFAULT NULL COMMENT 'web_orders.ORDER_ID, e.g. WEB-2026-886561',
  `CUSTOMER_ID` int DEFAULT NULL COMMENT 'NULL for guest checkout',
  `REFERENCE_CODE` varchar(64) NOT NULL COMMENT 'Our reference, sent as clientReferenceInformation.code',
  `CYBERSOURCE_ID` varchar(64) DEFAULT NULL COMMENT 'CyberSource transaction id, for reconciliation and refunds',
  `STATUS` varchar(30) NOT NULL DEFAULT 'SESSION_CREATED' COMMENT 'SESSION_CREATED | AUTHORIZED | DECLINED | REJECTED | PENDING_VERIFICATION | FAILED | REFUNDED',
  `AMOUNT` decimal(15,2) NOT NULL,
  `CURRENCY` varchar(3) NOT NULL DEFAULT 'KES',
  `CARD_NETWORK` varchar(20) DEFAULT NULL COMMENT 'VISA | MASTERCARD | AMEX',
  `CARD_LAST4` char(4) DEFAULT NULL COMMENT 'Masked digits only — never the full number',
  `GATEWAY_REASON` varchar(120) DEFAULT NULL COMMENT 'Reason/decision returned by CyberSource',
  `CREATION_TS` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `CREATION_USER_ID` varchar(50) DEFAULT 'system',
  `LAST_UPDATE_TS` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `LAST_UPDATE_USER_ID` varchar(50) DEFAULT 'system',
  `ACTIVE_S` char(1) DEFAULT 'Y',
  PRIMARY KEY (`ABSA_TRANSACTION_ID`),
  UNIQUE KEY `UQ_WEB_ABSA_REFERENCE` (`REFERENCE_CODE`),
  UNIQUE KEY `UQ_WEB_ABSA_CYBERSOURCE` (`CYBERSOURCE_ID`),
  KEY `IDX_WEB_ABSA_ORDER` (`ORDER_ID`),
  KEY `IDX_WEB_ABSA_CUSTOMER` (`CUSTOMER_ID`),
  KEY `IDX_WEB_ABSA_STATUS` (`STATUS`,`CREATION_TS`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
