CREATE TABLE `web_access_log` (
  `ACCESS_LOG_ID` bigint NOT NULL AUTO_INCREMENT,
  `ACTOR_ID` int DEFAULT NULL COMMENT 'customer.CUSTOMER_ID or employee.EMPLOYEE_ID; NULL when unauthenticated',
  `ACTOR_TYPE` varchar(20) NOT NULL DEFAULT 'anonymous' COMMENT 'customer | employee | admin | anonymous',
  `ACTOR_ROLE` varchar(50) DEFAULT NULL COMMENT 'Role at the time of access, e.g. PHARMACIST',
  `ACTION` varchar(60) NOT NULL COMMENT 'e.g. PRESCRIPTION_IMAGE_VIEW, PRESCRIPTION_VIEW, REVIEW_MODERATE',
  `RESOURCE_TYPE` varchar(40) DEFAULT NULL COMMENT 'e.g. PRESCRIPTION, PRESCRIPTION_IMAGE, ORDER, REVIEW',
  `RESOURCE_ID` varchar(200) DEFAULT NULL COMMENT 'Identifier of the record; may be a filename, so not an int',
  `SUBJECT_CUSTOMER_ID` int DEFAULT NULL,
  `OUTCOME` varchar(10) NOT NULL DEFAULT 'ALLOWED' COMMENT 'ALLOWED | DENIED',
  `REASON` varchar(200) DEFAULT NULL COMMENT 'Why access was refused',
  `IP_ADDRESS` varchar(45) DEFAULT NULL COMMENT 'IPv4 or IPv6',
  `USER_AGENT` varchar(255) DEFAULT NULL,
  `REQUEST_METHOD` varchar(10) DEFAULT NULL,
  `REQUEST_PATH` varchar(255) DEFAULT NULL,
  `CREATION_TS` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`ACCESS_LOG_ID`),
  KEY `IDX_WEB_ACCESS_LOG_SUBJECT` (`SUBJECT_CUSTOMER_ID`,`CREATION_TS`),
  KEY `IDX_WEB_ACCESS_LOG_ACTOR` (`ACTOR_ID`,`CREATION_TS`),
  KEY `IDX_WEB_ACCESS_LOG_ACTION` (`ACTION`,`CREATION_TS`),
  KEY `IDX_WEB_ACCESS_LOG_OUTCOME` (`OUTCOME`,`CREATION_TS`),
  KEY `IDX_WEB_ACCESS_LOG_TS` (`CREATION_TS`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
