  CONSTRAINT `FK_WEB_REVIEW_VOTES_REVIEW` FOREIGN KEY (`REVIEW_ID`) REFERENCES `web_reviews` (`REVIEW_ID`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
