DROP TABLE IF EXISTS `web_reviews`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `web_reviews` (
  `REVIEW_ID` int NOT NULL AUTO_INCREMENT,
  `ITEM_ID` int NOT NULL,
  `CUSTOMER_ID` int NOT NULL,
  `ORDER_ID` int DEFAULT NULL COMMENT 'Set when the reviewer bought this item; drives the Verified Purchase badge',
  `RATING` tinyint NOT NULL COMMENT '1-5 stars',
  `TITLE` varchar(150) DEFAULT NULL,
  `BODY` text,
  `STATUS` varchar(20) NOT NULL DEFAULT 'PENDING' COMMENT 'PENDING | APPROVED | REJECTED',
  `HELPFUL_COUNT` int NOT NULL DEFAULT '0',
  `REPORT_COUNT` int NOT NULL DEFAULT '0',
  `MODERATED_BY` varchar(50) DEFAULT NULL,
  `MODERATED_TS` timestamp NULL DEFAULT NULL,
  `REJECTION_REASON` varchar(255) DEFAULT NULL,
  `CREATION_TS` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `CREATION_USER_ID` varchar(50) DEFAULT 'system',
  `LAST_UPDATE_TS` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `LAST_UPDATE_USER_ID` varchar(50) DEFAULT 'system',
  `AUDIT_ID` int DEFAULT NULL,
  `ACTIVE_S` char(1) DEFAULT 'Y',
  PRIMARY KEY (`REVIEW_ID`),
  UNIQUE KEY `UQ_WEB_REVIEWS_CUSTOMER_ITEM` (`CUSTOMER_ID`,`ITEM_ID`),
  KEY `IDX_WEB_REVIEWS_ITEM` (`ITEM_ID`),
  KEY `IDX_WEB_REVIEWS_STATUS` (`STATUS`),
  KEY `IDX_WEB_REVIEWS_ITEM_STATUS` (`ITEM_ID`,`STATUS`,`ACTIVE_S`),
  CONSTRAINT `FK_WEB_REVIEWS_CUSTOMER` FOREIGN KEY (`CUSTOMER_ID`) REFERENCES `customer` (`CUSTOMER_ID`) ON DELETE CASCADE,
  CONSTRAINT `FK_WEB_REVIEWS_ITEM` FOREIGN KEY (`ITEM_ID`) REFERENCES `items` (`ITEM_ID`) ON DELETE CASCADE,
  CONSTRAINT `CHK_WEB_REVIEWS_RATING` CHECK ((`RATING` between 1 and 5))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
