/*!50106 DROP EVENT IF EXISTS `create_item_reorder_level_event` */;;
DELIMITER ;;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;;
/*!50003 SET character_set_client  = utf8mb4 */ ;;
/*!50003 SET character_set_results = utf8mb4 */ ;;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;;
/*!50003 SET @saved_time_zone      = @@time_zone */ ;;
/*!50003 SET time_zone             = 'SYSTEM' */ ;;
/*!50106 CREATE*/ /*!50117 */ /*!50106 EVENT `create_item_reorder_level_event` ON SCHEDULE EVERY 1 DAY STARTS '2021-07-14 23:50:00' ON COMPLETION NOT PRESERVE ENABLE DO BEGIN
set @startdate=DATE_SUB(LAST_DAY(NOW()),INTERVAL DAY(LAST_DAY(NOW()))-1 DAY);
set @enddate=LAST_DAY(now());
truncate table item_reorder_level;
insert into item_reorder_level (
select i.item_id,i.item_nm,round((sum(si.SALE_QTY)/(select count(distinct s.bill_date) from sales s 
where s.BILL_DATE>=@startdate and s.BILL_DATE<=@enddate))*10,2) as reorder_level,
round((sum(si.SALE_QTY)/(select count(distinct s.bill_date) from sales s 
where s.BILL_DATE>=@startdate and s.BILL_DATE<=@enddate))*6,2) as reorder_qty
from sales_items si left join  items i on i.ITEM_ID= si.ITEM_ID
left join sales s on s.BILL_ID = si.BILL_ID 
where s.BILL_DATE>=@startdate and s.BILL_DATE<=@enddate 
group by i.ITEM_NM);
END */ ;;
/*!50003 SET time_zone             = @saved_time_zone */ ;;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;;
/*!50003 SET character_set_client  = @saved_cs_client */ ;;
/*!50003 SET character_set_results = @saved_cs_results */ ;;
/*!50003 SET collation_connection  = @saved_col_connection */ ;;
