/*!50106 CREATE*/ /*!50117 */ /*!50106 EVENT `insert_auto_quotation_items` ON SCHEDULE EVERY 1 DAY STARTS '2021-07-26 23:55:00' ON COMPLETION NOT PRESERVE ENABLE DO BEGIN
set sql_safe_updates=0;
delete from auto_quotations where (select count(*) from sales where BILL_DATE=curdate() group by bill_date)>0;
insert into auto_quotations
(item_id,item_nm,QUANTITY,ACTIVE_S,SUPPLIER_ID,SUPPLIER_PRIORITY,UNIT_RATE,DISCOUNT_PERCENTAGE,VALIDITY,ITEM_SUPPLIER_ID,BARCODE,BONUS)
select distinct si.item_id,i.item_nm,i.REORDER_QTY,'Y',it.SUPPLIER_ID,it.SUPPLIER_PRIORITY,
it.UNIT_RATE,it.DISCOUNT_PERCENTAGE,it.VALIDITY,it.ITEM_SUPPLIER_ID,i.BARCODE,
ifnull((select init.bonus from invoice inv,invoice_items init where inv.invoice_id=init.invoice_id and init.item_id=it.item_id and it.SUPPLIER_ID=inv.SUPPLIER_ID order by init.last_update_ts desc limit 1),0) as bonus
from sales s inner join sales_items si on si.bill_id=s.bill_id
inner join items i on i.item_id=si.item_id
inner join stock st on si.item_id=st.item_id and st.stock_id=si.stock_id
inner join items_supplier it on it.item_id=i.item_id
where i.REORDER_LEVEL>st.QUANTITY and i.REORDER_QTY is not null and s.bill_date=curdate();
END */ ;;
