CREATE  PROCEDURE `ACCOUNT_PAYABLES`(
	IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN
DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';
DECLARE AP_WHERE_CLAUSE VARCHAR(5000) DEFAULT '';

SET AP_WHERE_CLAUSE=WHERECLAUSE;   
SET AP_WHERE_CLAUSE=replace(AP_WHERE_CLAUSE,'e.EMP_NM','CONCAT(e.FIRST_NM," ", e.LAST_NM)');

TRUNCATE TABLE account_payables_working;

insert into account_payables_working select ap.SUPPLIER_NAME,ap.PAYMENT_NO,ap.SOURCE_REF,ap.INVOICE_NO,ap.PAYMENT_DATE,
ap.STATUS,ap.TOTAL_AMOUNT_PAID,ap.TOTAL_AMOUNT_TO_BE_PAID,ap.PAYMENT_STATUS,ap.SOURCE_TYPE,ap.APPROVED_BY,
ap.APPROVED_DATE,ap.APPROVED_DATE, concat(e.FIRST_NM , " " , e.LAST_NM) as CREATED_BY,
concat(emp.FIRST_NM , " " , emp.LAST_NM) as MODIFIED_BY,CONCAT(e.FIRST_NM," ", e.LAST_NM) AS EMP_NM from account_payables ap
inner join employee e on e.EMPLOYEE_ID=ap.CREATION_USER_ID
inner join employee emp on emp.EMPLOYEE_ID=ap.LAST_UPDATE_USER_ID;

SET BASE_SQL='select ifnull(ap.SUPPLIER_NAME," ") SUPPLIER_NAME,
ap.PAYMENT_NO,ifnull(ap.SOURCE_REF," ") SOURCE_REF,ifnull(ap.INVOICE_NO," ") INVOICE_NO,
date_format(ap.PAYMENT_DATE,"%d-%m-%y") PAYMENT_DATE,
ap.STATUS, ifnull(ap.TOTAL_AMOUNT_PAID,0) TOTAL_AMOUNT_PAID,
ifnull(ap.TOTAL_AMOUNT_TO_BE_PAID,0) TOTAL_AMOUNT_TO_BE_PAID,
ap.PAYMENT_STATUS,ifnull(ap.SOURCE_TYPE," ") SOURCE_TYPE,ifnull(e.FIRST_NM," ") FIRST_NM,
ifnull(date_format(ap.FROM_APPROVED_DATE,"%d-%m-%y")," ") FROM_APPROVED_DATE,
date_format(ap.TO_APPROVED_DATE,"%d-%m-%y") TO_APPROVED_DATE,ap.CREATED_BY,ap.MODIFIED_BY ,
ap.EMP_NM from account_payables_working ap
 left join employee e on e.EMPLOYEE_ID=ap.APPROVED_BY ';

SET @FINAL_SQL= CONCAT(BASE_SQL,AP_WHERE_CLAUSE);

PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ACCOUNT_RECEIVABLES` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
