CREATE  PROCEDURE `ACCOUNT_RECEIVABLES_RECEIPT`(
	IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN
DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';

set BASE_SQL='select ar.CUSTOMER_NAME,ar.RECEIPT_NO,ar.SOURCE_REF,ar.RECEIPT_DATE,
ifnull(ar.PAYMENT_TYPE,"N/A") TYPE,
ar.STATUS,ar.AMOUNT_RECEIVED,ar.AMOUNT_TO_BE_RECEIVED,ar.PAYMENT_STATUS,ar.SOURCE_TYPE,ar.APPROVED_BY,
ar.APPROVED_DATE,ar.APPROVED_DATE, concat(e.FIRST_NM , " " , e.LAST_NM) as CREATED_BY,
concat(emp.FIRST_NM , " " , emp.LAST_NM) as MODIFIED_BY,
CONCAT(e.FIRST_NM," ", e.LAST_NM) AS EMP_NM,
ROW_NUMBER() OVER(ORDER BY (SELECT 1)) AS S_NO from account_receivables ar
inner join employee e on e.EMPLOYEE_ID=ar.CREATION_USER_ID
inner join employee emp on emp.EMPLOYEE_ID=ar.LAST_UPDATE_USER_ID
left join sales s on s.BILL_CODE=ar.SOURCE_REF';


SET @FINAL_SQL= CONCAT(BASE_SQL,WHERECLAUSE);

PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;

END ;;
