CREATE  PROCEDURE `ACCOUNT_RECEIVABLES_RECEIPT_DUAL`(
	IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN
DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';
DECLARE AR_WHERE_CLAUSE VARCHAR(5000) DEFAULT '';

SET AR_WHERE_CLAUSE=WHERECLAUSE;   
SET AR_WHERE_CLAUSE=replace(AR_WHERE_CLAUSE,'e.EMP_NM','CONCAT(e.FIRST_NM," ", e.LAST_NM)');


TRUNCATE TABLE account_receivables_receipt_working;
 
insert into account_receivables_receipt_working select ar.CUSTOMER_NAME,ar.RECEIPT_NO,
ar.SOURCE_REF,ar.RECEIPT_DATE,
ar.STATUS,ar.AMOUNT_RECEIVED,ar.AMOUNT_TO_BE_RECEIVED,ar.PAYMENT_STATUS,ar.SOURCE_TYPE,ar.APPROVED_BY,
ar.APPROVED_DATE,ar.APPROVED_DATE, concat(e.FIRST_NM , " " , e.LAST_NM) as CREATED_BY,
concat(emp.FIRST_NM , " " , emp.LAST_NM) as MODIFIED_BY,
CONCAT(e.FIRST_NM," ", e.LAST_NM) AS EMP_NM,
ifnull(ar.PAYMENT_TYPE,"N/A") TYPE,ar.UNIQUE_RECEIPT_NO
from account_receivables ar
inner join employee e on e.EMPLOYEE_ID=ar.CREATION_USER_ID
inner join employee emp on emp.EMPLOYEE_ID=ar.LAST_UPDATE_USER_ID
where ar.UNIQUE_RECEIPT_NO is not null;

SET BASE_SQL=  'select ar.CUSTOMER_NAME,ar.RECEIPT_NO,ar.TYPE,
ar.SOURCE_REF,date_format(ar.RECEIPT_DATE,"%d-%m-%y") RECEIPT_DATE,
ar.STATUS,ifnull(ar.AMOUNT_RECEIVED,0) as AMOUNT_RECEIVED,
ifnull(ar.AMOUNT_TO_BE_RECEIVED,0) as AMOUNT_TO_BE_RECEIVED,
ar.PAYMENT_STATUS,ar.SOURCE_TYPE,e.FIRST_NM,ifnull(ar.UNIQUE_RECEIPT_NO,"N/A") UNIQUE_RECEIPT_NO,
date_format(ar.FROM_APPROVED_DATE,"%d-%m-%y") FROM_APPROVED_DATE,ar.TO_APPROVED_DATE,ar.CREATED_BY,
ar.MODIFIED_BY ,ar.EMP_NM from account_receivables_receipt_working ar
 inner join employee e on ar.APPROVED_BY=e.EMPLOYEE_ID ';

SET @FINAL_SQL= CONCAT(BASE_SQL,AR_WHERE_CLAUSE);

PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;

END ;;
DELIMITER ;
