CREATE  PROCEDURE `BANK_STATEMENT`(
	IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN
DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';

TRUNCATE TABLE bank_transactions_working;

insert into bank_transactions_working select bt.TRANSACTION_REF,
bt.TRANSACTION_DATE,bt.TRANSACTION_DATE,
c.ACCOUNT_NO,c.ACCOUNT_NAME, concat(c.ACCOUNT_NAME,' : ',c.ACCOUNT_NO) AS PARTY,
bt.MODE,bt.TRANSACTION_TYPE,
bt.AMOUNT,bt.BALANCE,concat(e.FIRST_NM,' ',ifnull(e.LAST_NM,'')) as FIRST_NM,
bt.COUNTER_PARTY_BALANCE,bt.REASON from bank_transactions bt 
inner join chart_of_accounts c on c.ACCOUNT_ID = bt.PARTY
 INNER JOIN employee e on bt.LAST_UPDATE_USER_ID=e.EMPLOYEE_ID;

SET BASE_SQL=  'select bt.TRANSACTION_REF,
DATE_FORMAT(bt.FROM_TRANSACTION_DATE,"%d-%m-%y") AS FROM_TRANSACTION_DATE,
date_format(bt.TO_TRANSACTION_DATE,"%d-%m-%y") as TO_TRANSACTION_DATE,
bt.ACCOUNT_NO_PARTY,bt.ACCOUNT_NAME_PARTY,bt.PARTY,bt.MODE,bt.TRANSACTION_TYPE,
bt.COUNTER_PARTY_BALANCE,ifnull(bt.REASON,"N/A") REASON,
bt.AMOUNT,bt.BALANCE,bt.SUBMITTED_BY from bank_transactions_working bt';


SET @FINAL_SQL= CONCAT(BASE_SQL,WHERECLAUSE);

PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;

END ;;
DELIMITER ;
