CREATE  PROCEDURE `BANK_TRANSACTION`(
	IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN
DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';
DECLARE DATE_WHERE_CLAUSE VARCHAR(5000) DEFAULT '';

TRUNCATE TABLE bank_transactions_working1;

insert into bank_transactions_working1
( select bt.TRANSACTION_REF,bt.TRANSACTION_DATE,bt.TRANSACTION_DATE,
ifnull(concat(c1.ACCOUNT_NAME," : ",c1.ACCOUNT_NO),'') AS COUNTER_PARTY,
bt.VALUE_DATE,c.ACCOUNT_NO,c.ACCOUNT_NAME, 
concat(c.ACCOUNT_NAME,' : ',c.ACCOUNT_NO) AS PARTY,bt.MODE,bt.TRANSACTION_TYPE,
bt.AMOUNT,bt.BALANCE,concat(em.FIRST_NM,' ',ifnull(em.LAST_NM,'')),bt.COUNTER_PARTY_BALANCE,
bt.REASON,bt.LAST_UPDATE_TS,bt.STATUS
 from bank_transactions bt left join chart_of_accounts c on c.ACCOUNT_ID = bt.PARTY
 LEFT JOIN chart_of_accounts c1 on c1.ACCOUNT_ID = bt.COUNTER_PARTY
 inner join employee em on em.EMPLOYEE_ID=bt.LAST_UPDATE_USER_ID
  union
 select ex.EXPENSE_NO,ex.DATE,ex.DATE,
 ifnull(concat(c1.ACCOUNT_NAME," : ",c1.ACCOUNT_NO),'') AS COUNTER_PARTY,
ex.AS_OF_DATE,c.ACCOUNT_NO,c.ACCOUNT_NAME, 
concat(c.ACCOUNT_NAME,' : ',c.ACCOUNT_NO) AS PARTY,ex.MODE,"Credit",
ex.AMOUNT,ex.BALANCE,concat(em.FIRST_NM,' ',ifnull(em.LAST_NM,'')),ex.COUNTER_PARTY_BALANCE,
ex.REASON,ex.LAST_UPDATE_TS,"Expenses"
 from expenses ex left join chart_of_accounts c on c.ACCOUNT_ID = ex.PARTY_NO
 LEFT JOIN chart_of_accounts c1 on c1.ACCOUNT_ID = ex.COUNTER_PARTY_NO
 inner join employee em on em.EMPLOYEE_ID=ex.LAST_UPDATE_USER_ID
 where ex.MODE="Cheque"
 );
 
SET BASE_SQL=  'select bt.TRANSACTION_REF,
DATE_FORMAT(bt.FROM_TRANSACTION_DATE,"%d-%m-%y") AS FROM_TRANSACTION_DATE,
DATE_FORMAT(bt.TO_TRANSACTION_DATE,"%d-%m-%y") AS TO_TRANSACTION_DATE,
bt.FROM_TRANSACTION_DATE AS TXN_DATE,bt.STATUS,
bt.COUNTER_PARTY,bt.COUNTER_PARTY_BALANCE,DATE_FORMAT(bt.LAST_UPDATE_TS,"%d-%m-%y %h:%i %p") LAST_UPDATE_TS,
bt.ACCOUNT_NO_PARTY,bt.ACCOUNT_NAME_PARTY,bt.PARTY,bt.MODE,bt.TRANSACTION_TYPE,
bt.AMOUNT,bt.BALANCE,bt.SUBMITTED_BY,bt.REASON from bank_transactions_working1 bt';

SET @FINAL_SQL= CONCAT(BASE_SQL,WHERECLAUSE,' order by bt.LAST_UPDATE_TS asc');

PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;

END ;;
DELIMITER ;
