CREATE  PROCEDURE `BANK_TRANSACTION_HISTORY`(
	IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN
DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';

TRUNCATE TABLE bank_transaction_history_working;

insert into bank_transaction_history_working
( select bt.TRANSACTION_REF,bt.TRANSACTION_DATE,bt.TRANSACTION_DATE,
ifnull(concat(c1.ACCOUNT_NAME," : ",c1.ACCOUNT_NO),'') AS COUNTER_PARTY,
c.ACCOUNT_NO,c.ACCOUNT_NAME, 
