bt.REASON,bt.LAST_UPDATE_TS,bt.STATUS
 from bank_transactions_history bt left join chart_of_accounts c on c.ACCOUNT_ID = bt.PARTY
 LEFT JOIN chart_of_accounts c1 on c1.ACCOUNT_ID = bt.COUNTER_PARTY
 inner join employee em on em.EMPLOYEE_ID=bt.LAST_UPDATE_USER_ID);
 
SET BASE_SQL=  'select bt.TRANSACTION_REF,
DATE_FORMAT(bt.FROM_TRANSACTION_DATE,"%d-%m-%y") AS FROM_TRANSACTION_DATE,
DATE_FORMAT(bt.TO_TRANSACTION_DATE,"%d-%m-%y") AS TO_TRANSACTION_DATE,
bt.FROM_TRANSACTION_DATE AS TXN_DATE,bt.STATUS,
bt.COUNTER_PARTY,bt.COUNTER_PARTY_BALANCE,DATE_FORMAT(bt.LAST_UPDATE_TS,"%d-%m-%y %h:%i %p") LAST_UPDATE_TS,
bt.ACCOUNT_NO_PARTY,bt.ACCOUNT_NAME_PARTY,bt.PARTY,bt.MODE,bt.TRANSACTION_TYPE,
