CREATE  PROCEDURE `CHART_OF_ACCOUNTS`(
	IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN
DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';

SET BASE_SQL=  "select at.ACCOUNT_TYPE,
ca.ACCOUNT_NO,ca.ACCOUNT_NAME,
date_format(ca.AS_OF_DATE,'%d-%m-%y') as AS_OF_DATE,
ca.ACCOUNT_NO AS INITIAL,
LPAD((ca.ACCOUNT_NO+9)-RIGHT(ca.ACCOUNT_NO, 1),4,0) AS MAXIMUM,
ca.TRANSACTION_LIMIT,ca.TOTAL_LIMIT,ca.CURRENT_BALANCE from chart_of_accounts ca 
inner join account_type at on at.ACCOUNT_TYPE_ID=ca.ACCOUNT_TYPE";

SET @FINAL_SQL= CONCAT(BASE_SQL,WHERECLAUSE);

PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;

END ;;
