CREATE  PROCEDURE `CONSOLIDATED_STOCK_LIST`(
	IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN
DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';

SET BASE_SQL='select i.ITEM_CD,i.ITEM_NM,st.BATCH_NO,st.EXPIRY_DT,i.RACK_NO,i.SHELF_NO,
sum(st.QUANTITY) AS QUANTITY from stock st 
INNER JOIN items i ON st.ITEM_ID=i.ITEM_ID';
SET @FINAL_SQL= CONCAT(BASE_SQL,WHERECLAUSE,'group by i.ITEM_CD,i.ITEM_NM,st.BATCH_NO,st.EXPIRY_DT,i.RACK_NO,i.SHELF_NO');

PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;

END ;;
