CREATE  PROCEDURE `CREDIT_NOTE_SUMMARY`(
	IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN
DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';

truncate table credit_note_summary_history;
insert into credit_note_summary_history(
select c.credit_note_no,c.credit_date,c.credit_date,
c.PAYMENT_STATUS,
c.amount,"CREDIT NOTE ISSUED",
p.type,c.bill_type_id,c.bill_id,
concat(cu.FIRST_NM," ",cu.LAST_NM),
CONCAT(e.FIRST_NM," ", e.LAST_NM) AS EMP_NM,
CONCAT(emp.FIRST_NM," ", emp.LAST_NM) AS EMP_MODIFIED,c.remarks
from credit_note c 
left join customer cu on c.CUSTOMER_ID=cu.CUSTOMER_ID
inner join payment_types p on p.PAYMENT_TYPE_ID=c.PAYMENT_TYPE_ID
left JOIN employee e on c.APPROVED_BY = e.Employee_ID
left join employee emp on emp.EMPLOYEE_ID=c.LAST_UPDATE_USER_ID
where c.return_type!="Sales Returns"

union 

select c.credit_note_no,c.credit_date,c.credit_date,
c.PAYMENT_STATUS,
c.amount,"SR CREDIT NOTE ISSUED",
p.type,c.bill_type_id,c.bill_id,
concat(cu.FIRST_NM," ",cu.LAST_NM),
CONCAT(e.FIRST_NM," ", e.LAST_NM) AS EMP_NM,
CONCAT(emp.FIRST_NM," ", emp.LAST_NM) AS EMP_MODIFIED,c.remarks
from credit_note c 
left join customer cu on c.CUSTOMER_ID=cu.CUSTOMER_ID
inner join payment_types p on p.PAYMENT_TYPE_ID=c.PAYMENT_TYPE_ID
left JOIN employee e on c.APPROVED_BY = e.Employee_ID
left join employee emp on emp.EMPLOYEE_ID=c.LAST_UPDATE_USER_ID
where c.return_type="Sales Returns"

union

select c.credit_note_no,c.credit_date,c.credit_date,
c.PAYMENT_STATUS,
c.amount,"CREDIT NOTE RECEIVED",
p.type,c.bill_type_id,c.bill_id,
concat(cu.FIRST_NM," ",cu.LAST_NM),
CONCAT(e.FIRST_NM," ", e.LAST_NM) AS EMP_NM,
CONCAT(emp.FIRST_NM," ", emp.LAST_NM) AS EMP_MODIFIED,c.remarks
from credit_note c 
left join customer cu on c.CUSTOMER_ID=cu.CUSTOMER_ID
inner join payment_types p on p.PAYMENT_TYPE_ID=c.PAYMENT_TYPE_ID
left JOIN employee e on c.APPROVED_BY = e.Employee_ID
left join employee emp on emp.EMPLOYEE_ID=c.LAST_UPDATE_USER_ID
where c.PAYMENT_STATUS="Paid"

);

SET BASE_SQL=  'select c.CREDIT_NOTE_NO,c.FROM_CREDIT_DATE,c.TO_CREDIT_DATE,c.PAYMENT_STATUS,
c.AMOUNT,c.STATUS,c.PAYMENT_TYPE,
c.BILL_TYPE,c.BILL_CODE,c.CUSTOMER,c.APPROVED_BY,c.MODIFIED_BY,c.REMARKS from credit_note_summary_history c';

SET @FINAL_SQL= CONCAT(BASE_SQL,WHERECLAUSE);

PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
