/*!50003 DROP PROCEDURE IF EXISTS `CUSTOMER_CREDIT_STATEMENT` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `CUSTOMER_CREDIT_STATEMENT`(WHERECLAUSE VARCHAR(500))
BEGIN
DECLARE BASE_SQL VARCHAR(5000) DEFAULT '';

SET BASE_SQL = 'select ar.MASTER_ACC_NO, ar.CUSTOMER_NAME,
  coalesce(ar.BILL_NO, ar.SOURCE_REF) as BILL_CODE,
  date_format(coalesce(s1.BILL_DATE,s2.BILL_DATE,s3.BILL_DATE,ar.RECEIPT_DATE),"%d-%m-%y") as BILL_DATE,
  datediff(curdate(), coalesce(s1.BILL_DATE,s2.BILL_DATE,s3.BILL_DATE,ar.RECEIPT_DATE)) as DAYS_OWING,
  coalesce(s1.NET_AMOUNT,s2.NET_AMOUNT,s3.NET_AMOUNT) as BILL_TOTAL,
  coalesce(s1.PAID_AMOUNT, s2.PAID_AMOUNT, s3.PAID_AMOUNT, ar.AMOUNT_RECEIVED, 0) as PAID,
  coalesce(s1.BALANCE_AMOUNT, s2.BALANCE_AMOUNT, s3.BALANCE_AMOUNT, ar.AMOUNT_TO_BE_RECEIVED) as OWING,
  coalesce(i.ITEM_NM,"") as ITEM_NM,
  coalesce(si.SALE_QTY,0) as SALE_QTY,
  ma.CREDIT_LIMIT, ma.CREDIT_LIMIT_LEFT
from account_receivables ar
left join sales s1 on s1.BILL_ID = ar.SALES_BILL_ID
left join sales s2 on s2.BILL_CODE = ar.BILL_NO
left join sales s3 on s3.BILL_CODE = ar.SOURCE_REF
left join sales_items si on si.BILL_ID = coalesce(s1.BILL_ID,s2.BILL_ID,s3.BILL_ID)
left join items i on i.ITEM_ID = si.ITEM_ID
left join master_account ma on ma.CREDIT_NUMBER = ar.MASTER_ACC_NO
where ar.SOURCE_TYPE = "Sales Billing"
  and ar.PAYMENT_STATUS in ("Pending","Partially Paid")
  and ar.AMOUNT_TO_BE_RECEIVED > 0
  and coalesce(ar.ACTIVE_S,"Y") = "Y"
  and (coalesce(s1.BILL_ID,s2.BILL_ID,s3.BILL_ID) is null
       or coalesce(s1.BALANCE_AMOUNT,s2.BALANCE_AMOUNT,s3.BALANCE_AMOUNT) > 0)';

-- The caller's filter arrives as " WHERE 1 = 1 AND ...", so its WHERE is
-- replaced with AND to graft it onto the conditions above.
SET @FINAL_SQL = CONCAT(BASE_SQL, ' AND ', SUBSTRING(WHERECLAUSE, 8));

-- Asking by customer name means the customer has no credit account - that is
-- the only way the screen offers them by name, and the search counts only
-- their unaccounted bills under that heading. Without this, a statement for
-- HAWAII DIBA "no credit account" listed 17 bills owing 448,859 when her
-- unaccounted debt is one bill owing 14,864: it swept in everything on her
-- credit account and would have been handed to her as a demand.
IF LOCATE('CUSTOMER_NAME', WHERECLAUSE) > 0 THEN
  SET @FINAL_SQL = CONCAT(@FINAL_SQL,
      ' and (ar.MASTER_ACC_NO is null or ar.MASTER_ACC_NO = "")');
END IF;

SET @FINAL_SQL = CONCAT(@FINAL_SQL, ' order by DAYS_OWING desc, BILL_CODE, ITEM_NM');

PREPARE stmt FROM @FINAL_SQL;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `CUSTOMER_DETAILS` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `CUSTOMER_DETAILS`(
	IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN
DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';
DECLARE CUST_WHERE_CLAUSE  VARCHAR(5000) DEFAULT '';

SET CUST_WHERE_CLAUSE=WHERECLAUSE;   
SET CUST_WHERE_CLAUSE=replace(CUST_WHERE_CLAUSE,'c.STATUS','if(c.ACTIVE_S="Y","Active","De-Active")');

SET BASE_SQL='select c.FIRST_NM,
c.LAST_NM,
c.EMAIL_ID,
c.PHONE_NBR,
c.CREDIT_LIMIT,
c.CREDIT_DAYS,
cm.MEMBERSHIP_CARD_NAME,
cm.MEMBERSHIP_CARD_NO,
date_format(cm.MEMBERSHIP_START_DATE,"%d-%m-%y") as MEMBERSHIP_START_DATE,
date_format(cm.MEMBERSHIP_END_DATE,"%d-%m-%y") as MEMBERSHIP_END_DATE,
cm.MEMBERSHIP_CREDIT_AMOUNT,
cm.MEMBERSHIP_DURATION_IN_MONTHS,
cm.MEMBERSHIP_DISCOUNT_PERCENTAGE,
cm.MEMBERSHIP_BONUS_PERCENTAGE,
ci.INSURANCE_POLICY_CODE,
ci.CUSTOMER_POLICY_NO,
date_format(ci.INSURANCE_POLICY_START,"%d-%m-%y") as INSURANCE_POLICY_START,
date_format(ci.INSURANCE_POLICY_END,"%d-%m-%y") as INSURANCE_POLICY_END,
if(c.ACTIVE_S="Y","Active","De-Active") STATUS from customer c
left join customer_membership cm on cm.CUSTOMER_ID=c.CUSTOMER_ID
left join customer_insurance ci on ci.CUSTOMER_ID=c.CUSTOMER_ID';

SET @FINAL_SQL= CONCAT(BASE_SQL,CUST_WHERE_CLAUSE);

PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `CUSTOMER_MEMBERSHIP_REPORT` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `CUSTOMER_MEMBERSHIP_REPORT`(
	IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN
DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';
DECLARE MEM_WHERE_CLAUSE  VARCHAR(5000) DEFAULT '';

SET MEM_WHERE_CLAUSE=WHERECLAUSE;   
SET MEM_WHERE_CLAUSE=replace(MEM_WHERE_CLAUSE,'cm.STATUS','if(cm.ACTIVE_S="Y","Active","De-Active") ');

SET BASE_SQL='select concat(c.FIRST_NM," ",ifnull(c.LAST_NM," ")) CUSTOMER_NM,
cm.MEMBERSHIP_CARD_NAME,
date_format(cm.MEMBERSHIP_START_DATE,"%d-%m-%y") as MEMBERSHIP_START_DATE,
date_format(cm.MEMBERSHIP_END_DATE,"%d-%m-%y") as MEMBERSHIP_END_DATE,
if(cm.ACTIVE_S="Y","Active","De-Active") STATUS,
cm.MEMBERSHIP_CREDIT_DAYS,
cm.MEMBERSHIP_CREDIT_AMOUNT,
cm.MEMBERSHIP_DURATION_IN_MONTHS,
cm.MEMBERSHIP_BONUS_PERCENTAGE,
cm.MEMBERSHIP_DISCOUNT_PERCENTAGE,
ifnull(round(sum(s.PAID_AMOUNT),2),0) PAID_AMT,
ifnull(round(sum(s.BALANCE_AMOUNT),2),0) BALANCE_AMT
 from customer_membership cm
inner join customer c on c.CUSTOMER_ID=cm.CUSTOMER_ID
left join sales s on s.CUSTOMER_ID=cm.CUSTOMER_ID';

SET @FINAL_SQL= CONCAT(BASE_SQL,MEM_WHERE_CLAUSE,' group by cm.MEMBERSHIP_CARD_NAME,cm.CUSTOMER_ID');


PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `CUSTOMER_STATEMENT` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `CUSTOMER_STATEMENT`(
	IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN

DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';
DECLARE CUST_WHERE_CLAUSE VARCHAR(5000) DEFAULT '';

SET CUST_WHERE_CLAUSE=WHERECLAUSE;  
SET CUST_WHERE_CLAUSE=replace(CUST_WHERE_CLAUSE,'ar.FromDate','ar.APPROVED_DATE');
SET CUST_WHERE_CLAUSE=replace(CUST_WHERE_CLAUSE,'ar.ToDate','ar.APPROVED_DATE');

truncate table customer_statement_working;
insert into customer_statement_working(

select ar.CUSTOMER_NAME,ar.SOURCE_REF,ifnull(ar.PAYMENT_TYPE,"N/A") TYPE,
ar.RECEIPT_DATE as RECEIPT_DATE , 
ar.PAYMENT_STATUS,
CASE 
WHEN ar.SOURCE_TYPE="Credit Note" THEN ifnull(sa.NET_AMOUNT,0)
WHEN ar.SOURCE_TYPE="Sales Billing" THEN s.NET_AMOUNT
WHEN ar.SOURCE_TYPE="Sales Returns - Credit Note" THEN sl.NET_AMOUNT
END AMOUNT_SPENT,
CASE 
WHEN ar.SOURCE_TYPE="Credit Note" THEN sa.PAID_AMOUNT
WHEN ar.SOURCE_TYPE="Sales Billing" THEN s.PAID_AMOUNT
WHEN ar.SOURCE_TYPE="Sales Returns - Credit Note" THEN sl.PAID_AMOUNT
END AMOUNT_RECEIVED,
ar.AMOUNT_TO_BE_RECEIVED as outstanding_amt,
 ar.SOURCE_TYPE,ar.APPROVED_DATE,
 CASE 
WHEN ar.PAYMENT_TYPE='Cash' THEN "N/A"
WHEN ar.PAYMENT_TYPE='Card' THEN ar.CREDIT_CARD_NO
WHEN ar.PAYMENT_TYPE='Cheque' THEN ar.CHEQUE_NUMBER
WHEN ar.PAYMENT_TYPE='MPesa' THEN ar.UPI_PHONE_NO
ELSE "N/A"
END REF_NO,
CASE 
WHEN ar.PAYMENT_TYPE='Cash' THEN "N/A"
WHEN ar.PAYMENT_TYPE='Card' THEN ar.CARD_AUTH_CODE
WHEN ar.PAYMENT_TYPE='Cheque' THEN ar.CHEQUE_DT
WHEN ar.PAYMENT_TYPE='MPesa' THEN ar.UPI_AUTH_CODE
ELSE "N/A"
END AUTH_CODE_DATE,
CASE 
WHEN ar.PAYMENT_TYPE='Cash' THEN ar.CASH_AMOUNT
WHEN ar.PAYMENT_TYPE='Card' THEN ar.CREDIT_CARD_AMOUNT
WHEN ar.PAYMENT_TYPE='Cheque' THEN ar.CHEQUE_AMT
WHEN ar.PAYMENT_TYPE='MPesa' THEN ar.UPI_AMOUNT
ELSE 0
END PAY_TYPE_AMOUNT
from account_receivables ar
left join sales s on ar.SOURCE_REF=s.BILL_CODE
left join credit_note cn on cn.credit_note_no=ar.SOURCE_REF 
left join sales sa on cn.bill_id=sa.BILL_CODE
left join sales_return sr on sr.SALES_RETURN_NO=ar.SOURCE_REF
left join sales sl on sl.BILL_ID=sr.BILL_ID
where ar.PAYMENT_STATUS='Pending' or ar.PAYMENT_STATUS='Cancel' or ar.PAYMENT_STATUS='Paid'

union 

select s.CUSTOMER_NM,s.BILL_CODE,
CASE 
WHEN s.CASH_AMOUNT>=0 THEN "CASH"
WHEN s.CREDIT_AMOUNT>=0 THEN "CREDIT"
WHEN s.UPI_AMOUNT>=0 THEN "M-PESA"
WHEN s.CREDIT_CARD_AMOUNT>=0 THEN "CARD"
WHEN s.CHEQUE_AMT>=0 THEN "CHEQUE"
ELSE " "
END TYPE,
s.BILL_DATE as RECEIPT_DATE , 
s.PAYMENT_STATUS,
s.NET_AMOUNT,
s.PAID_AMOUNT as AMOUNT_RECEIVED,
s.BALANCE_AMOUNT as outstanding_amt,
"Sales Billing",s.BILL_DATE,
CASE 
WHEN s.CASH_AMOUNT>0 THEN "N/A"
WHEN s.CREDIT_AMOUNT>0 THEN s.CREDIT_DAYS
WHEN s.CHEQUE_AMT>0 THEN s.CHEQUE_NUMBER
WHEN s.UPI_AMOUNT>0 THEN s.UPI_PHONE_NO
WHEN s.CREDIT_CARD_AMOUNT>0 THEN CREDIT_CARD_NO
ELSE "N/A"
END REF_NO,
CASE 
WHEN s.CASH_AMOUNT>0 THEN "N/A"
WHEN s.CREDIT_AMOUNT>0 THEN s.CREDIT_ACCOUNT_NO
WHEN s.CHEQUE_AMT>0 THEN s.CHEQUE_DATE
WHEN s.UPI_AMOUNT>0 THEN s.UPI_TRANS_ID
WHEN s.CREDIT_CARD_AMOUNT>0 THEN s.TAXNO
ELSE "N/A"
END AUTH_CODE_DATE,
CASE 
WHEN s.CASH_AMOUNT>0 THEN s.CASH_AMOUNT
WHEN s.CREDIT_AMOUNT>0 THEN s.CREDIT_AMOUNT
WHEN s.CHEQUE_AMT>0 THEN s.CHEQUE_AMT
WHEN s.UPI_AMOUNT>0 THEN s.UPI_AMOUNT
WHEN s.CREDIT_CARD_AMOUNT>0 THEN s.CREDIT_CARD_AMOUNT
ELSE 0
END PAY_TYPE_AMOUNT
from sales s where s.BILL_CODE not in (select ar.SOURCE_REF from account_receivables ar where SOURCE_REF is not null)
and s.PAYMENT_STATUS != "CANCEL" and s.PAYMENT_STATUS != "DUMMY BILL");

SET BASE_SQL=  ' select ar.CUSTOMER_NAME,
ar.BILL_CODE as SOURCE_REF,ifnull(ar.PAYMENT_TYPE,"N/A") TYPE,
date_format(ar.RECEIPT_DATE,"%d-%m-%y") AS RECEIPT_DATE, ar.APPROVED_DATE,
ifnull(ar.PAYMENT_STATUS,"N/A") PAYMENT_STATUS,
ifnull(ar.SOURCE_TYPE,"N/A") SOURCE_TYPE,
date_format(ar.APPROVED_DATE,"%d-%m-%y") as APPROVED_DATE,
ifnull(ar.AMOUNT_SPENT,0) AMOUNT_SPENT,
ifnull(ar.AMOUNT_RECEIVED,0) AMOUNT_RECEIVED,
ifnull(ar.OUTSTANDING_AMT,0) as outstanding_amt,
ar.SOURCE_TYPE,ar.APPROVED_DATE,
ifnull(ar.REF_NO,"N/A") REF_NO,
ifnull(ar.AUTH_CODE_DATE,"N/A") AUTH_CODE_DATE,
ifnull(ar.PAY_TYPE_AMOUNT,0) PAY_TYPE_AMOUNT
 from customer_statement_working ar';


SET @FINAL_SQL= CONCAT(BASE_SQL,CUST_WHERE_CLAUSE,' order by ar.RECEIPT_DATE desc'); 

PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;
 
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
