/*!50003 DROP PROCEDURE IF EXISTS `CUSTOMER_STATEMENT_BY_MASTERACCOUNT` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `CUSTOMER_STATEMENT_BY_MASTERACCOUNT`(
	IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN

DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';
DECLARE CUST_WHERE_CLAUSE VARCHAR(5000) DEFAULT '';

SET CUST_WHERE_CLAUSE=WHERECLAUSE;  
SET CUST_WHERE_CLAUSE=replace(CUST_WHERE_CLAUSE,'ar.FromDate','ar.APPROVED_DATE');
SET CUST_WHERE_CLAUSE=replace(CUST_WHERE_CLAUSE,'ar.ToDate','ar.APPROVED_DATE');
SET CUST_WHERE_CLAUSE=replace(CUST_WHERE_CLAUSE,'ar.CUSTOMER_NAME','ar.MASTER');

truncate table customer_statement_account_working;
insert into customer_statement_account_working(

select ar.CUSTOMER_NAME,concat(cu.FIRST_NM," ",cu.LAST_NM) AS MASTER,
ar.SOURCE_REF,ifnull(ar.PAYMENT_TYPE,"N/A") TYPE,
ar.RECEIPT_DATE as RECEIPT_DATE , 
ar.PAYMENT_STATUS,
CASE 
WHEN ar.SOURCE_TYPE="Credit Note" THEN ifnull(sa.NET_AMOUNT,0)
WHEN ar.SOURCE_TYPE="Sales Billing" THEN s.NET_AMOUNT
WHEN ar.SOURCE_TYPE="Sales Returns - Credit Note" THEN sl.NET_AMOUNT
END AMOUNT_SPENT,
CASE 
WHEN ar.SOURCE_TYPE="Credit Note" THEN sa.PAID_AMOUNT
WHEN ar.SOURCE_TYPE="Sales Billing" THEN s.PAID_AMOUNT
WHEN ar.SOURCE_TYPE="Sales Returns - Credit Note" THEN sl.PAID_AMOUNT
END AMOUNT_RECEIVED,
ar.AMOUNT_TO_BE_RECEIVED as outstanding_amt,
 ar.SOURCE_TYPE,ar.APPROVED_DATE,
 CASE 
WHEN ar.PAYMENT_TYPE='Cash' THEN "N/A"
WHEN ar.PAYMENT_TYPE='Card' THEN ar.CREDIT_CARD_NO
WHEN ar.PAYMENT_TYPE='Cheque' THEN ar.CHEQUE_NUMBER
WHEN ar.PAYMENT_TYPE='MPesa' THEN ar.UPI_PHONE_NO
ELSE "N/A"
END REF_NO,
CASE 
WHEN ar.PAYMENT_TYPE='Cash' THEN "N/A"
WHEN ar.PAYMENT_TYPE='Card' THEN ar.CARD_AUTH_CODE
WHEN ar.PAYMENT_TYPE='Cheque' THEN ar.CHEQUE_DT
WHEN ar.PAYMENT_TYPE='MPesa' THEN ar.UPI_AUTH_CODE
ELSE "N/A"
END AUTH_CODE_DATE,
CASE 
WHEN ar.PAYMENT_TYPE='Cash' THEN ar.CASH_AMOUNT
WHEN ar.PAYMENT_TYPE='Card' THEN ar.CREDIT_CARD_AMOUNT
WHEN ar.PAYMENT_TYPE='Cheque' THEN ar.CHEQUE_AMT
WHEN ar.PAYMENT_TYPE='MPesa' THEN ar.UPI_AMOUNT
ELSE 0
END PAY_TYPE_AMOUNT,ma.CREDIT_NUMBER
from account_receivables ar
left join sales s on ar.SOURCE_REF=s.BILL_CODE
left join credit_note cn on cn.credit_note_no=ar.SOURCE_REF 
left join sales sa on cn.bill_id=sa.BILL_CODE
left join sales_return sr on sr.SALES_RETURN_NO=ar.SOURCE_REF
left join sales sl on sl.BILL_ID=sr.BILL_ID
inner join master_account ma on ma.CREDIT_NUMBER=ar.MASTER_ACC_NO
left join family_account fa on fa.CREDIT_NUMBER=ar.MASTER_ACC_NO 
left join customer cu on ma.CUSTOMER_ID=cu.CUSTOMER_ID
where ar.PAYMENT_STATUS='Pending' or ar.PAYMENT_STATUS='Cancel' or ar.PAYMENT_STATUS='Paid'

union 

select s.CUSTOMER_NM,concat(cu.FIRST_NM," ",cu.LAST_NM) AS MASTER,s.BILL_CODE,
CASE 
WHEN s.CASH_AMOUNT>=0 THEN "CASH"
WHEN s.CREDIT_AMOUNT>=0 THEN "CREDIT"
WHEN s.UPI_AMOUNT>=0 THEN "M-PESA"
WHEN s.CREDIT_CARD_AMOUNT>=0 THEN "CARD"
WHEN s.CHEQUE_AMT>=0 THEN "CHEQUE"
ELSE " "
END TYPE,
s.BILL_DATE as RECEIPT_DATE , 
s.PAYMENT_STATUS,
s.NET_AMOUNT,
s.PAID_AMOUNT as AMOUNT_RECEIVED,
s.BALANCE_AMOUNT as outstanding_amt,
"Sales Billing",s.BILL_DATE,
CASE 
WHEN s.CASH_AMOUNT>0 THEN "N/A"
WHEN s.CREDIT_AMOUNT>0 THEN s.CREDIT_DAYS
WHEN s.CHEQUE_AMT>0 THEN s.CHEQUE_NUMBER
WHEN s.UPI_AMOUNT>0 THEN s.UPI_PHONE_NO
WHEN s.CREDIT_CARD_AMOUNT>0 THEN CREDIT_CARD_NO
ELSE "N/A"
END REF_NO,
CASE 
WHEN s.CASH_AMOUNT>0 THEN "N/A"
WHEN s.CREDIT_AMOUNT>0 THEN s.CREDIT_ACCOUNT_NO
WHEN s.CHEQUE_AMT>0 THEN s.CHEQUE_DATE
WHEN s.UPI_AMOUNT>0 THEN s.UPI_TRANS_ID
WHEN s.CREDIT_CARD_AMOUNT>0 THEN s.TAXNO
ELSE "N/A"
END AUTH_CODE_DATE,
CASE 
WHEN s.CASH_AMOUNT>0 THEN s.CASH_AMOUNT
WHEN s.CREDIT_AMOUNT>0 THEN s.CREDIT_AMOUNT
WHEN s.CHEQUE_AMT>0 THEN s.CHEQUE_AMT
WHEN s.UPI_AMOUNT>0 THEN s.UPI_AMOUNT
WHEN s.CREDIT_CARD_AMOUNT>0 THEN s.CREDIT_CARD_AMOUNT
ELSE 0
END PAY_TYPE_AMOUNT,
ma.CREDIT_NUMBER
from sales s 
inner join master_account ma on ma.CREDIT_NUMBER=s.CREDIT_ACCOUNT_NO
left join family_account fa on fa.CREDIT_NUMBER=s.CREDIT_ACCOUNT_NO 
left join customer cu on ma.CUSTOMER_ID=cu.CUSTOMER_ID
where s.BILL_CODE not in (select ar.SOURCE_REF from account_receivables ar where SOURCE_REF is not null)
and s.PAYMENT_STATUS != "CANCEL" and s.PAYMENT_STATUS != "DUMMY BILL");

SET BASE_SQL=  ' select ar.CUSTOMER_NAME,ar.MASTER,
ar.BILL_CODE as SOURCE_REF,ifnull(ar.PAYMENT_TYPE,"N/A") TYPE,
date_format(ar.RECEIPT_DATE,"%d-%m-%y") AS RECEIPT_DATE, ar.APPROVED_DATE,
ifnull(ar.PAYMENT_STATUS,"N/A") PAYMENT_STATUS,
ifnull(ar.SOURCE_TYPE,"N/A") SOURCE_TYPE,
date_format(ar.APPROVED_DATE,"%d-%m-%y") as APPROVED_DATE,
ifnull(ar.AMOUNT_SPENT,0) AMOUNT_SPENT,
ifnull(ar.AMOUNT_RECEIVED,0) AMOUNT_RECEIVED,
ifnull(ar.OUTSTANDING_AMT,0) as OUTSTANDING_AMT,
ar.SOURCE_TYPE,ar.APPROVED_DATE,
ifnull(ar.REF_NO,"N/A") REF_NO,
ifnull(ar.AUTH_CODE_DATE,"N/A") AUTH_CODE_DATE,
ifnull(ar.PAY_TYPE_AMOUNT,0) PAY_TYPE_AMOUNT,ar.CREDIT_NUMBER
 from customer_statement_account_working ar';
 
SET @FINAL_SQL= CONCAT(BASE_SQL,CUST_WHERE_CLAUSE,' order by ar.RECEIPT_DATE desc'); 

PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;
 
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `DEBIT_NOTE` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb3 */ ;
/*!50003 SET character_set_results = utf8mb3 */ ;
/*!50003 SET collation_connection  = utf8mb3_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `DEBIT_NOTE`(
	IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN
DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';

SET BASE_SQL='select d.debit_note_no,d.debit_date,d.invoice_id,
sp.SP_NAME,d.amount,d.remarks,e.First_NM as approved_by
from debit_note d inner join supplier sp on d.SUPPLIER_ID=sp.SUPPLIER_ID
inner join employee e on e.Employee_ID = d.Approved_By';

SET @FINAL_SQL= CONCAT(BASE_SQL,WHERECLAUSE);

PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `DELIVERY_NOTE` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `DELIVERY_NOTE`(
	IN `WHERECLAUSE` VARCHAR(3000)
)
BEGIN
DECLARE BASE_SQL1  VARCHAR(5000) DEFAULT '';
DECLARE BASE_SQL2  VARCHAR(5000) DEFAULT '';
DECLARE SERVEDBYWHERE  VARCHAR(5000) DEFAULT '';
DECLARE SALEWHERECLAUSE  VARCHAR(5000) DEFAULT '';
set SALEWHERECLAUSE=WHERECLAUSE;

SET SALEWHERECLAUSE=replace(SALEWHERECLAUSE,'s.FROM_BILL_DATE','s.BILL_DATE');
SET SALEWHERECLAUSE=replace(SALEWHERECLAUSE,'s.TO_BILL_DATE','s.BILL_DATE');
set SERVEDBYWHERE= SALEWHERECLAUSE;
set SERVEDBYWHERE = REPLACE(SERVEDBYWHERE,"1 = 1","");
set SERVEDBYWHERE = REPLACE(SERVEDBYWHERE,"WHERE","");

SET BASE_SQL1=  'SELECT 
  i.ITEM_NM, 
  ifnull(si.SALE_QTY,0) SALE_QTY,
  s.LAST_UPDATE_TS,
  ifnull(ROUND(si.UNIT_SALE_PRICE,2),0) MRP,
  ifnull(s.TOTAL_QTY,0) TOTAL_QTY,
  ifnull(si.VAT,0) EFFECTIVE_VAT,
  ifnull(s.TOTAL_PRODUCTS,0) TOTAL_PRODUCTS,
  ifnull(ROUND(s.OVERALL_DISCOUNT,2),0) OVERALL_DISCOUNT,
  ifnull(ROUND(s.TOTAL_AMOUNT,2),0) TOTAL_AMOUNT,
  ifnull(s.NET_AMOUNT,0) NET_AMOUNT,
  ifnull(ROUND(s.PAID_AMOUNT,2),0) PAID_AMOUNT,
  ifnull(s.BALANCE_AMOUNT,0) BALANCE_AMOUNT,
  tc.CATEGORY_CODE AS TAX,
  ifnull(si.VAT,0) VAT,
  ifnull(ROUND(s.VAT_AMT,2),0) VAT_AMT,
  s.BILL_CODE,
   ifnull(s.REMARKS,"-") REMARKS,
  substring_index(s.PAYMENT_STATUS," ",2) AS PAYMENT_STATUS,
  e.FIRST_NM,
  ifnull(concat(p.FIRST_NM," ",substring(p.LAST_NM,1,1)),"N/A") AS DOCTOR_NM,
  substring(ifnull(concat(c.FIRST_NM," ",c.LAST_NM),"N/A"),1,50) AS CUSTOMER_NM,
  ifnull(concat(c.ADDRESS_LINE1," ",c.ADDRESS_LINE2),"N/A") AS CUST_ADDRESS,
  ifnull(ROUND(si.SALE_AMOUNT/si.SALE_QTY,2),0) AS PRICE,
  si.SALE_AMOUNT,
  ROW_NUMBER() OVER (PARTITION BY s.bill_id ORDER BY sales_items_id) AS S_NO,
    (select em.FIRST_NM FROM sales s,employee em where em.EMPLOYEE_ID=s.LAST_UPDATE_USER_ID ';
 SET BASE_SQL2= ') AS SERVED_BY
  FROM sales s 
INNER JOIN sales_items si ON s.BILL_ID = si.BILL_ID
INNER JOIN items i ON i.ITEM_ID = si.ITEM_ID 
inner join customer c on c.CUSTOMER_ID=s.CUSTOMER_ID 
inner join employee e on e.EMPLOYEE_ID=s.EMPLOYEE_ID
inner join provider p on s.PROVIDER_ID=p.PROVIDER_ID
inner join taxcategory tc on tc.TAXCATEGORY_ID=si.TAX_CATEGORY_ID';


SET @FINAL_SQL= CONCAT(BASE_SQL1,SERVEDBYWHERE,BASE_SQL2,SALEWHERECLAUSE);

PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;


END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `DELIVERY_NOTE_DUAL` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `DELIVERY_NOTE_DUAL`(
	IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN
DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';

TRUNCATE TABLE delivery_note_working;

INSERT INTO delivery_note_working 
select DISTINCT s.BILL_CODE,s.BILL_DATE,s.BILL_DATE,s.CUSTOMER_ID,
s.CUSTOMER_NM,
s.PAID_AMOUNT,s.BALANCE_AMOUNT,s.PAYMENT_STATUS,
ifnull(ROUND(s.VAT_AMT,2),0) VAT_AMT,
ifnull(concat(e.FIRST_NM," ",e.LAST_NM),"N/A") AS CREATED_BY,
concat(emp.FIRST_NM , " " , emp.LAST_NM) as MODIFIED_BY from sales s 
INNER JOIN sales_items si ON s.Bill_ID=si.BILL_ID and 
s.PAYMENT_STATUS != "CANCEL" and s.PAYMENT_STATUS != "DUMMY BILL"
inner join customer c on c.CUSTOMER_ID = s.CUSTOMER_ID
inner join employee e on e.EMPLOYEE_ID=s.CREATION_USER_ID
inner join employee emp on emp.EMPLOYEE_ID=s.LAST_UPDATE_USER_ID;

SET BASE_SQL = 'select DISTINCT w.BILL_CODE,
date_format(w.FROM_BILL_DATE,"%d-%m-%y") FROM_BILL_DATE,
date_format(w.TO_BILL_DATE,"%d-%m-%y") TO_BILL_DATE,w.CUSTOMER_NM,w.CREATED_BY,w.MODIFIED_BY,
w.PAID_AMOUNT,round(ifnull(w.VAT_AMT,0),2) AS VAT_AMT,
w.BALANCE_AMOUNT,w.PAYMENT_STATUS from
delivery_note_working w '; 


SET @FINAL_SQL= concat(BASE_SQL,WHERECLAUSE," ORDER BY w.FROM_BILL_DATE DESC");

PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `DUMMY_BILL_LIST` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb3 */ ;
/*!50003 SET character_set_results = utf8mb3 */ ;
/*!50003 SET collation_connection  = utf8mb3_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `DUMMY_BILL_LIST`(
	IN `WHERECLAUSE` VARCHAR(3000)
)
BEGIN
DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';


SET BASE_SQL='select p.FIRST_NM, s.BILL_DATE,s.BILL_CODE,st.EXPIRY_DT,s.CUSTOMER_NM,
si.UNIT_SALE_PRICE,i.ITEM_NM,si.SALE_QTY,m.MFR_NAME,si.BATCH_NO,si.DISCOUNT,
((si.UNIT_SALE_PRICE*si.SALE_QTY)-si.DISCOUNT) AS TOTAL_AMOUNT from sales s 
INNER JOIN provider p ON s.PROVIDER_ID=p.PROVIDER_ID 
 INNER JOIN sales_items si ON s.BILL_ID=si.BILL_ID
 inner join items i on si.ITEM_ID=i.ITEM_ID
 INNER JOIN manufacturer m ON i.MANUFACTURER_ID=m.MANUFACTURER_ID
INNER JOIN stock st ON si.STOCK_ID=st.STOCK_ID ';
SET @FINAL_SQL= CONCAT(BASE_SQL,WHERECLAUSE,'GROUP BY m.MFR_NAME ORDER BY m.MFR_NAME');
PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `DUMMY_SALES_BILL` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `DUMMY_SALES_BILL`(
	IN `WHERECLAUSE` VARCHAR(3000)
)
BEGIN
DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';
DECLARE SALES_WHERE_CLAUSE  VARCHAR(5000) DEFAULT '';

SET SALES_WHERE_CLAUSE=WHERECLAUSE;

SET SALES_WHERE_CLAUSE=replace(SALES_WHERE_CLAUSE,'s.FROM_BILL_DATE','s.BILL_DATE');
SET SALES_WHERE_CLAUSE=replace(SALES_WHERE_CLAUSE,'s.TO_BILL_DATE','s.BILL_DATE');
SET SALES_WHERE_CLAUSE=replace(SALES_WHERE_CLAUSE,'e.EMP_NM','CONCAT(e.FIRST_NM," ", e.LAST_NM)');

SET BASE_SQL='select s.BILL_CODE,s.CUSTOMER_NM,date_format(s.BILL_DATE,"%d-%m-%y") BILL_DATE,i.ITEM_NM,
CONCAT(e.FIRST_NM," ", e.LAST_NM) AS EMP_NM,
if(s.UPI_AMOUNT ,UPI_AMOUNT,0)  UPI_AMOUNT ,
if(s.CASH_AMOUNT,CASH_AMOUNT,0) CASH_AMOUNT ,
if(s.CREDIT_AMOUNT,CREDIT_AMOUNT,0) CREDIT_AMOUNT ,if(s.CHEQUE_AMT,CHEQUE_AMT,0) CHEQUE_AMT ,
if(s.CREDIT_CARD_AMOUNT,CREDIT_CARD_AMOUNT,0) CREDIT_CARD_AMOUNT,
 concat(e.FIRST_NM , " " , e.LAST_NM) as CREATED_BY,
concat(emp.FIRST_NM , " " , emp.LAST_NM) as MODIFIED_BY  from  sales s 
INNER JOIN sales_items si ON s.BILL_ID=si.BILL_ID
 inner join items i on si.ITEM_ID=i.ITEM_ID
inner join employee e on e.EMPLOYEE_ID=s.CREATION_USER_ID
inner join employee emp on emp.EMPLOYEE_ID=s.LAST_UPDATE_USER_ID ';
SET @FINAL_SQL= CONCAT(BASE_SQL,SALES_WHERE_CLAUSE,' and s.PAYMENT_STATUS="Dummy Bill" ');
PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `EXCESS_STOCK_REPORT` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
