CREATE  PROCEDURE `EXPENDITURE_OF_CUSTOMER`(
	IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN
DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';
DECLARE SALES_WHERE_CLAUSE VARCHAR(5000) DEFAULT '';
SET SALES_WHERE_CLAUSE=WHERECLAUSE;
SET SALES_WHERE_CLAUSE=replace(SALES_WHERE_CLAUSE,'ap.FromDate','s.BILL_DATE');
SET SALES_WHERE_CLAUSE=replace(SALES_WHERE_CLAUSE,'ap.ToDate','s.BILL_DATE'); 
SET SALES_WHERE_CLAUSE=replace(SALES_WHERE_CLAUSE,'ap.CUS_NAME','s.CUSTOMER_NM'); 
 
SET BASE_SQL=' SELECT S.BILL_CODE,
date_format(s.BILL_DATE,"%d-%m-%y") BILL_DATE,
S.TOTAL_QTY,
case when PAYMENT_STATUS= "Cancel" then 0
else round(S.TOTAL_AMOUNT,2) end TOTAL_AMOUNT,
case when PAYMENT_STATUS= "Cancel" then 0
else round(s.OVERALL_DISCOUNT,2) end OVERALL_DISCOUNT,
S.PAYMENT_STATUS,
case when PAYMENT_STATUS= "Cancel" then 0
else round(S.PAID_AMOUNT,2) end PAID_AMOUNT,
case when PAYMENT_STATUS= "Cancel" then 0
else round( S.BALANCE_AMOUNT,2) end BALANCE_AMOUNT,
concat(e.FIRST_NM," ",e.LAST_NM) as created_by ,
s.CUSTOMER_NM,
s.CUSTOMER_ID
 FROM ihealthpharm.sales S
 INNER JOIN employee e on e.EMPLOYEE_ID = s.CREATION_USER_ID ';

SET @FINAL_SQL= CONCAT(BASE_SQL,SALES_WHERE_CLAUSE);

PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
