CREATE  PROCEDURE `EXPENSES`(
	IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN
DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';

truncate table expenses_working;

insert into expenses_working(
select ex.DATE,ex.DATE,ex.EXPENSE_NO,concat(c.ACCOUNT_NAME," : ",c.ACCOUNT_NO) AS PARTY,
concat(ca.ACCOUNT_NAME," : ",ca.ACCOUNT_NO) AS COUNTER_PARTY,
ex.MODE,ex.AMOUNT,ex.BALANCE,ex.EXPENSES_REF,ex.REASON,ex.COUNTER_PARTY_BALANCE,
concat(em.FIRST_NM,' ',ifnull(em.LAST_NM,'')),ex.LAST_UPDATE_TS from expenses ex 
inner join chart_of_accounts c on c.ACCOUNT_ID=ex.PARTY_NO 
inner join chart_of_accounts ca on ca.ACCOUNT_ID=ex.COUNTER_PARTY_NO
inner join employee em on em.EMPLOYEE_ID=ex.LAST_UPDATE_USER_ID);

SET BASE_SQL='select DATE_FORMAT(ex.FROM_AS_OF_DATE,"%d-%m-%y") AS FROM_AS_OF_DATE,
DATE_FORMAT(ex.TO_AS_OF_DATE,"%d-%m-%y") AS TO_AS_OF_DATE,ex.FROM_AS_OF_DATE AS TXN_DATE,
ex.EXPENSE_REF_NO,ex.PARTY,ex.COUNTER_PARTY,ex.REASON,
ifnull(ex.COUNTER_PARTY_BALANCE,"N/A") COUNTER_PARTY_BALANCE,
DATE_FORMAT(ex.LAST_UPDATE_TS,"%d-%m-%y %h:%i %p") LAST_UPDATE_TS,
ex.MODE,ex.AMOUNT,ex.BALANCE,ex.REFERENCE,ex.SUBMITTED_BY from expenses_working ex';


SET @FINAL_SQL= CONCAT(BASE_SQL,WHERECLAUSE);

PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
