DELIMITER ;;
CREATE  PROCEDURE `FAST_MOVING_PRODUCT_DETAILS`(
	IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN
DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';
DECLARE SALES_WHERE_CLAUSE  VARCHAR(5000) DEFAULT '';
DECLARE BASE_SQL1  VARCHAR(5000) DEFAULT '';
DECLARE BASE_SQL2  VARCHAR(5000) DEFAULT '';
DECLARE FROM_DATE VARCHAR(5000) DEFAULT '' ;
DECLARE TO_DATE VARCHAR(5000) DEFAULT '' ;
  
DECLARE WHERECLAUSE_STRING VARCHAR(5000) DEFAULT '' ;

SET WHERECLAUSE_STRING=concat('"',WHERECLAUSE,'"');
SET SALES_WHERE_CLAUSE=WHERECLAUSE;

set FROM_DATE=concat('REGEXP_SUBSTR(',WHERECLAUSE_STRING,',','"[0-9]\*-[0-9]\*-[0-9]*")');
set TO_DATE=concat('REVERSE(REGEXP_SUBSTR(REVERSE(',WHERECLAUSE_STRING,")",',','"[0-9]\*-[0-9]\*-[0-9]*"))');

SET SALES_WHERE_CLAUSE=replace(SALES_WHERE_CLAUSE,'s.FROM_DATE','BILL_DATE');
SET SALES_WHERE_CLAUSE=replace(SALES_WHERE_CLAUSE,'s.TO_DATE','BILL_DATE');
 
truncate table fast_moving_sales;

insert into fast_moving_sales
select i.ITEM_NM,i.ITEM_ID,ITEM_CD,sum(si.SALE_QTY) as qty ,si.BATCH_NO,s.BILL_DATE from sales_items si left join  items i on i.ITEM_ID= si .ITEM_ID
left join sales s on s.BILL_ID = si.BILL_ID 
group by i.ITEM_NM;

truncate table fast_moving_stock;

insert into fast_moving_stock
select i.ITEM_NM,sh.ITEM_ID,max(sh.QUANTITY),sh.BATCH_NO from stock_history sh
left join items i  on sh.ITEM_ID = i.ITEM_ID 
group by i.ITEM_NM;

truncate table fast_moving_final;


set BASE_SQL1='insert into fast_moving_final
select fs.ITEM_NM, fs.ITEM_ID,fs.ITEM_CD,fs.qty as sales_qty,s.qty as stock_qty, (fs.qty / datediff( ';
 

set BASE_SQL2=')) as daily_avg ,fs.BILL_DATE,fs.BATCH_NO
from fast_moving_sales fs left join fast_moving_stock s on s.ITEM_ID= fs.ITEM_ID   ';
 

SET BASE_SQL= concat(BASE_SQL1,TO_DATE,',', FROM_DATE,BASE_SQL2);

SET @FINAL_SQL= CONCAT(BASE_SQL); 

PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;

select ITEM_NM,
ITEM_ID,
ITEM_CD,
sales_qty,
stock_qty,
daily_avg,
BATCH_NO,
BILL_DATE,
 round((daily_avg*26),2) as monthly_avg ,
(stock_qty-(daily_avg*26)) as fast_moving 
from fast_moving_final
where stock_qty-(daily_avg*26) >= 0;


END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
