CREATE  PROCEDURE `ITEM_AUDIT_REPORT`(
	IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN

DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';
DECLARE BASE_SQL1  VARCHAR(5000) DEFAULT '';
DECLARE SALES_ITEMS_SQL  VARCHAR(5000) DEFAULT '';
DECLARE SALES_RETURN_ITEMS_SQL  VARCHAR(5000) DEFAULT '';
DECLARE PURCHASE_RETURN_ITEMS_SQL  VARCHAR(5000) DEFAULT '';
DECLARE STOCK_HIS_SQL  VARCHAR(5000) DEFAULT '';
DECLARE INSERT_SQL  VARCHAR(5000) DEFAULT '';
DECLARE EVENT_WHERE_CLAUSE  VARCHAR(5000) DEFAULT '';
DECLARE NEW_WHERE_CLAUSE  VARCHAR(5000) DEFAULT '';
DECLARE SALE_WHERE_CLAUSE  VARCHAR(5000) DEFAULT '';
DECLARE STOCK_HIS_WHERE_CLAUSE  VARCHAR(5000) DEFAULT '';
DECLARE SALE_RETURN_WHERE_CLAUSE VARCHAR(5000) DEFAULT '';
DECLARE PURCHASE_RETURN_WHERE_CLAUSE VARCHAR(5000) DEFAULT '';

SET EVENT_WHERE_CLAUSE=WHERECLAUSE;
SET EVENT_WHERE_CLAUSE=replace(EVENT_WHERE_CLAUSE,'sh.FROM_UPDATED_DATE','sm.CURRENT_STOCK_DATE');
SET EVENT_WHERE_CLAUSE=replace(EVENT_WHERE_CLAUSE,'sh.TO_UPDATED_DATE','sm.CURRENT_STOCK_DATE');
SET EVENT_WHERE_CLAUSE=replace(EVENT_WHERE_CLAUSE,'sh.ITEM_NM','i.ITEM_NM');

SET STOCK_HIS_WHERE_CLAUSE=WHERECLAUSE;
SET STOCK_HIS_WHERE_CLAUSE=replace(STOCK_HIS_WHERE_CLAUSE,'sh.FROM_UPDATED_DATE','date_format(st.LAST_UPDATE_TS,"%y-%m-%d")');
SET STOCK_HIS_WHERE_CLAUSE=replace(STOCK_HIS_WHERE_CLAUSE,'sh.TO_UPDATED_DATE','date_format(st.LAST_UPDATE_TS,"%y-%m-%d")');
SET STOCK_HIS_WHERE_CLAUSE=replace(STOCK_HIS_WHERE_CLAUSE,'sh.ITEM_NM','i.ITEM_NM');


SET NEW_WHERE_CLAUSE=WHERECLAUSE;
SET NEW_WHERE_CLAUSE=replace(NEW_WHERE_CLAUSE,'sh.FROM_UPDATED_DATE','date_format(st.LAST_UPDATE_TS,"%y-%m-%d")');
SET NEW_WHERE_CLAUSE=replace(NEW_WHERE_CLAUSE,'sh.TO_UPDATED_DATE','date_format(st.LAST_UPDATE_TS,"%y-%m-%d")');
SET NEW_WHERE_CLAUSE=replace(NEW_WHERE_CLAUSE,'sh.ITEM_NM','st.ITEM_NM');

SET SALE_WHERE_CLAUSE=WHERECLAUSE;
SET SALE_WHERE_CLAUSE=replace(SALE_WHERE_CLAUSE,'sh.FROM_UPDATED_DATE','date_format(si.LAST_UPDATE_TS,"%y-%m-%d")');
SET SALE_WHERE_CLAUSE=replace(SALE_WHERE_CLAUSE,'sh.TO_UPDATED_DATE','date_format(si.LAST_UPDATE_TS,"%y-%m-%d")');
SET SALE_WHERE_CLAUSE=replace(SALE_WHERE_CLAUSE,'sh.ITEM_NM','i.ITEM_NM');

SET SALE_RETURN_WHERE_CLAUSE=WHERECLAUSE;
SET SALE_RETURN_WHERE_CLAUSE=replace(SALE_RETURN_WHERE_CLAUSE,'sh.FROM_UPDATED_DATE','date_format(sri.LAST_UPDATE_TS,"%y-%m-%d")');
SET SALE_RETURN_WHERE_CLAUSE=replace(SALE_RETURN_WHERE_CLAUSE,'sh.TO_UPDATED_DATE','date_format(sri.LAST_UPDATE_TS,"%y-%m-%d")');
SET SALE_RETURN_WHERE_CLAUSE=replace(SALE_RETURN_WHERE_CLAUSE,'sh.ITEM_NM','i.ITEM_NM');

SET PURCHASE_RETURN_WHERE_CLAUSE=WHERECLAUSE;
SET PURCHASE_RETURN_WHERE_CLAUSE=replace(PURCHASE_RETURN_WHERE_CLAUSE,'sh.FROM_UPDATED_DATE','date_format(pri.LAST_UPDATE_TS,"%y-%m-%d")');
SET PURCHASE_RETURN_WHERE_CLAUSE=replace(PURCHASE_RETURN_WHERE_CLAUSE,'sh.TO_UPDATED_DATE','date_format(pri.LAST_UPDATE_TS,"%y-%m-%d")');
SET PURCHASE_RETURN_WHERE_CLAUSE=replace(PURCHASE_RETURN_WHERE_CLAUSE,'sh.ITEM_NM','i.ITEM_NM');


truncate table stock_movement_detailed_working;

SET BASE_SQL1="insert into stock_movement_detailed_working 
select sm.STOCK_ID,i.ITEM_NM,sm.OPENING_STOCK,ifnull(sm.CLOSING_STOCK,0) CLOSING_STOCK,
sm.CURRENT_STOCK_DATE,sm.EXPIRY_DT from stock_movement_working sm
inner join items i on i.ITEM_ID=sm.ITEM_ID";

SET @FINAL_SQL= CONCAT(BASE_SQL1,EVENT_WHERE_CLAUSE);


PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;


truncate table opening_stock_min_date_working;
insert into opening_stock_min_date_working
select distinct sm.STOCK_ID,sm.ITEM_NM,
ifnull(sm.OPENING_STOCK,0) OPENING_STOCK,
ifnull(sm.CLOSING_STOCK,0) CLOSING_STOCK,sm.CURRENT_STOCK_DATE
from stock_movement_detailed_working sm,
(select min(s.CURRENT_STOCK_DATE) MIN_CURRENT_DATE,s.STOCK_ID FROM stock_movement_detailed_working s
 group by s.STOCK_ID,s.EXPIRY_DT) mindates
where mindates.MIN_CURRENT_DATE=sm.CURRENT_STOCK_DATE and mindates.STOCK_ID=sm.STOCK_ID;

truncate table closing_stock_max_date_working;
insert into closing_stock_max_date_working
select distinct sm.STOCK_ID,sm.ITEM_NM,
ifnull(sm.OPENING_STOCK,0) OPENING_STOCK,
ifnull(sm.CLOSING_STOCK,0) CLOSING_STOCK,
sm.CURRENT_STOCK_DATE
from stock_movement_detailed_working sm,
(select max(s.CURRENT_STOCK_DATE) MAX_CURRENT_DATE,s.STOCK_ID FROM stock_movement_detailed_working s
 group by s.STOCK_ID,s.EXPIRY_DT) maxdates
where maxdates.MAX_CURRENT_DATE=sm.CURRENT_STOCK_DATE and maxdates.STOCK_ID=sm.STOCK_ID;

truncate table sales_items_view_history_audit_working;
SET SALES_ITEMS_SQL="
insert into sales_items_view_history_audit_working
select si.STOCK_ID,i.ITEM_NM,sp.SP_NAME,s.BILL_CODE,st.INVOICE_NO,si.SALE_QTY,
si.UNIT_SALE_PRICE,st.UNIT_PURCHASE_RATE,si.DISCOUNT_PERCENTAGE,
st.PURCHASE_DISCOUNT_PERCENTAGE,
si.VAT,si.QTY_FREE,si.MARGIN,
st.EXPIRY_DT,'Sales Billing',
concat(e.FIRST_NM,' ',e.LAST_NM) EMPLOYEE_NM,
si.LAST_UPDATE_TS from sales_items si 
inner join items i on i.ITEM_ID=si.ITEM_ID
inner join sales s on s.BILL_ID=si.BILL_ID
left join stock st on si.ITEM_ID=st.ITEM_ID and st.STOCK_ID=si.STOCK_ID
left join employee e on e.EMPLOYEE_ID=si.LAST_UPDATE_USER_ID
left join supplier sp on sp.SUPPLIER_ID=st.SUPPLIER_ID";

SET @FINAL_SQL= CONCAT(SALES_ITEMS_SQL,SALE_WHERE_CLAUSE);


PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;

truncate table sales_return_items_view_history_audit_working;
SET SALES_RETURN_ITEMS_SQL="
insert into sales_return_items_view_history_audit_working
select si.STOCK_ID,i.ITEM_NM,sp.SP_NAME,s.BILL_CODE,st.INVOICE_NO,sri.RETURN_QUANTITY,
si.UNIT_SALE_PRICE,st.UNIT_PURCHASE_RATE,si.DISCOUNT_PERCENTAGE,
st.PURCHASE_DISCOUNT_PERCENTAGE,
si.VAT,si.QTY_FREE,si.MARGIN,
st.EXPIRY_DT,'Sales Canceling',
concat(e.FIRST_NM,' ',e.LAST_NM) EMPLOYEE_NM,
sri.LAST_UPDATE_TS from 
 sales_return_item sri 
inner join items i on i.ITEM_ID=sri.ITEM_ID
inner join sales_items si on sri.SALES_ITEM_ID=si.SALES_ITEMS_ID
inner join sales s on s.BILL_ID=si.BILL_ID
left join stock st on si.ITEM_ID=st.BILL_ID and st.STOCK_ID=si.STOCK_ID 
left join employee e on e.EMPLOYEE_ID=sri.LAST_UPDATE_USER_ID
left join supplier sp on sp.SUPPLIER_ID=st.SUPPLIER_ID";

SET @FINAL_SQL= CONCAT(SALES_RETURN_ITEMS_SQL,SALE_RETURN_WHERE_CLAUSE);


PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;

truncate table purchase_return_items_view_history_audit_working;
SET PURCHASE_RETURN_ITEMS_SQL="insert into purchase_return_items_view_history_audit_working
select st.STOCK_ID,i.ITEM_NM,sp.SP_NAME,'N/A',inv.INVOICE_NO,pri.RETURN_QUANTITY,
st.UNIT_SALE_RATE,st.UNIT_PURCHASE_RATE,st.SALE_DISCOUNT_PERCENTAGE,
st.PURCHASE_DISCOUNT_PERCENTAGE,
tc.CATEGORY_VALUE,pri.BONUS_QUANTITY,st.MARGIN,
st.EXPIRY_DT,'Purchase Return',
concat(e.FIRST_NM,' ',e.LAST_NM) EMPLOYEE_NM,
pri.LAST_UPDATE_TS from purchase_return_item pri 
inner join purchase_return pr on pr.PURCHASE_RETURN_ID=pri.PURCHASE_RETURN_ID
inner join invoice inv on inv.INVOICE_ID=pr.INVOICE_ID
inner join items i on i.ITEM_ID=pri.ITEM_ID
left join stock st on inv.INVOICE_NO=st.INVOICE_NO
left join employee e on e.EMPLOYEE_ID=pri.LAST_UPDATE_USER_ID
left join supplier sp on sp.SUPPLIER_ID=inv.SUPPLIER_ID
left join taxcategory tc on tc.TAXCATEGORY_ID=st.TAX_CATEGORY_ID";

SET @FINAL_SQL= CONCAT(PURCHASE_RETURN_ITEMS_SQL,PURCHASE_RETURN_WHERE_CLAUSE);


PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;

truncate table stock_history_detailed_audit_working;
SET STOCK_HIS_SQL="
insert into stock_history_detailed_audit_working
select st.STOCK_ID,i.ITEM_NM,sp.SP_NAME,'N/A',st.INVOICE_NO,st.QUANTITY,
st.UNIT_SALE_RATE,st.UNIT_PURCHASE_RATE,st.SALE_DISCOUNT_PERCENTAGE,
st.PURCHASE_DISCOUNT_PERCENTAGE,
tc.CATEGORY_VALUE,st.BONUS,st.MARGIN,
st.EXPIRY_DT,st.ENTRY_TYPE,
concat(e.FIRST_NM,' ',e.LAST_NM) EMPLOYEE_NM,
st.LAST_UPDATE_TS from stock_history st
inner join items i on i.ITEM_ID=st.ITEM_ID
inner join stock s on s.STOCK_ID=st.STOCK_ID
left join employee e on e.EMPLOYEE_ID=st.LAST_UPDATE_USER_ID
left join supplier sp on sp.SUPPLIER_ID=st.SUPPLIER_ID
left join taxcategory tc on tc.TAXCATEGORY_ID=s.TAX_CATEGORY_ID";

SET @FINAL_SQL= CONCAT(STOCK_HIS_SQL,STOCK_HIS_WHERE_CLAUSE," and st.ENTRY_TYPE!='Sales Billing' 
and st.ENTRY_TYPE!='Sales Canceling' and st.QUANTITY!=0 and st.ENTRY_TYPE!='Purchase Return'", 
" group by st.stock_id,st.entry_type");


PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;

truncate table stock_history_view_audit_working;

insert into stock_history_view_audit_working
select * from sales_items_view_history_audit_working
union 
select * from sales_return_items_view_history_audit_working
union
select * from purchase_return_items_view_history_audit_working
union 
select * from stock_history_detailed_audit_working;

SET BASE_SQL="
select st.ITEM_NM,st.BILL_CODE,st.STOCK_ID,st.INVOICE_NO,
ifnull(st.QUANTITY,0) QUANTITY,ifnull(round(st.UNIT_SALE_RATE,2),0) UNIT_SALE_RATE,
ifnull((select sum(os.opening_stock) from opening_stock_min_date_working os where os.stock_id=st.stock_id
group by st.stock_id,st.expiry_dt),0) OPENING_STOCK,
ifnull(round(st.UNIT_PURCHASE_RATE,2),0) UNIT_PURCHASE_RATE,
ifnull(round(st.SALE_DISCOUNT_PERCENTAGE,2),0) SALE_DISCOUNT_PERCENTAGE,
ifnull(round(st.PURCHASE_DISCOUNT_PERCENTAGE,2),0) PURCHASE_DISCOUNT_PERCENTAGE,
ifnull(st.VAT,0) VAT,ifnull(st.BONUS,0) BONUS,
ifnull(round(st.MARGIN,2),'N/A') MARGIN,
round(ifnull(st.QUANTITY,0) * st.UNIT_SALE_RATE * ( 1 - ifnull(st.SALE_DISCOUNT_PERCENTAGE,0)/100) * 
ifnull(( 1 + st.VAT/100),0),2) as SALE_PRICE,
round(ifnull(st.QUANTITY,0) * st.UNIT_PURCHASE_RATE * ( 1 - ifnull(st.PURCHASE_DISCOUNT_PERCENTAGE,0)/100) * 
ifnull(( 1 + st.VAT/100),0),2) as PURCHASE_PRICE,
date_format(st.EXPIRY_DT,'%d-%m-%y') EXPIRY_DT,
st.ENTRY_TYPE,ifnull(st.SUPPLIER_NM,'N/A') SP_NAME,
ifnull(st.LAST_UPDATE_USER,'N/A') LAST_UPDATE_USER,
date_format(st.LAST_UPDATE_TS,'%d-%m-%y %h:%i %p') LAST_UPDATE_TS from stock_history_view_audit_working st
";
SET @FINAL_SQL= CONCAT(BASE_SQL,NEW_WHERE_CLAUSE,' and st.EXPIRY_DT is not null',' order by st.ITEM_NM,st.LAST_UPDATE_TS ASC');

PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;


END ;;
DELIMITER ;
