/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `ITEM_MOVEMENT_REPORT`(
	IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN
DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';
DECLARE INSERT_SQL  VARCHAR(5000) DEFAULT '';
DECLARE NEW_WHERE_CLAUSE  VARCHAR(5000) DEFAULT '';

SET NEW_WHERE_CLAUSE=WHERECLAUSE;
SET NEW_WHERE_CLAUSE=replace(NEW_WHERE_CLAUSE,'sh.FROM_UPDATED_DATE','st.CURRENT_STOCK_DATE');
SET NEW_WHERE_CLAUSE=replace(NEW_WHERE_CLAUSE,'sh.TO_UPDATED_DATE','st.CURRENT_STOCK_DATE');
SET NEW_WHERE_CLAUSE=replace(NEW_WHERE_CLAUSE,'sh.ITEM_NM','i.ITEM_NM');
SET NEW_WHERE_CLAUSE=replace(NEW_WHERE_CLAUSE,'sh.LAST_UPDATE_USER','concat(e.FIRST_NM," ",e.LAST_NM)');


SET BASE_SQL="select i.ITEM_NM,
CASE 
WHEN (st.ENTRY_TYPE='Sales Billing' or st.ENTRY_TYPE='Sales Canceling') THEN sl.BILL_CODE
ELSE 'N/A'
END BILL_CODE,
ifnull(st.INVOICE_NO,'N/A') INVOICE_NO,
ifnull(sum(st.OPENING_STOCK),0) OPENING_STOCK,
ifnull(sum(st.CLOSING_STOCK),0) CLOSING_STOCK,
ifnull(st.UNIT_SALE_RATE,0) UNIT_SALE_RATE,  
round(ifnull(st.UNIT_PURCHASE_RATE,0),2) UNIT_PURCHASE_RATE,
ifnull(st.PURCHASE_DISCOUNT_PERCENTAGE,0) AS P_DISC,
ifnull(tc.CATEGORY_VALUE,0) AS TAX,
round(ifnull(sum(st.OPENING_STOCK),0) * st.UNIT_PURCHASE_RATE * ( 1 - ifnull(st.PURCHASE_DISCOUNT_PERCENTAGE,0)/100) * 
ifnull(( 1 + tc.CATEGORY_VALUE/100),0),2) as OPENING_BALANCE,
round(ifnull(sum(st.CLOSING_STOCK),0) * st.UNIT_PURCHASE_RATE * ( 1 - ifnull(st.PURCHASE_DISCOUNT_PERCENTAGE,0)/100) * 
ifnull(( 1 + tc.CATEGORY_VALUE/100),0),2) as CLOSING_BALANCE,
date_format(st.EXPIRY_DT,'%d-%m-%y') EXPIRY_DT,concat(e.FIRST_NM,' ',e.LAST_NM) LAST_UPDATE_USER,
sp.SP_NAME,date_format(st.LAST_UPDATE_TS,'%d-%m-%y %h:%i %p') LAST_UPDATE_TS,
st.ENTRY_TYPE,date_format(st.CURRENT_STOCK_DATE,'%d-%m-%y') OP_CL_STOCK_DATE,
st.CURRENT_STOCK_DATE
 from stock_movement_working st 
inner join items i on i.ITEM_ID = st.ITEM_ID 
left join employee e on e.EMPLOYEE_ID=st.CREATION_USER_ID
inner join supplier sp on sp.SUPPLIER_ID=st.SUPPLIER_ID
left join taxcategory tc on st.TAX_CATEGORY_ID=tc.TAXCATEGORY_ID
left join sales_items si on st.BILL_ID=si.BILL_ID
left join sales sl on sl.BILL_ID=si.BILL_ID";

SET @FINAL_SQL= CONCAT(BASE_SQL,NEW_WHERE_CLAUSE,' group by i.ITEM_NM,st.EXPIRY_DT',' order by st.CURRENT_STOCK_DATE DESC');


PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `LABEL_INSTRUCTION` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `LABEL_INSTRUCTION`(
	IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN
DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';

SET BASE_SQL='SELECT ii.ITEM_NM,ii.ITEM_QTY,ii.EXPIRY_DT,
SUBSTRING_INDEX(ii.CUSTOMER_NM, " ", 2) AS CUSTOMER_NM,
f.FORMULATION_NAME,ii.INSTRUCTIONS FROM item_instructions_working ii
 inner join formulation_instructions f on f.FORMULATION_INSTRUCTION_ID=ii.FORMULATION_ID';

SET @FINAL_SQL= CONCAT(BASE_SQL,WHERECLAUSE);

PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;
truncate table item_instructions_working;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `MANUFACTURER_WISE_SALES` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb3 */ ;
/*!50003 SET character_set_results = utf8mb3 */ ;
/*!50003 SET collation_connection  = utf8mb3_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `MANUFACTURER_WISE_SALES`(
	IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN
DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';

SET BASE_SQL='select distinct sv.BILL_ID,i.ITEM_CD,sv.FromDate,sv.ToDate,i.ITEM_NM,
si.SALE_QTY,si.UNIT_SALE_PRICE,(si.UNIT_SALE_PRICE*si.SALE_QTY) AS SUB_TOTAL,si.DISCOUNT,
((si.UNIT_SALE_PRICE*si.SALE_QTY)-si.DISCOUNT) AS TOTAL_AMOUNT,si.BATCH_NO  from sales_view sv
INNER JOIN sales_items si ON sv.BILL_ID=si.BILL_ID
INNER JOIN items i ON si.ITEM_ID=i.ITEM_ID';
SET @FINAL_SQL= CONCAT(BASE_SQL,WHERECLAUSE,'ORDER BY sv.FromDate');

PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;

END ;;
DELIMITER ;
