CREATE  PROCEDURE `MASTER_ACCOUNT_HISTORY`(
	IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN 
DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';
DECLARE BASE_SQL_ONE  VARCHAR(5000) DEFAULT '';
DECLARE SALES_WHERE_CLAUSE VARCHAR(5000) DEFAULT '';

SET SALES_WHERE_CLAUSE=WHERECLAUSE;  
SET SALES_WHERE_CLAUSE=replace(SALES_WHERE_CLAUSE,'ma.FROM_UPDATED_DATE','ma.LAST_UPDATE_TS');
SET SALES_WHERE_CLAUSE=replace(SALES_WHERE_CLAUSE,'ma.TO_UPDATED_DATE','ma.LAST_UPDATE_TS');
SET SALES_WHERE_CLAUSE=replace(SALES_WHERE_CLAUSE,'ma.MASTER_NAME','CONCAT(c.FIRST_NM," ", c.LAST_NM)');
SET SALES_WHERE_CLAUSE=replace(SALES_WHERE_CLAUSE,'ma.FAMILY_NAME','CONCAT(c.FIRST_NM," ", c.LAST_NM)');
 
  
SET BASE_SQL=' SELECT ma.CREDIT_NUMBER,
concat(c.FIRST_NM," ",c.LAST_NM) as CUSTOMER_NM ,
ma.CREDIT_NUMBER,
ma.CREDIT_LIMIT,
ma.CREDIT_DAYS,
ma.CREDIT_DAYS_LEFT,
ma.CREDIT_LIMIT_LEFT,
ma.ENTRY_TYPE,
ifnull(ma.SALES_BILL_NO,"N/A") AS SALES_BILL_NO,
ma.CREATION_TS,
date_format(ma.CREATION_TS,"%d-%m-%y") as CREATION_DT,
date_format(ma.LAST_UPDATE_TS,"%d-%m-%y") as UPDATED_DT,
ma.LAST_UPDATE_TS 
FROM master_account_history ma 
left join customer c on ma.CUSTOMER_ID=c.CUSTOMER_ID 
'; 


SET @FINAL_SQL= CONCAT(BASE_SQL,SALES_WHERE_CLAUSE);

PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;
END ;;
