CREATE  PROCEDURE `MINIMUM_STOCK_REORDER_LEVEL`(
	IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN
DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';

TRUNCATE TABLE  min_stock_working;

insert into min_stock_working
select b.ITEM_ID, b.ITEM_NM  , sum(a.QUANTITY) AS STOCK_LEVEL, sum(a.QUANTITY) AS 	QTY_BREAKUP , ifnull(b.REORDER_LEVEL,0) as REORDER_LEVEL, 
ifnull(b.REORDER_QTY, 0) as REORDER_QTY, ifnull(a.UNIT_PURCHASE_RATE,0) as UNIT_PURCHASE_RATE,
ifnull(a.PURCHASE_DISCOUNT_PERCENTAGE,0) as PURCHASE_DISCOUNT_PERCENTAGE , a.SUPPLIER_ID, SP_NAME
 from stock a
 inner join items b on  a.ITEM_ID = b.ITEM_ID and a.Quantity != 0
 inner join supplier s on s.SUPPLIER_ID = a.SUPPLIER_ID
group by a.ITEM_ID, ITEM_NM,b.REORDER_LEVEL, b.REORDER_QTY,a.UNIT_PURCHASE_RATE, a.UNIT_PURCHASE_RATE,
 a.SUPPLIER_ID, SP_NAME
having sum(a.Quantity) <= ifnull(b.Reorder_Level,0);

set sql_safe_updates = 0;


update min_stock_working a, (select b.ITEM_ID, sum(b.Stock_Level) as STOCK
from min_stock_working b group by b.ITEM_ID)  b
set a.STOCK_LEVEL = b.STOCK
where a.ITEM_ID = b.ITEM_ID;


SET BASE_SQL='select a.ITEM_NM , a.STOCK_LEVEL, a.QTY_BREAKUP , a.REORDER_LEVEL, 
 a.REORDER_QTY, a.UNIT_PURCHASE_RATE as P_RATE,
a.PURCHASE_DISCOUNT_PERCENTAGE as P_DISCOUNT,a.SP_NAME from min_stock_working a
';

SET @FINAL_SQL= CONCAT(BASE_SQL,'  order by 1,7,8');


PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;

END ;;
DELIMITER ;
