CREATE  PROCEDURE `OUTSTANDING_PAYABLES`(
	IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN
DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';
DECLARE AP_WHERE_CLAUSE VARCHAR(5000) DEFAULT '';

SET AP_WHERE_CLAUSE=WHERECLAUSE;   
SET AP_WHERE_CLAUSE=replace(AP_WHERE_CLAUSE,'ap.FROM_INVOICE_DATE','DATE_FORMAT(ap.CREATION_TS,"%y-%m-%d")');
SET AP_WHERE_CLAUSE=replace(AP_WHERE_CLAUSE,'ap.TO_INVOICE_DATE','DATE_FORMAT(ap.CREATION_TS,"%y-%m-%d")');

SET BASE_SQL='select ap.SUPPLIER_NAME,ap.PAYMENT_NO,ap.SOURCE_REF,ap.INVOICE_NO,
ap.STATUS,ifnull(inv.CREDIT_DAYS,"N/A") CREDIT_DAYS,
ifnull(inv.INVOICE_AMOUNT,0) INVOICE_AMOUNT,ifnull(ap.TOTAL_AMOUNT_PAID,0) TOTAL_AMOUNT_PAID,
ifnull(ap.TOTAL_AMOUNT_TO_BE_PAID,0) TOTAL_AMOUNT_TO_BE_PAID,
date_format(ap.PAYMENT_DATE,"%d-%m-%y") as PAYMENT_DATE,
ap.PAYMENT_STATUS,ap.SOURCE_TYPE,concat(ae.FIRST_NM," ",ae.LAST_NM) APPROVED_BY,
date_format(ap.APPROVED_DATE,"%d-%m-%y") APPROVED_DATE,
concat(e.FIRST_NM , " " , e.LAST_NM) as CREATED_BY,
date_format(ap.CREATION_TS,"%d-%m-%y %h:%i %p") CREATION_TS,
DATE_FORMAT(ap.CREATION_TS,"%y-%m-%d") from account_payables ap
inner join invoice inv on inv.INVOICE_NO=ap.INVOICE_NO
inner join employee e on e.EMPLOYEE_ID=ap.CREATION_USER_ID
left join employee ae on inv.APPROVED_BY=ae.EMPLOYEE_ID';

SET @FINAL_SQL= CONCAT(BASE_SQL,AP_WHERE_CLAUSE);

PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;

END ;;
DELIMITER ;
