CREATE  PROCEDURE `OUTSTANDING_RECEIVABLES`(
	IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN
DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';
DECLARE CUST_WHERE_CLAUSE  VARCHAR(5000) DEFAULT '';

SET CUST_WHERE_CLAUSE=WHERECLAUSE;   
SET CUST_WHERE_CLAUSE=replace(CUST_WHERE_CLAUSE,'ma.MASTER','concat(cu.FIRST_NM," ",cu.LAST_NM)');
SET CUST_WHERE_CLAUSE=replace(CUST_WHERE_CLAUSE,'fa.FAMILY','ar.CUSTOMER_NAME');
SET CUST_WHERE_CLAUSE=replace(CUST_WHERE_CLAUSE,'ar.FROM_BILL_DATE','ar.RECEIPT_DATE');
SET CUST_WHERE_CLAUSE=replace(CUST_WHERE_CLAUSE,'ar.TO_BILL_DATE','ar.RECEIPT_DATE');

SET BASE_SQL='select distinct ar.RECEIPT_NO,ar.CUSTOMER_NAME,concat(cu.FIRST_NM," ",cu.LAST_NM) AS MASTER,
s.NET_AMOUNT,
date_format(ar.RECEIPT_DATE,"%d-%m-%y") as RECEIPT_DATE,
ar.SOURCE_TYPE,ar.SOURCE_REF,
ifnull(ar.AMOUNT_RECEIVED,0) AMOUNT_RECEIVED,
CASE 
WHEN ar.PAYMENT_STATUS="Cancel" THEN (-1*(s.NET_AMOUNT-s.PAID_AMOUNT))
ELSE ar.AMOUNT_TO_BE_RECEIVED
END AMOUNT_TO_BE_RECEIVED,
ar.PAYMENT_STATUS,
ar.MASTER_ACC_NO,ma.CREDIT_DAYS,ma.CREDIT_LIMIT,ma.CREDIT_DAYS_LEFT,
ma.CREDIT_LIMIT_LEFT,ar.SOURCE_REF
from account_receivables ar
inner join sales s on ar.SOURCE_REF=s.BILL_CODE and s.CUSTOMER_NM=ar.CUSTOMER_NAME 
inner join master_account ma on ma.CREDIT_NUMBER=ar.MASTER_ACC_NO
left join family_account fa on fa.CREDIT_NUMBER=ar.MASTER_ACC_NO 
left join customer cu on ma.CUSTOMER_ID=cu.CUSTOMER_ID';

SET @FINAL_SQL= CONCAT(BASE_SQL,CUST_WHERE_CLAUSE);

PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;

END ;;
DELIMITER ;
