CREATE  PROCEDURE `OVER_STOCK_REORDER_LEVEL_REPORT`(
	IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN
DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';
DECLARE SALES_WHERE_CLAUSE  VARCHAR(5000) DEFAULT '';
DECLARE BASE_SQL1  VARCHAR(5000) DEFAULT '';
DECLARE BASE_SQL2  VARCHAR(5000) DEFAULT '';
DECLARE FROM_DATE VARCHAR(5000) DEFAULT '' ;
DECLARE TO_DATE VARCHAR(5000) DEFAULT '' ;

DECLARE WHERECLAUSE_STRING VARCHAR(5000) DEFAULT '' ;

SET WHERECLAUSE_STRING=concat('"',WHERECLAUSE,'"');
SET SALES_WHERE_CLAUSE=WHERECLAUSE;

set FROM_DATE=concat('REGEXP_SUBSTR(',WHERECLAUSE_STRING,',','"[0-9]\*-[0-9]\*-[0-9]*")');
set TO_DATE=concat('REVERSE(REGEXP_SUBSTR(REVERSE(',WHERECLAUSE_STRING,")",',','"[0-9]\*-[0-9]\*-[0-9]*"))');


SET SALES_WHERE_CLAUSE=replace(SALES_WHERE_CLAUSE,'s.FROM_DATE','s.BILL_DATE');
SET SALES_WHERE_CLAUSE=replace(SALES_WHERE_CLAUSE,'s.TO_DATE','s.BILL_DATE');

truncate table over_stock_working_sales;
truncate table over_stock_working_stock;

set BASE_SQL1='insert into over_stock_working_sales 
select distinct si.ITEM_ID,i.ITEM_NM,ifnull(i.REORDER_LEVEL,0) AS REORDER_LEVEL,
ifnull(i.REORDER_QTY,0) AS REORDER_QTY,0 AS QTY,
round(sum(si.SALE_QTY)/datediff(';


set BASE_SQL2='),2) as SALE_AVG
 from sales_items si
inner join sales s on si.BILL_ID=s.BILL_ID
inner join items i on i.ITEM_ID=si.ITEM_ID ';

SET BASE_SQL= concat(BASE_SQL1,TO_DATE,',', FROM_DATE,BASE_SQL2);

SET @FINAL_SQL= CONCAT(BASE_SQL,SALES_WHERE_CLAUSE,' group by si.ITEM_ID, i.ITEM_NM,i.REORDER_LEVEL,i.REORDER_QTY '); 


DROP  INDEX  ihp_stock_quantity_idx on stock;
CREATE INDEX ihp_stock_quantity_idx on stock (quantity);
PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;

insert into over_stock_working_stock
select s.ITEM_ID,i.ITEM_NM,ifnull(i.REORDER_LEVEL,0) as REORDER_LEVEL,
ifnull(i.REORDER_QTY,0) as REORDER_QTY,sum(Quantity) as QTY, 0 as SALE_AVG,
i.ITEM_CD,s.PACK
from stock s, items i where s.ITEM_ID = i.ITEM_ID
and QUANTITY != 0
group by s.ITEM_ID,i.ITEM_NM,i.REORDER_LEVEL,
i.REORDER_QTY;

select distinct st.ITEM_ID,st.ITEM_NM,st.REORDER_LEVEL,
st.REORDER_QTY,st.QTY, ifnull(s.SALE_AVG,0) as SALE_AVG,
st.ITEM_CD,st.PACK
from over_stock_working_stock st
left join over_stock_working_sales s
on st.Item_ID = s.Item_ID 
where st.QTY >= (2 * s.SALE_AVG) + ( select ifnull(d.REORDER_LEVEL,0) 
from items d where d.ITEM_ID = st.ITEM_ID) order by 2;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
