CREATE  PROCEDURE `PETTY_CASH_EXPENDITURE`(
	IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN
DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';

truncate table petty_cash_expenditure;

insert into petty_cash_expenditure(
select ifnull(concat(ca.ACCOUNT_NAME," : ",ca.ACCOUNT_NO),''),
ifnull(bt.REASON,"N/A") ,
ifnull(concat(cao.ACCOUNT_NAME," : ",cao.ACCOUNT_NO),''),
bt.AMOUNT,
bt.BALANCE,bt.TRANSACTION_DATE,bt.TRANSACTION_DATE,
bt.CREATION_TS,bt.LAST_UPDATE_TS,
concat(em.FIRST_NM,' ',ifnull(em.LAST_NM,'')),bt.COUNTER_PARTY_BALANCE,bt.TRANSACTION_REF from bank_transactions bt  
inner join employee em on em.EMPLOYEE_ID=bt.LAST_UPDATE_USER_ID
left join chart_of_accounts ca on ca.ACCOUNT_ID=bt.PARTY
left join chart_of_accounts cao on cao.ACCOUNT_ID=bt.COUNTER_PARTY
where ca.ACCOUNT_NO=6100 or cao.ACCOUNT_NO=6100

union

select ifnull(concat(ca.ACCOUNT_NAME," : ",ca.ACCOUNT_NO),''),
ifnull(ex.REASON,"N/A") ,
ifnull(concat(cao.ACCOUNT_NAME," : ",cao.ACCOUNT_NO),''),
ex.AMOUNT,
ex.BALANCE,ex.DATE,ex.DATE,
ex.CREATION_TS,ex.LAST_UPDATE_TS,
concat(em.FIRST_NM,' ',ifnull(em.LAST_NM,'')),
ex.COUNTER_PARTY_BALANCE,ex.EXPENSE_NO from expenses ex  
inner join employee em on em.EMPLOYEE_ID=ex.LAST_UPDATE_USER_ID
left join chart_of_accounts ca on ca.ACCOUNT_ID=ex.PARTY_NO
left join chart_of_accounts cao on cao.ACCOUNT_ID=ex.COUNTER_PARTY_NO
where ca.ACCOUNT_NO=6100 or cao.ACCOUNT_NO=6100);

SET BASE_SQL='select pe.PARTY,pe.CREATION_TS,pe.LAST_UPDATE_TS,
pe.REFERENCE,pe.COUNTER_PARTY,pe.AMOUNT,pe.FROM_AS_OF_DATE AS TXN_DATE,
pe.BALANCE,DATE_FORMAT(pe.FROM_AS_OF_DATE,"%d-%m-%y") AS FROM_DATE,
DATE_FORMAT(pe.TO_AS_OF_DATE,"%d-%m-%y") as TO_AS_OF_DATE,
pe.LAST_UPDATE_USER AS SUBMITTED_BY,pe.REF_NO,
ifnull(pe.COUNTER_PARTY_BALANCE,"N/A") COUNTER_PARTY_BALANCE from  petty_cash_expenditure pe
left join chart_of_accounts ca on ca.ACCOUNT_NO=pe.PARTY
left join chart_of_accounts cao on cao.ACCOUNT_NO=pe.Counter_Party';

SET @FINAL_SQL= CONCAT(BASE_SQL,WHERECLAUSE,' order by pe.CREATION_TS asc');

PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;



END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
