CREATE  PROCEDURE `PRINT_QUOTATION_RECEIPT`(
	IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN
DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';
DECLARE QTN_WHERE_CLAUSE VARCHAR(5000) DEFAULT '';

SET @count:=0;
SET QTN_WHERE_CLAUSE=WHERECLAUSE;   
SET QTN_WHERE_CLAUSE=replace(QTN_WHERE_CLAUSE,'q.FROM_QTN_DATE','q.QUOTATION_DT');
SET QTN_WHERE_CLAUSE=replace(QTN_WHERE_CLAUSE,'q.TO_QTN_DATE','q.QUOTATION_DT');
SET QTN_WHERE_CLAUSE=replace(QTN_WHERE_CLAUSE,'qi.CREATED_BY','concat(e.FIRST_NM," ",e.LAST_NM)');

SET BASE_SQL='select q.QUOTATION_NO,
date_format(q.QUOTATION_DT,"%d-%m-%y") QUOTATION_DT,
i.ITEM_NM,qi.QUANTITY,qi.STATUS,sp.SP_NAME,
concat(sp.ADDRESS_LINE1," ",sp.ADDRESS_LINE2) AS ADDRESS,
ifnull(sp.PHONE_NBR,"N/A") AS PHONE_NBR,concat(er.FIRST_NM," ",er.LAST_NM) REQUESTED_BY,
0 AS DISCOUNT_PERCENTAGE,
0 AS UNIT_PURCHASE_PRICE,
tc.CATEGORY_CODE,
concat(e.FIRST_NM," ",e.LAST_NM) CREATED_BY,
0 AS VAT_PER,q.REMARKS,
concat(emp.FIRST_NM," ",emp.LAST_NM) MODIFIED_BY,
ifnull(qi.BONUS,0) as BONUS,
0 AS TOTAL_VALUE,
0 AS DISCOUNT_AMT,
0 AS VAT_AMT,
date_format(qi.CREATION_TS,"%d-%m-%y %h:%i %p") CREATION_TS,
(@count:=@count+1) AS S_NO 
from quotation_items qi
inner join quotation q on q.QUOTATION_ID=qi.QUOTATION_ID
inner join items i on i.ITEM_ID=qi.ITEM_ID
inner join supplier sp on sp.SUPPLIER_ID=qi.SUPPLIER_ID
left join employee e on e.EMPLOYEE_ID=qi.CREATION_USER_ID
left join employee emp on emp.EMPLOYEE_ID=qi.LAST_UPDATE_USER_ID
left join taxcategory tc on tc.TAXCATEGORY_ID=qi.TAXCATEGORY_ID
left join employee er on er.EMPLOYEE_ID=q.REQUESTED_BY';

SET @FINAL_SQL= CONCAT(BASE_SQL,QTN_WHERE_CLAUSE);

PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
