CREATE  PROCEDURE `PURCHASE_INVOICE_DETAILS`(
	IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN
DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';
DECLARE SALES_WHERE_CLAUSE VARCHAR(5000) DEFAULT '';
SET SALES_WHERE_CLAUSE=WHERECLAUSE;

SET SALES_WHERE_CLAUSE=replace(SALES_WHERE_CLAUSE,'e.EMP_NM','CONCAT(e.FIRST_NM," ", e.LAST_NM)');

SET BASE_SQL=  'select distinct sp.SP_NAME,
ifnull(inv.INVOICE_NO," ") INVOICE_NO,
ifnull(sp.CITY_NM," ") CITY_NM,
ifnull(inv.GRN_NO," ") GRN_NO,
inv.INVOICE_DT,
date_format(inv.INVOICE_DT,"%d-%m-%y") INVOICE_GRID_DT,
i.ITEM_NM,
CONCAT(e.FIRST_NM," ", e.LAST_NM) AS EMP_NM,
CONCAT(e.FIRST_NM," ", e.LAST_NM) AS EMP_MODIFIED,
m.MFR_NAME,
init.BATCH_NO,
init.QUANTITY_APPROVED,
init.EXPIRY_DT,
date_format(init.EXPIRY_DT,"%d-%m-%y") EXPIRY_GRID_DT,
ifnull(init.BONUS,0) BONUS,
ifnull(ROUND(init.PACK_PRICE,2),0) UNIT_RATE,
ifnull(ROUND(init.DISCOUNT_PERCENTAGE,2),0) DISCOUNT,
ifnull(ROUND((init.QUANTITY_APPROVED*init.PACK_PRICE) - (init.QUANTITY_APPROVED*init.PACK_PRICE*init.DISCOUNT_PERCENTAGE/100),2),0)
AS TOTAL_VALUE,
ifnull((init.QUANTITY_APPROVED*init.PACK_PRICE*init.DISCOUNT_PERCENTAGE/100),0) AS DISCOUNT_AMT,
ifnull(inv.ROUND_OFF,0) AS ROUNDOFF,
ifnull(Round((tc.CATEGORY_VALUE/100)*(init.QUANTITY_APPROVED*init.PACK_PRICE * ( 1 -(init.DISCOUNT_PERCENTAGE/100))),2),0)  AS VAT_AMT,
ifnull(ROUND(inv.HANDLING_CHARGES,2),0) HANDLING_CHARGES
from invoice_items init
inner join invoice inv on init.INVOICE_ID=inv.INVOICE_ID
inner join items i on init.ITEM_ID=i.ITEM_ID
inner join supplier sp on inv.SUPPLIER_ID=sp.SUPPLIER_ID
left join taxcategory tc on tc.TAXCATEGORY_ID=init.TAX
left join employee e on e.EMPLOYEE_ID=inv.CREATION_USER_ID 
left join employee em on em.EMPLOYEE_ID=inv.LAST_UPDATE_USER_ID
left join manufacturer m on m.MANUFACTURER_ID=i.MANUFACTURER_ID';

SET @FINAL_SQL= CONCAT(BASE_SQL,SALES_WHERE_CLAUSE,'ORDER BY inv.INVOICE_DT');

PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;

END ;;
DELIMITER ;
