CREATE  PROCEDURE `PURCHASE_MARGIN`(
	IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN

DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';

SET BASE_SQL=  'select i.ITEM_NM,init.BATCH_NO,init.QUANTITY_APPROVED,init.BONUS,
init.BONUS,init.PACK_PRICE AS UNIT_RATE,ifnull(init.UNIT_SALE_RATE,0) UNIT_SALE_RATE,
ifnull(init.DISCOUNT_PERCENTAGE,0) DISCOUNT_PERCENTAGE,
ifnull(init.SALE_DISCOUNT_PERCENTAGE,0) SALE_DISCOUNT_PERCENTAGE,
ifnull(init.MRP,0) MRP,round(ifnull(init.DISCOUNT,0),2) DISCOUNT,
tc.CATEGORY_VALUE,
round((init.UNIT_SALE_RATE*init.QUANTITY_APPROVED*(init.MARGIN_PER/100)),2) MARGIN_AMT,
round(ifnull(init.MARGIN_PER,0),2) AS MARGIN
from invoice_items init 
inner join invoice inv on init.INVOICE_ID=inv.INVOICE_ID
inner join items i on init.ITEM_ID=i.ITEM_ID
left join taxcategory tc on tc.TAXCATEGORY_ID=init.TAX';

SET @FINAL_SQL= CONCAT(BASE_SQL,WHERECLAUSE,' order by init.last_update_ts desc');

PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;

END ;;
