CREATE  PROCEDURE `PURCHASE_MARGIN_COMPARISON`(
	IN `WHERECLAUSE` VARCHAR(5000)
)
BEGIN

DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';
DECLARE PUR_WHERE_CLAUSE VARCHAR(5000) DEFAULT '';
SET PUR_WHERE_CLAUSE=WHERECLAUSE;

SET PUR_WHERE_CLAUSE=replace(PUR_WHERE_CLAUSE,'e.EMP_NM','CONCAT(e.FIRST_NM," ", e.LAST_NM)');

SET BASE_SQL='select i.ITEM_NM,inv.INVOICE_NO,sp.SP_NAME,init.BATCH_NO,init.QUANTITY_APPROVED,
init.BONUS,ifnull(init.UNIT_SALE_RATE,0) UNIT_SALE_RATE,
ifnull(init.DISCOUNT_PERCENTAGE,0) DISCOUNT_PERCENTAGE,
ifnull(init.SALE_DISCOUNT_PERCENTAGE,0) SALE_DISCOUNT_PERCENTAGE,
ifnull(CONCAT(e.FIRST_NM," ", e.LAST_NM),"N/A") AS EMP_NM,
ifnull(CONCAT(emp.FIRST_NM," ", emp.LAST_NM),"N/A") AS EMP_MODIFIED,
ifnull(init.PACK_PRICE,0) UNIT_RATE,init.MRP,round(ifnull(init.DISCOUNT,0),2) DISCOUNT,
ROUND((ifnull(init.PACK_PRICE,0)*init.QUANTITY_APPROVED)*(1-ifnull(init.DISCOUNT_PERCENTAGE,0)/100)*
(1+ifnull(tc.CATEGORY_VALUE,0)/100),2) AS NET_AMOUNT,
round((init.UNIT_SALE_RATE*init.QUANTITY_APPROVED*(init.MARGIN_PER/100)),2) MARGIN_AMT,
round(ifnull(init.MARGIN_PER,0),2) AS MARGIN
from invoice_items init 
inner join items i on init.ITEM_ID=i.ITEM_ID
inner join invoice inv on inv.INVOICE_ID=init.INVOICE_ID
left join supplier sp on inv.SUPPLIER_ID=sp.SUPPLIER_ID
left join taxcategory tc on tc.TAXCATEGORY_ID=init.TAX
left join employee e on e.EMPLOYEE_ID=init.CREATION_USER_ID
left join employee emp on emp.EMPLOYEE_ID=init.LAST_UPDATE_USER_ID';

SET @FINAL_SQL= CONCAT(BASE_SQL,PUR_WHERE_CLAUSE,' order by init.LAST_UPDATE_TS DESC');

PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;

END ;;
