CREATE  PROCEDURE `PURCHASE_ORDER_DETAILS`(
	IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN
DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';
DECLARE PUR_WHERE_CLAUSE VARCHAR(5000) DEFAULT '';
SET PUR_WHERE_CLAUSE=WHERECLAUSE;

SET PUR_WHERE_CLAUSE=replace(PUR_WHERE_CLAUSE,'e.EMP_NM','CONCAT(e.FIRST_NM," ", e.LAST_NM)');
SET PUR_WHERE_CLAUSE=replace(PUR_WHERE_CLAUSE,'po.FROM_AS_OF_DATE','po.PURCHASE_ORDER_DT');
SET PUR_WHERE_CLAUSE=replace(PUR_WHERE_CLAUSE,'po.TO_AS_OF_DATE','po.PURCHASE_ORDER_DT');

SET BASE_SQL=  'select ifnull(po.PURCHASE_ORDER_NO," ") PURCHASE_ORDER_NO,qt.QUOTATION_NO,
po.PURCHASE_ORDER_DT,
date_format(po.PURCHASE_ORDER_DT,"%d-%m-%y") PURCHASE_ORDER_GRID_DT,
sp.SP_NAME,ifnull(sp.CITY_NM," ") CITY_NM,
ifnull(CONCAT(e.FIRST_NM," ", e.LAST_NM),"N/A") AS EMP_NM,
ifnull(CONCAT(emp.FIRST_NM," ", emp.LAST_NM),"N/A") AS EMP_MODIFIED,
ifnull(CONCAT(app.FIRST_NM," ", app.LAST_NM),"N/A") AS APP_BY,
i.ITEM_NM,poi.QUANTITY,ifnull(poi.BONUS,0) BONUS,
ifnull(ROUND(poi.PACK_PURCHASE_PRICE,2),0) UNIT_RATE,
ifnull(ROUND(poi.DISCOUNT_PERCENTAGE,2),0) DISCOUNT,
round((poi.QUANTITY*poi.PACK_PURCHASE_PRICE) *(ifnull(poi.DISCOUNT_PERCENTAGE,0)/100),2) AS DISC_AMT,
round((poi.QUANTITY*poi.PACK_PURCHASE_PRICE*(1-ifnull(poi.DISCOUNT_PERCENTAGE,0)/100)),2) AS TOTAL_VALUE,
ifnull(poi.NET_AMT,0) NET_AMT,
ifnull(ROUND(po.OTHER_CHARGES,2),0) OTHER_CHARGES,
round((poi.QUANTITY*poi.PACK_PURCHASE_PRICE) * (1-ifnull(poi.DISCOUNT_PERCENTAGE,0)/100)*(ifnull(tc.CATEGORY_VALUE,0)/100),2) AS VAT_AMT,
poi.PACK from purchase_order po 
inner join purchase_order_items poi on poi.PURCHASE_ORDER_ID=po.PURCHASE_ORDER_ID
inner join items i on poi.ITEM_Id=i.ITEM_ID 
inner join supplier sp on po.SUPPLIER_ID=sp.SUPPLIER_ID
left join employee e on e.EMPLOYEE_ID=po.CREATION_USER_ID 
left join employee emp on emp.EMPLOYEE_ID=po.LAST_UPDATE_USER_ID
left join quotation qt on qt.QUOTATION_ID=po.QUOTATION_ID
left join taxcategory tc on tc.TAXCATEGORY_ID=poi.TAX
left join employee app on po.APPROVED_BY=app.EMPLOYEE_ID';

SET @FINAL_SQL= CONCAT(BASE_SQL,PUR_WHERE_CLAUSE,' ORDER BY poi.LAST_UPDATE_TS DESC');


PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;

END ;;
