DECLARE ST_WHERE_CLAUSE VARCHAR(5000) DEFAULT '';


SET AP_WHERE_CLAUSE=WHERECLAUSE;  
SET ST_WHERE_CLAUSE=WHERECLAUSE;    
SET AP_WHERE_CLAUSE=replace(AP_WHERE_CLAUSE,'st.TO_UPDATED_DATE','date_format(st.LAST_UPDATE_TS,"%y-%m-%d")');
SET ST_WHERE_CLAUSE=replace(ST_WHERE_CLAUSE,'st.TO_UPDATED_DATE','ST.STOCK_DATE');


truncate table stock_history_by_date_working;
set BASE_SQL1='insert into stock_history_by_date_working
select st.STOCK_ID,st.STOCK_NO,st.ITEM_ID,st.PHARMACY_ID,st.INVOICE_ID,st.QUANTITY,st.BONUS,
st.UNIT_SALE_RATE,st.SP_VAT,st.MRP,st.MARGIN,st.MARGIN_AMT,st.SALE_DISCOUNT_PERCENTAGE,
st.SALE_DISCOUNT_AMOUNT,st.AUDIT_ID,st.CREATION_TS,st.CREATION_USER_ID,
st.LAST_UPDATE_TS,st.LAST_UPDATE_USER_ID,st.MANUFACTURE_DT,st.EXPIRY_DT,st.BATCH_NO,
st.PURCHASE_DISCOUNT_AMOUNT,st.PURCHASE_DISCOUNT_PERCENTAGE,st.RACK,st.UNIT_PURCHASE_RATE,st.SHELF,
st.BARCODE,st.SUPPLIER_ID,st.REMARKS,st.STATUS,st.VAT,st.STOCK_DATE,
st.INVOICE_NO,st.ENTRY_TYPE,st.PACK,st.BILL_ID 
from stock_history st';

SET @FINAL_SQL= CONCAT(BASE_SQL1,AP_WHERE_CLAUSE);

PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;




truncate table purchaseprice_value_for_current_stock_working;

insert into purchaseprice_value_for_current_stock_working (
select i.ITEM_NM, st.BATCH_NO, st.EXPIRY_DT, st.QUANTITY, ifnull(st.PURCHASE_DISCOUNT_PERCENTAGE,0)
as PURCHASE_DISCOUNT_PERCENTAGE, round(ifnull(st.UNIT_PURCHASE_RATE,0),2) AS UNIT_PURCHASE_RATE,
tc.CATEGORY_CODE,
ifnull(ROUND((tc.CATEGORY_VALUE/100)*((st.QUANTITY*st.UNIT_PURCHASE_RATE)),2),0) AS VAT_AMT,
round(ifnull(st.QUANTITY,0) * st.UNIT_PURCHASE_RATE * ( 1 - ifnull(st.PURCHASE_DISCOUNT_PERCENTAGE,0)/100) * 
(1 + (tc.CATEGORY_VALUE/100)),2) as PURCHASE_VALUE,
date_format(st.LAST_UPDATE_TS,'%y-%m-%d'),date_format(st.LAST_UPDATE_TS,'%y-%m-%d'),
st.LAST_UPDATE_TS,st.STOCK_ID
from stock_history_by_date_working st
inner join stock s on s.stock_id=st.STOCK_ID 
left join taxcategory tc on tc.TAXCATEGORY_ID=s.TAX_CATEGORY_ID
inner join items i on i.ITEM_ID = st.ITEM_ID and i.ITEM_NM is not null,
(select max(sh.LAST_UPDATE_TS) LAST_UPDATED_TS,sh.STOCK_ID as stockid FROM stock_history_by_date_working sh
inner join items it on it.ITEM_ID = sh.ITEM_ID and it.ITEM_NM is not null 
group by sh.stock_id) maxdates 
WHERE maxdates.stockid=st.STOCK_ID and maxdates.LAST_UPDATED_TS=st.LAST_UPDATE_TS 
order by i.item_nm asc,st.LAST_UPDATE_TS asc);


truncate table stock_by_date_working;
set BASE_SQL2='insert into stock_by_date_working
select i.ITEM_NM, st.BATCH_NO, st.EXPIRY_DT, st.QUANTITY, ifnull(st.PURCHASE_DISCOUNT_PERCENTAGE,0)
as PURCHASE_DISCOUNT_PERCENTAGE, round(ifnull(st.UNIT_PURCHASE_RATE,0),2) AS UNIT_PURCHASE_RATE,
tc.CATEGORY_CODE,
ifnull(ROUND((tc.CATEGORY_VALUE/100)*((st.QUANTITY*st.UNIT_PURCHASE_RATE)),2),0) AS VAT_AMT,
round(ifnull(st.QUANTITY,0) * st.UNIT_PURCHASE_RATE * ( 1 - ifnull(st.PURCHASE_DISCOUNT_PERCENTAGE,0)/100) * 
(1 + (tc.CATEGORY_VALUE/100)),2) as PURCHASE_VALUE,
date_format(st.LAST_UPDATE_TS,"%y-%m-%d"),date_format(st.LAST_UPDATE_TS,"%y-%m-%d"),
st.LAST_UPDATE_TS,st.STOCK_ID,st.STOCK_DATE
from stock st 
left join taxcategory tc on tc.TAXCATEGORY_ID=st.TAX_CATEGORY_ID
inner join items i on i.ITEM_ID = st.ITEM_ID';

SET @FINAL_SQL= CONCAT(BASE_SQL2,ST_WHERE_CLAUSE, " and st.quantity>0 and i.ITEM_NM is not null
and st.STOCK_ID not in (select stock_id from purchaseprice_value_for_current_stock_working)",
' order by i.item_nm asc,st.LAST_UPDATE_TS asc');

PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;

SET BASE_SQL= 'select st.ITEM_NM,st.BATCH_NO,date_format(st.EXPIRY_DT,"%d-%m-%y") EXPIRY_DT,
ifnull(st.QUANTITY,0) AS QUANTITY,st.PURCHASE_DISCOUNT_PERCENTAGE,st.UNIT_PURCHASE_RATE,
st.CATEGORY_CODE,ifnull(st.VAT_AMT,0) AS VAT_AMT,
ifnull(st.PURCHASE_VALUE,0) AS PURCHASE_VALUE,
date_format(st.LAST_UPDATE_TS,"%d-%m-%y %h:%i %p") AS LAST_UPDATE_TS
 from purchaseprice_value_for_current_stock_working st
 where st.quantity>0
 union 
 select st.ITEM_NM,st.BATCH_NO,date_format(st.EXPIRY_DT,"%d-%m-%y") EXPIRY_DT,
ifnull(st.QUANTITY,0) AS QUANTITY,st.PURCHASE_DISCOUNT_PERCENTAGE,st.UNIT_PURCHASE_RATE,
st.CATEGORY_CODE,ifnull(st.VAT_AMT,0) AS VAT_AMT,
ifnull(st.PURCHASE_VALUE,0) AS PURCHASE_VALUE,
date_format(st.LAST_UPDATE_TS,"%d-%m-%y %h:%i %p") AS LAST_UPDATE_TS
 from stock_by_date_working st
 ';

SET @FINAL_SQL= CONCAT(BASE_SQL);

PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;

END ;;
DELIMITER ;
