CREATE  PROCEDURE `PURCHASE_REGISTER_LIST`(
	IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN
DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';
DECLARE SALES_WHERE_CLAUSE VARCHAR(5000) DEFAULT '';

SET SALES_WHERE_CLAUSE=WHERECLAUSE;
SET SALES_WHERE_CLAUSE=replace(SALES_WHERE_CLAUSE,'e.CREATED_BY','concat(e.FIRST_NM , " " , e.LAST_NM)');

SET BASE_SQL=  'select DISTINCT inv.INVOICE_NO,
date_format(inv.INVOICE_DT,"%d-%m-%y") as INVOICE_DT,
sp.SP_NAME,pt.TYPE,ifnull(inv.INVOICE_AMOUNT,0) as inv_amt ,CONCAT(e.FIRST_NM," ", e.LAST_NM) AS EMP_NM,
 concat(e.FIRST_NM , " " , e.LAST_NM) as CREATED_BY,
concat(e.FIRST_NM , " " , e.LAST_NM) as MODIFIED_BY from purchase_order po 
inner join invoice inv on inv.SUPPLIER_ID=po.SUPPLIER_ID
inner join supplier sp on inv.SUPPLIER_ID=sp.SUPPLIER_ID
inner join payment_types pt
inner join employee e on e.EMPLOYEE_ID=po.CREATION_USER_ID
inner join employee emp on emp.EMPLOYEE_ID=po.LAST_UPDATE_USER_ID ';
  
SET @FINAL_SQL= CONCAT(BASE_SQL,SALES_WHERE_CLAUSE,' group by inv.INVOICE_NO');

PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;

END ;;
DELIMITER ;
