CREATE  PROCEDURE `PURCHASE_RETURNS`(
	IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN
DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';
DECLARE SALES_WHERE_CLAUSE VARCHAR(5000) DEFAULT '';
SET SALES_WHERE_CLAUSE=WHERECLAUSE;

SET SALES_WHERE_CLAUSE=replace(SALES_WHERE_CLAUSE,'e.CREATED_BY','concat(e.FIRST_NM , " " , e.LAST_NM)');

SET BASE_SQL='select distinct sp.SP_NAME,
ifnull(inv.INVOICE_NO," ") INVOICE_NO,
ifnull(pr.PURCHASE_RETURN_NO," ") PURCHASE_RETURN_NO,
ifnull(sp.CITY_NM," ") CITY_NM,
ifnull(inv.GRN_NO," ") GRN_NO,
pr.PURCHASE_RETURN_DATE,
date_format(pr.PURCHASE_RETURN_DATE,"%d-%m-%y") PURCHASE_RETURN_GRID_DATE,
inv.INVOICE_DT,
date_format(inv.INVOICE_DT,"%d-%m-%y") INVOICE_GRID_DT,
i.ITEM_NM,
prit.BATCH_NO,
prit.RETURN_QUANTITY AS QUANTITY ,
init.EXPIRY_DT,
date_format(init.EXPIRY_DT,"%d-%m-%y") EXPIRY_GRID_DT,
ifnull(init.BONUS,0) BONUS,
ifnull(ROUND(init.UNIT_RATE,2),0) UNIT_RATE,
ifnull(ROUND(init.DISCOUNT_PERCENTAGE,2),0) DISCOUNT,
ifnull(ROUND((prit.RETURN_QUANTITY*init.PACK_PRICE) - (prit.RETURN_QUANTITY*init.PACK_PRICE*init.DISCOUNT_PERCENTAGE/100),2),0)
AS TOTAL_VALUE,
ifnull(ROUND(tc.CATEGORY_VALUE/100*((prit.RETURN_QUANTITY*init.PACK_PRICE *( 1 -(init.DISCOUNT_PERCENTAGE/100)))),2),0) AS VAT_AMT,
ifnull(ROUND(pr.CHARGES,2),0) HANDLING_CHARGES,
 concat(e.FIRST_NM , " " , e.LAST_NM) as CREATED_BY,
concat(e.FIRST_NM , " " , e.LAST_NM) as MODIFIED_BY
from purchase_return_item prit
inner join purchase_return pr on pr.PURCHASE_RETURN_ID=prit.PURCHASE_RETURN_ID
inner join invoice_items init on init.INVOICE_ID=pr.INVOICE_ID and init.Item_ID = prit.Item_ID
inner join invoice inv on inv.INVOICE_ID=pr.INVOICE_ID
inner join items i on prit.ITEM_ID=i.ITEM_ID
inner join stock st on st.ITEM_ID=i.ITEM_ID
inner join supplier sp on pr.SUPPLIER_ID=sp.SUPPLIER_ID 
inner join taxcategory tc on tc.TAXCATEGORY_ID=i.tax_id
inner join employee e on pr.CREATION_USER_ID=e.EMPLOYEE_ID and pr.LAST_UPDATE_USER_ID=e.EMPLOYEE_ID '; 

SET @FINAL_SQL= CONCAT(BASE_SQL,SALES_WHERE_CLAUSE);

PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;

END ;;
DELIMITER ;
