CREATE  PROCEDURE `QUOTATION_DETAILS`(
	IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN
DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';
DECLARE QTN_WHERE_CLAUSE VARCHAR(5000) DEFAULT '';

SET QTN_WHERE_CLAUSE=WHERECLAUSE;   
SET QTN_WHERE_CLAUSE=replace(QTN_WHERE_CLAUSE,'q.FROM_QTN_DATE','q.QUOTATION_DT');
SET QTN_WHERE_CLAUSE=replace(QTN_WHERE_CLAUSE,'q.TO_QTN_DATE','q.QUOTATION_DT');
SET QTN_WHERE_CLAUSE=replace(QTN_WHERE_CLAUSE,'q.CREATED_BY','concat(ec.FIRST_NM," ",ec.LAST_NM)');


SET BASE_SQL='select q.QUOTATION_NO,date_format(q.QUOTATION_DT,"%d-%m-%y") QUOTATION_DT,
sum(qi.QUANTITY) QUANTITY,
sp.SP_NAME,concat(ec.FIRST_NM," ",ec.LAST_NM) CREATED_BY,q.CREATION_TS,
qs.STATUS,concat(es.FIRST_NM," ",es.LAST_NM) SENT_BY,q.SENT_DT,
concat(erq.FIRST_NM," ",erq.LAST_NM) REQUESTED_BY,concat(ep.FIRST_NM," ",ep.LAST_NM) APPROVED_BY,
date_format(q.APPROVED_DT,"%d-%m-%y") APPROVED_DT,
date_format(q.QUOTATION_EXPIRY_DT,"%d-%m-%y") QUOTATION_EXPIRY_DT,concat(erj.FIRST_NM," ",erj.LAST_NM) REJECTED_BY,
date_format(q.REJECTED_DT,"%d-%m-%y") REJECTED_DT,q.REJECTED_REASON,q.QUOTATION_SEND_MODE,
concat(esp.FIRST_NM," ",esp.LAST_NM) SUPPLIER_QTN_APPROVED_BY,
date_format(q.SUPPLIER_QTN_APPROVED_DT,"%d-%m-%y") SUPPLIER_QTN_APPROVED_DT,
concat(esr.FIRST_NM," ",esr.LAST_NM) SUPPLIER_QTN_REJECTED_BY,
date_format(q.SUPPLIER_QTN_REJECTED_DT,"%d-%m-%y") SUPPLIER_QTN_REJECTED_DT,
q.SUPPLIER_QTN_REJECTED_REASON,q.DESCRIPTION
from quotation q 
inner join quotation_status qs on qs.QUOTATION_STATUS_ID=q.QUOTATION_STATUS_ID
left join employee ec on ec.EMPLOYEE_ID=q.CREATED_BY
left join employee es on es.EMPLOYEE_ID=q.SENT_BY
left join employee erq on erq.EMPLOYEE_ID=q.REQUESTED_BY
left join employee erj on erj.EMPLOYEE_ID=q.REJECTED_BY
left join employee ep on ep.EMPLOYEE_ID=q.APPROVED_BY
left join employee esp on esp.EMPLOYEE_ID=q.SUPPLIER_QTN_APPROVED_BY
left join employee esr on esr.EMPLOYEE_ID=q.SUPPLIER_QTN_REJECTED_BY
inner join quotation_items qi on qi.QUOTATION_ID=q.QUOTATION_ID
inner join supplier sp on sp.SUPPLIER_ID=qi.SUPPLIER_ID';

SET @FINAL_SQL= CONCAT(BASE_SQL,QTN_WHERE_CLAUSE,' group by q.QUOTATION_NO');

PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
