CREATE  PROCEDURE `QUOTATION_DETAILS_BY_ITEM`(
	IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN
DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';
DECLARE QTN_WHERE_CLAUSE VARCHAR(5000) DEFAULT '';

SET QTN_WHERE_CLAUSE=WHERECLAUSE;   
SET QTN_WHERE_CLAUSE=replace(QTN_WHERE_CLAUSE,'q.FROM_QTN_DATE','q.QUOTATION_DT');
SET QTN_WHERE_CLAUSE=replace(QTN_WHERE_CLAUSE,'q.TO_QTN_DATE','q.QUOTATION_DT');
SET QTN_WHERE_CLAUSE=replace(QTN_WHERE_CLAUSE,'qi.CREATED_BY','concat(e.FIRST_NM," ",e.LAST_NM)');

SET BASE_SQL='select q.QUOTATION_NO,
date_format(q.QUOTATION_DT,"%d-%m-%y") QUOTATION_DT,
i.ITEM_NM,qi.QUANTITY,qi.STATUS,sp.SP_NAME,
qi.DISCOUNT_PERCENTAGE,ifnull(qi.UNIT_PURCHASE_PRICE,0) AS UNIT_PURCHASE_PRICE,tc.CATEGORY_CODE,
concat(e.FIRST_NM," ",e.LAST_NM) CREATED_BY,
concat(emp.FIRST_NM," ",emp.LAST_NM) MODIFIED_BY,
date_format(qi.CREATION_TS,"%d-%m-%y %h:%i %p") CREATION_TS from quotation_items qi
inner join quotation q on q.QUOTATION_ID=qi.QUOTATION_ID
inner join items i on i.ITEM_ID=qi.ITEM_ID
inner join supplier sp on sp.SUPPLIER_ID=qi.SUPPLIER_ID
left join employee e on e.EMPLOYEE_ID=qi.CREATION_USER_ID
left join employee emp on emp.EMPLOYEE_ID=qi.LAST_UPDATE_USER_ID
left join taxcategory tc on tc.TAXCATEGORY_ID=qi.TAXCATEGORY_ID';

SET @FINAL_SQL= CONCAT(BASE_SQL,QTN_WHERE_CLAUSE);

PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `SALES_ATTRIBUTION_VAT` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `SALES_ATTRIBUTION_VAT`(
	IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN
DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';
DECLARE NEW_WHERE_CLAUSE  VARCHAR(5000) DEFAULT '';

SET NEW_WHERE_CLAUSE=WHERECLAUSE;
SET NEW_WHERE_CLAUSE=replace(NEW_WHERE_CLAUSE,'sa.FROM_BILL_DATE','s.BILL_DATE');
SET NEW_WHERE_CLAUSE=replace(NEW_WHERE_CLAUSE,'sa.TO_BILL_DATE','s.BILL_DATE');
SET NEW_WHERE_CLAUSE=replace(NEW_WHERE_CLAUSE,'sa.ITEM_NM','i.ITEM_NM');

SET BASE_SQL='select  s.BILL_CODE, s.BILL_DATE, s.BILL_DATE, i.ITEM_NM, si.BATCH_NO,
concat(e.FIRST_NM," ",e.LAST_NM) AS CREATED_BY,
ifnull(si.SALE_QTY,0) AS SALE_QTY, ifnull(si.QTY_FREE,0) as QTY_FREE,
round(ifnull(si.UNIT_SALE_PRICE,0),2) AS UNIT_SALE_PRICE , 
round(ifnull(si.DISCOUNT_PERCENTAGE,0),2) AS S_DISC, 
ifnull(si.VAT,0) AS VAT, ifnull(si.SALE_AMOUNT,0) AS SALE_AMOUNT,
round((ifnull(si.SALE_QTY,0)*si.UNIT_SALE_PRICE) * (1-ifnull(si.DISCOUNT_PERCENTAGE,0)/100),2) AS TOTAL_AMT,
date_format(si.CREATION_TS,"%d-%m-%y %h:%i %p") CREATION_TS,
round((ifnull(si.SALE_QTY,0)*si.UNIT_SALE_PRICE) * (1-ifnull(si.DISCOUNT_PERCENTAGE,0)/100)*(ifnull(tc.CATEGORY_VALUE,0)/100),2) AS VAT_AMT
 from SALES_ITEMS si 
 inner join SALES s on si.BILL_ID = s.BILL_ID and s.Payment_Status not in ( "Dummy Bill","Cancel") and si.VAT!=0
 inner join ITEMS  i  on i.ITEM_ID = si.ITEM_ID 
 inner join employee e on e.EMPLOYEE_ID=s.EMPLOYEE_ID
 inner join taxcategory tc on si.TAX_CATEGORY_ID=tc.TAXCATEGORY_ID';

SET @FINAL_SQL= CONCAT(BASE_SQL,NEW_WHERE_CLAUSE);

PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `SALES_BY_CUSTOMER_DETAILS` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `SALES_BY_CUSTOMER_DETAILS`(
	IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN
DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';
DECLARE SALES_WHERE_CLAUSE VARCHAR(5000) DEFAULT '';
SET SALES_WHERE_CLAUSE=WHERECLAUSE;
SET SALES_WHERE_CLAUSE=replace(SALES_WHERE_CLAUSE,'e.EMP_NM','CONCAT(e.FIRST_NM," ", e.LAST_NM)');
SET SALES_WHERE_CLAUSE=replace(SALES_WHERE_CLAUSE,'s.FROM_BILL_DATE','s.BILL_DATE');
SET SALES_WHERE_CLAUSE=replace(SALES_WHERE_CLAUSE,'s.TO_BILL_DATE','s.BILL_DATE');

SET BASE_SQL= 'select DISTINCT s.CUSTOMER_NM,s.BILL_CODE,
date_format(s.BILL_DATE,"%d-%m-%y") BILL_DATE,
CONCAT(e.FIRST_NM," ", e.LAST_NM) AS EMP_NM,
p.FIRST_NM,i.ITEM_NM,m.MFR_NAME,si.BATCH_NO,
date_format(st.EXPIRY_DT,"%d-%m-%y") EXPIRY_DT,si.SALE_QTY,
ifnull(si.MARGIN,0) MARGIN,round(ifnull(si.PNL,0),2) PNL_AMT,
si.UNIT_SALE_PRICE,round(ifnull(si.DISCOUNT_PERCENTAGE,0),2) AS DISC,
round(((si.UNIT_SALE_PRICE*si.SALE_QTY)*( 1 - ifnull(si.DISCOUNT_PERCENTAGE,0) /100)),2) AS TOTAL_AMOUNT,
 concat(e.FIRST_NM , " " , e.LAST_NM) as CREATED_BY,
concat(emp.FIRST_NM , " " , emp.LAST_NM) as MODIFIED_BY
from sales_items si 
inner join sales s on si.BILL_ID=s.BILL_ID
inner join items i on si.ITEM_ID=i.ITEM_ID
inner join stock st on st.STOCK_ID=si.STOCK_ID
inner join manufacturer m on i.MANUFACTURER_ID=m.MANUFACTURER_ID
inner join provider p on s.PROVIDER_ID=p.PROVIDER_ID
inner join employee e on e.EMPLOYEE_ID=s.CREATION_USER_ID
inner join employee emp on emp.EMPLOYEE_ID=s.LAST_UPDATE_USER_ID ';
 
SET @FINAL_SQL= CONCAT(BASE_SQL,SALES_WHERE_CLAUSE,' order by s.BILL_DATE');


PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;

END ;;
