CREATE  PROCEDURE `SALES_PROFIT_ATTRIBUTION`(
	IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN
DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';
DECLARE PROFIT_WHERE_CLAUSE  VARCHAR(5000) DEFAULT '';
DECLARE BASE_SQL1  VARCHAR(5000) DEFAULT '';

SET PROFIT_WHERE_CLAUSE=WHERECLAUSE;
SET PROFIT_WHERE_CLAUSE=replace(PROFIT_WHERE_CLAUSE,'sa.FROM_BILL_DATE','s.BILL_DATE');
SET PROFIT_WHERE_CLAUSE=replace(PROFIT_WHERE_CLAUSE,'sa.TO_BILL_DATE','s.BILL_DATE');
SET PROFIT_WHERE_CLAUSE=replace(PROFIT_WHERE_CLAUSE,'sa.ITEM_NM','i.ITEM_NM');
SET PROFIT_WHERE_CLAUSE=replace(PROFIT_WHERE_CLAUSE,'sa.CREATED_BY','concat(e.FIRST_NM," ",e.LAST_NM)');
SET PROFIT_WHERE_CLAUSE=replace(PROFIT_WHERE_CLAUSE,'sa.CUSTOMER_NM','concat(c.FIRST_NM," ",c.LAST_NM)');
SET PROFIT_WHERE_CLAUSE=replace(PROFIT_WHERE_CLAUSE,'sa.CUSTOMER_TYPE',
'CASE
WHEN c.CORPORATE="Y" THEN "Corporate"
WHEN c.CORPORATE="S" THEN "Staff"
ELSE "Customer"
END');

TRUNCATE TABLE sales_profit_attribution_working ;

SET BASE_SQL1='insert into sales_profit_attribution_working
select s.BIll_CODE, 
concat(c.FIRST_NM," ",c.LAST_NM) AS CUSTOMER_NM,
CASE
WHEN c.CORPORATE="Y" THEN "Corporate"
WHEN c.CORPORATE="S" THEN "Staff"
ELSE "Customer"
END CUSTOMER_TYPE, 
s.BILL_DATE, s.BILL_DATE, i.ITEM_NM, si.BATCH_NO,
concat(e.FIRST_NM," ",e.LAST_NM) AS CREATED_BY,s.CREATION_TS,
ifnull(si.SALE_QTY,0) AS SALE_QTY, ifnull(si.QTY_FREE,0) as QTY_FREE,
round(ifnull(si.UNIT_PURCHASE_PRICE,0),2) AS P_Price,
round(ifnull(st.PURCHASE_DISCOUNT_PERCENTAGE,0),2) 
AS P_Disc ,
round(ifnull(si.UNIT_SALE_PRICE,0),2) AS S_Price, 
round(ifnull(si.DISCOUNT_PERCENTAGE,0),2) AS S_Disc, 
ifnull(si.MARGIN,0) MARGIN,round(ifnull(si.PNL,0),2) PNL_AMT,
ifnull(si.VAT,0) AS VAT, ifnull(si.SALE_AMOUNT,0) AS SALE_AMOUNT,
round(((si.SALE_QTY-ifnull(si.QTY_FREE,0)) *(1 + ifnull(si.VAT,0)/100)*  ( 1 - ifnull(st.PURCHASE_DISCOUNT_PERCENTAGE,0) /100) * si.UNIT_PURCHASE_PRICE),2) AS PURCHASE_AMOUNT
 from SALES_ITEMS si  
 inner join SALES s on si.BILL_ID = s.BILL_ID and Payment_Status not in ( "Dummy Bill","Cancel") 
 inner join ITEMS  i on i.ITEM_ID = si.ITEM_ID
inner join STOCK st on st.ITEM_ID = si.ITEM_ID and si.STOCK_ID = st.STOCK_ID
 inner join employee e on e.EMPLOYEE_ID=s.EMPLOYEE_ID
 inner join customer c on c.CUSTOMER_ID=s.CUSTOMER_ID';
 
SET @FINAL_SQL= CONCAT(BASE_SQL1,PROFIT_WHERE_CLAUSE);


PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;

SET BASE_SQL='select sa.BILL_CODE,sa.CUSTOMER_NM,sa.CUSTOMER_TYPE,
date_format(sa.FROM_BILL_DATE,"%d-%m-%y") as FROM_BILL_DATE,
sa.ITEM_NM,ifnull(sa.MARGIN,0) MARGIN,ifnull(sa.PNL_AMT,0) PNL_AMT,
sa.BATCH_NO,ifnull(sa.SALE_QTY,0) SALE_QTY,sa.QTY_FREE,sa.CREATED_BY,
date_format(sa.CREATION_TS,"%d-%m-%y %h:%i %p") CREATION_TS,
sa.UNIT_PURCHASE_PRICE,sa.PURCHASE_DISCOUNT_PERCENTAGE,
sa.UNIT_SALE_PRICE,sa.DISCOUNT_PERCENTAGE,
ifnull(sa.PURCHASE_AMOUNT,0) PURCHASE_AMOUNT,
ifnull(sa.VAT,0) VAT,sa.SALE_AMOUNT,
ifnull(round((sa.SALE_AMOUNT-ifnull(sa.PURCHASE_AMOUNT,0)),2),0) AS PROFIT,
ifnull(round(((sa.SALE_AMOUNT-ifnull(sa.PURCHASE_AMOUNT,0))*100)/sa.PURCHASE_AMOUNT,2),0) AS PROFIT_PER
 from sales_profit_attribution_working sa';


SET @FINAL_SQL= CONCAT(BASE_SQL,WHERECLAUSE);

PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;

END ;;
DELIMITER ;
