CREATE  PROCEDURE `SALES_REGISTER_AREAWISE_DETAILS`(
IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN
DECLARE BASE_SQL VARCHAR(5000) DEFAULT '';
DECLARE SALES_WHERE_CLAUSE VARCHAR(5000) DEFAULT '';

DECLARE STOCK_VALUE1 VARCHAR(5000) DEFAULT '';
DECLARE STOCK_VALUE2 VARCHAR(5000) DEFAULT '';
DECLARE STOCK_VALUE3 VARCHAR(5000) DEFAULT '';

DECLARE TOTAL_VAT1 VARCHAR(5000) DEFAULT '';
DECLARE TOTAL_VAT2 VARCHAR(5000) DEFAULT '';
DECLARE TOTAL_VAT3 VARCHAR(5000) DEFAULT '';

DECLARE TOTAL_SALE_AMOUNT1 VARCHAR(5000) DEFAULT '';
DECLARE TOTAL_SALE_AMOUNT2 VARCHAR(5000) DEFAULT '';
DECLARE TOTAL_SALE_AMOUNT3 VARCHAR(5000) DEFAULT '';

DECLARE PENDING_AMOUNT1 VARCHAR(5000) DEFAULT '';
DECLARE PENDING_AMOUNT2 VARCHAR(5000) DEFAULT '';
DECLARE PENDING_AMOUNT3 VARCHAR(5000) DEFAULT '';

DECLARE PURCHASE_DISCOUNT_AMOUNT1 VARCHAR(5000) DEFAULT '';
DECLARE PURCHASE_DISCOUNT_AMOUNT3 VARCHAR(5000) DEFAULT '';
DECLARE PURCHASE_DISCOUNT_AMOUNT2 VARCHAR(5000) DEFAULT '';

DECLARE UPI_AMOUNT1 VARCHAR(5000) DEFAULT '';
DECLARE UPI_AMOUNT2 VARCHAR(5000) DEFAULT '';
DECLARE UPI_AMOUNT3 VARCHAR(5000) DEFAULT '';

DECLARE CASH_AMOUNT1 VARCHAR(5000) DEFAULT '';
DECLARE CASH_AMOUNT2 VARCHAR(5000) DEFAULT '';
DECLARE CASH_AMOUNT3 VARCHAR(5000) DEFAULT '';

DECLARE CREDIT_AMOUNT1 VARCHAR(5000) DEFAULT '';
DECLARE CREDIT_AMOUNT2 VARCHAR(5000) DEFAULT '';
DECLARE CREDIT_AMOUNT3 VARCHAR(5000) DEFAULT '';

DECLARE CHEQUE_AMT1 VARCHAR(5000) DEFAULT '';
DECLARE CHEQUE_AMT2 VARCHAR(5000) DEFAULT '';
DECLARE CHEQUE_AMT3 VARCHAR(5000) DEFAULT '';

DECLARE WHERECLAUSE_STRING VARCHAR(5000) DEFAULT '' ;


SET WHERECLAUSE_STRING=WHERECLAUSE;
SET SALES_WHERE_CLAUSE=WHERECLAUSE;


SET SALES_WHERE_CLAUSE=replace(SALES_WHERE_CLAUSE,'s.FROM_DATE','sa.BILL_DATE');
SET SALES_WHERE_CLAUSE=replace(SALES_WHERE_CLAUSE,'s.TO_DATE','sa.BILL_DATE');

truncate table area_wise_sales;

set STOCK_VALUE1= 'insert into area_wise_sales(type,value) values
("STOCK VALUE",(
select round(sum(s.UNIT_PURCHASE_RATE*s.pack),2)as stock_value from stock s
inner join sales_items si on si.ITEM_ID= s.ITEM_ID
inner join sales sa on sa.BILL_ID=si.BILL_ID ';

set STOCK_VALUE2=' ))';

set @STOCK_VALUE3=concat(STOCK_VALUE1,SALES_WHERE_CLAUSE ,STOCK_VALUE2);

PREPARE stmt FROM @STOCK_VALUE3;
EXECUTE stmt;
deallocate PREPARE stmt;

set PURCHASE_DISCOUNT_AMOUNT1= 'insert into area_wise_sales(type,value) values
("PURCHASE DISCOUNT AMOUNT",(select round(sum((s.UNIT_PURCHASE_RATE*s.pack*(s.PURCHASE_DISCOUNT_PERCENTAGE/100))*ii.QUANTITY_APPROVED),2) as Purchase_discount_amount from stock s
inner join invoice i on i.GRN_NO=s.INVOICE_NO 
inner join invoice_items ii on ii.INVOICE_ID=i.INVOICE_ID 
inner join sales_items si on si.STOCK_ID=s.STOCK_ID
inner join sales sa on sa.BILL_ID=si.BILL_ID';

set PURCHASE_DISCOUNT_AMOUNT2=' ))';

set @PURCHASE_DISCOUNT_AMOUNT3=concat(PURCHASE_DISCOUNT_AMOUNT1,SALES_WHERE_CLAUSE ,PURCHASE_DISCOUNT_AMOUNT2);

PREPARE stmt FROM @PURCHASE_DISCOUNT_AMOUNT3;
EXECUTE stmt;
deallocate PREPARE stmt;

set TOTAL_VAT1= 'insert into area_wise_sales(type,value) values
("TOTAL VAT",(SELECT round(sum(sa.VAT_AMT),2) as total_vat FROM sales sa ';

set TOTAL_VAT2=' ))';

set @TOTAL_VAT3=concat(TOTAL_VAT1,SALES_WHERE_CLAUSE,'and sa.PAYMENT_STATUS !="Dummy Bill" and sa.PAYMENT_STATUS !="Cancel"' ,TOTAL_VAT2);

PREPARE stmt FROM @TOTAL_VAT3;
EXECUTE stmt;
deallocate PREPARE stmt;



set UPI_AMOUNT1= 'insert into area_wise_sales(type,value) values
("UPI AMOUNT",(select round(sum(sa.UPI_AMOUNT),2) from sales sa';

set UPI_AMOUNT2=' ))';

set @UPI_AMOUNT3=concat(UPI_AMOUNT1,SALES_WHERE_CLAUSE ,UPI_AMOUNT2);

PREPARE stmt FROM @UPI_AMOUNT3;
EXECUTE stmt;
deallocate PREPARE stmt;

set CASH_AMOUNT1= 'insert into area_wise_sales(type,value) values
("CASH AMOUNT",(select round(sum(sa.CASH_AMOUNT),2) from sales sa';

set CASH_AMOUNT2=' ))';

set @CASH_AMOUNT3=concat(CASH_AMOUNT1,SALES_WHERE_CLAUSE ,CASH_AMOUNT2);

PREPARE stmt FROM @CASH_AMOUNT3;
EXECUTE stmt;
deallocate PREPARE stmt;

set CREDIT_AMOUNT1= 'insert into area_wise_sales(type,value) values
("CREDIT AMOUNT",(select round(sum(sa.CREDIT_AMOUNT),2) from sales sa';

set CREDIT_AMOUNT2=' ))';

set @CREDIT_AMOUNT3=concat(CREDIT_AMOUNT1,SALES_WHERE_CLAUSE ,CREDIT_AMOUNT2);

PREPARE stmt FROM @CREDIT_AMOUNT3;
EXECUTE stmt;
deallocate PREPARE stmt;

set CHEQUE_AMT1= 'insert into area_wise_sales(type,value) values
("CHEQUE AMOUNT",(select round(sum(sa.CHEQUE_AMT),2) from sales sa';

set CHEQUE_AMT2=' ))';

set @CHEQUE_AMT3=concat(CHEQUE_AMT1,SALES_WHERE_CLAUSE ,CHEQUE_AMT2);

PREPARE stmt FROM @CHEQUE_AMT3;
EXECUTE stmt;
deallocate PREPARE stmt;

set PENDING_AMOUNT1= 'insert into area_wise_sales(type,value) values
("PENDING AMOUNT",( select round(sum(sa.TOTAL_AMOUNT-sa.PAID_AMOUNT),2) as pending_amount from sales sa';

set PENDING_AMOUNT2=' ))';

set @PENDING_AMOUNT3=concat(PENDING_AMOUNT1,SALES_WHERE_CLAUSE ,PENDING_AMOUNT2);

PREPARE stmt FROM @PENDING_AMOUNT3;
EXECUTE stmt;
deallocate PREPARE stmt;

set TOTAL_SALE_AMOUNT1= 'insert into area_wise_sales(type,value) values
("TOTAL SALE AMOUNT",( select round(sum(sa.TOTAL_AMOUNT),2) as total_amount from sales sa';

set TOTAL_SALE_AMOUNT2=' ))';
 
set @TOTAL_SALE_AMOUNT3=concat(TOTAL_SALE_AMOUNT1,SALES_WHERE_CLAUSE ,TOTAL_SALE_AMOUNT2);

PREPARE stmt FROM @TOTAL_SALE_AMOUNT3;
EXECUTE stmt;
deallocate PREPARE stmt;



SET BASE_SQL= 'select p.type,p.value from area_wise_sales p';

SET @FINAL_SQL= CONCAT(BASE_SQL);

PREPARE stmt FROM @FINAL_SQL;
EXECUTE stmt;
deallocate PREPARE stmt;


END ;;
DELIMITER ;
