CREATE  PROCEDURE `SALES_REGISTER_DETAILS`(
	IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN

DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';
DECLARE SALES_WHERE_CLAUSE  VARCHAR(5000) DEFAULT '';

DROP TABLE IF EXISTS `#sales_register_details_working`;

CREATE TABLE `#sales_register_details_working` (
  `BILL_CODE` varchar(30) DEFAULT NULL,
  `FROM_BILL_DATE` date DEFAULT NULL,
  `TO_BILL_DATE` date DEFAULT NULL,
  `CUSTOMER_NM` varchar(500) DEFAULT NULL,
  `TYPE` varchar(50) DEFAULT NULL,
  `AMOUNT` float DEFAULT NULL,
  `PAID_AMOUNT` float DEFAULT NULL,
  `BALANCE_AMOUNT` float DEFAULT NULL,
  `PAYMENT_STATUS` varchar(50) DEFAULT NULL,
  `VAT_AMT` double DEFAULT NULL,
  `EMP_NM` varchar(50) DEFAULT NULL,
  `CREATED_BY` varchar(50) DEFAULT NULL,
  `MODIFIED_BY` varchar(50) DEFAULT NULL,
  `CREATION_TS` timestamp NULL DEFAULT NULL,
  `LAST_UPDATE_TS` timestamp NULL DEFAULT NULL
);

INSERT INTO `#sales_register_details_working`
select DISTINCT s.BILL_CODE,s.BILL_DATE,s.BILL_DATE,CONCAT(c.FIRST_NM," ", c.LAST_NM) as CUSTOMER_NM,
pt.TYPE, s.CASH_AMOUNT ,s.PAID_AMOUNT,s.BALANCE_AMOUNT,s.PAYMENT_STATUS,
round((ifnull(s.VAT_AMT,0)*ifnull(s.CASH_AMOUNT,0))/(s.NET_AMOUNT),2) AS VAT_AMT,
CONCAT(e.FIRST_NM," ", e.LAST_NM) AS EMP_NM,
 concat(e.FIRST_NM , " " , e.LAST_NM) as CREATED_BY,
concat(emp.FIRST_NM , " " , emp.LAST_NM) as MODIFIED_BY,s.CREATION_TS,s.LAST_UPDATE_TS from sales s 
INNER JOIN sales_items si ON s.Bill_ID=si.BILL_ID and s.CASH_AMOUNT >= 0.0 and s.PAYMENT_STATUS != "CANCEL" and s.PAYMENT_STATUS != "DUMMY BILL"
INNER JOIN payment_types pt on pt.TYPE = "CASH"
inner join employee e on e.EMPLOYEE_ID=s.CREATION_USER_ID
inner join employee emp on emp.EMPLOYEE_ID=s.LAST_UPDATE_USER_ID
inner join customer c on c.CUSTOMER_ID=s.CUSTOMER_ID

union

select DISTINCT s.BILL_CODE,s.BILL_DATE,s.BILL_DATE,CONCAT(c.FIRST_NM," ", c.LAST_NM) as CUSTOMER_NM,
pt.TYPE,s.CREDIT_AMOUNT,s.PAID_AMOUNT,s.BALANCE_AMOUNT,s.PAYMENT_STATUS,
CASE
WHEN s.CREDIT_AMOUNT<=0 THEN 0
ELSE
round((ifnull(s.VAT_AMT,0)*ifnull(s.CREDIT_AMOUNT,0))/(s.NET_AMOUNT),2) 
END VAT_AMT,
CONCAT(e.FIRST_NM," ", e.LAST_NM) AS EMP_NM,
 concat(e.FIRST_NM , " " , e.LAST_NM) as CREATED_BY,
concat(emp.FIRST_NM , " " , emp.LAST_NM) as MODIFIED_BY,s.CREATION_TS,s.LAST_UPDATE_TS from sales s 
INNER JOIN sales_items si ON s.Bill_ID=si.BILL_ID and s.CREDIT_AMOUNT >= 0.0 and s.PAYMENT_STATUS != "CANCEL" and s.PAYMENT_STATUS != "DUMMY BILL"
INNER JOIN payment_types pt on pt.TYPE = "CREDIT"
inner join employee e on e.EMPLOYEE_ID=s.CREATION_USER_ID
inner join employee emp on emp.EMPLOYEE_ID=s.LAST_UPDATE_USER_ID
inner join customer c on c.CUSTOMER_ID=s.CUSTOMER_ID

union

select DISTINCT s.BILL_CODE,s.BILL_DATE,s.BILL_DATE,CONCAT(c.FIRST_NM," ", c.LAST_NM) as CUSTOMER_NM,
pt.TYPE,s.UPI_AMOUNT,s.PAID_AMOUNT,s.BALANCE_AMOUNT,s.PAYMENT_STATUS,
round((ifnull(s.VAT_AMT,0)*ifnull(s.UPI_AMOUNT,0))/(s.NET_AMOUNT),2) AS VAT_AMT,
CONCAT(e.FIRST_NM," ", e.LAST_NM) AS EMP_NM,
 concat(e.FIRST_NM , " " , e.LAST_NM) as CREATED_BY,
concat(emp.FIRST_NM , " " , emp.LAST_NM) as MODIFIED_BY,s.CREATION_TS,s.LAST_UPDATE_TS from sales s 
INNER JOIN sales_items si ON s.Bill_ID=si.BILL_ID and UPI_AMOUNT >= 0.0 and 
s.PAYMENT_STATUS != "CANCEL" and s.PAYMENT_STATUS != "DUMMY BILL"
INNER JOIN payment_types pt on pt.TYPE = "M-PESA"
inner join employee e on e.EMPLOYEE_ID=s.CREATION_USER_ID
inner join employee emp on emp.EMPLOYEE_ID=s.LAST_UPDATE_USER_ID
inner join customer c on c.CUSTOMER_ID=s.CUSTOMER_ID

union

select DISTINCT s.BILL_CODE,s.BILL_DATE,s.BILL_DATE,CONCAT(c.FIRST_NM," ", c.LAST_NM) as CUSTOMER_NM,
pt.TYPE,s.CREDIT_CARD_AMOUNT ,s.PAID_AMOUNT,s.BALANCE_AMOUNT,s.PAYMENT_STATUS,
round((ifnull(s.VAT_AMT,0)*ifnull(s.CREDIT_CARD_AMOUNT,0))/(s.NET_AMOUNT),2) AS VAT_AMT,
CONCAT(e.FIRST_NM," ", e.LAST_NM) AS EMP_NM,
 concat(e.FIRST_NM , " " , e.LAST_NM) as CREATED_BY,
concat(emp.FIRST_NM , " " , emp.LAST_NM) as MODIFIED_BY,s.CREATION_TS,s.LAST_UPDATE_TS from sales s 
INNER JOIN sales_items si ON s.Bill_ID=si.BILL_ID and CREDIT_CARD_AMOUNT >= 0.0 and s.PAYMENT_STATUS != "CANCEL" and s.PAYMENT_STATUS != "DUMMY BILL"
INNER JOIN payment_types pt on pt.TYPE = "CARD"
inner join employee e on e.EMPLOYEE_ID=s.CREATION_USER_ID
inner join employee emp on emp.EMPLOYEE_ID=s.LAST_UPDATE_USER_ID
inner join customer c on c.CUSTOMER_ID=s.CUSTOMER_ID

union

select DISTINCT s.BILL_CODE,s.BILL_DATE,s.BILL_DATE,CONCAT(c.FIRST_NM," ", c.LAST_NM) as CUSTOMER_NM,
pt.TYPE,s.CHEQUE_AMT,s.PAID_AMOUNT,s.BALANCE_AMOUNT,s.PAYMENT_STATUS,
round((ifnull(s.VAT_AMT,0)*ifnull(s.CHEQUE_AMT,0))/(s.NET_AMOUNT),2) AS VAT_AMT,
CONCAT(e.FIRST_NM," ", e.LAST_NM) AS EMP_NM ,
 concat(e.FIRST_NM , " " , e.LAST_NM) as CREATED_BY,
concat(emp.FIRST_NM , " " , emp.LAST_NM) as MODIFIED_BY,s.CREATION_TS,s.LAST_UPDATE_TS from sales s 
INNER JOIN sales_items si ON s.Bill_ID=si.BILL_ID and CHEQUE_AMT >= 0.0 and s.PAYMENT_STATUS != "CANCEL" and s.PAYMENT_STATUS != "DUMMY BILL"
INNER JOIN payment_types pt on pt.TYPE = "CHEQUE"
inner join employee e on e.EMPLOYEE_ID=s.CREATION_USER_ID
inner join employee emp on emp.EMPLOYEE_ID=s.LAST_UPDATE_USER_ID
inner join customer c on c.CUSTOMER_ID=s.CUSTOMER_ID

union

select DISTINCT s.BILL_CODE,s.BILL_DATE,s.BILL_DATE,CONCAT(c.FIRST_NM," ", c.LAST_NM) as CUSTOMER_NM,
"CREDIT NOTE",s.CREDIT_NOTE_AMOUNT,s.PAID_AMOUNT,s.BALANCE_AMOUNT,s.PAYMENT_STATUS,
round((ifnull(s.VAT_AMT,0)*ifnull(s.CREDIT_NOTE_AMOUNT,0.0))/(s.NET_AMOUNT),2) AS VAT_AMT,
CONCAT(e.FIRST_NM," ", e.LAST_NM) AS EMP_NM ,
 concat(e.FIRST_NM , " " , e.LAST_NM) as CREATED_BY,
concat(emp.FIRST_NM , " " , emp.LAST_NM) as MODIFIED_BY,s.CREATION_TS,s.LAST_UPDATE_TS from sales s 
INNER JOIN sales_items si ON s.Bill_ID=si.BILL_ID and s.CREDIT_NOTE_AMOUNT >= 0.0 and 
s.PAYMENT_STATUS != "CANCEL" and s.PAYMENT_STATUS != "DUMMY BILL"
inner join employee e on e.EMPLOYEE_ID=s.CREATION_USER_ID
inner join employee emp on emp.EMPLOYEE_ID=s.LAST_UPDATE_USER_ID
inner join customer c on c.CUSTOMER_ID=s.CUSTOMER_ID;

create index sales_working_idx on `#sales_register_details_working` (`BILL_CODE`,`FROM_BILL_DATE`,`TO_BILL_DATE`,`TYPE`,`CREATED_BY`,`MODIFIED_BY`,`CREATION_TS`,`LAST_UPDATE_TS`);

SET BASE_SQL = 'select DISTINCT w.BILL_CODE,
date_format(w.FROM_BILL_DATE,"%d-%m-%y") FROM_BILL_DATE,
date_format(w.TO_BILL_DATE,"%d-%m-%y") TO_BILL_DATE,
w.CUSTOMER_NM,w.EMP_NM,
DATE_FORMAT(w.CREATION_TS,"%d-%m-%y %h") TIME_TO_GROUP,
DATE_FORMAT(w.CREATION_TS,"%d-%m-%y %h:%i %p") CREATION_TS,
w.TYPE, w.AMOUNT,w.PAID_AMOUNT,round(ifnull(w.VAT_AMT,0),2) AS VAT_AMT,w.BALANCE_AMOUNT,w.PAYMENT_STATUS,
w.CREATED_BY,w.MODIFIED_BY
from `#sales_register_details_working` w'; 

SET @FINAL_SQL= concat(BASE_SQL,WHERECLAUSE," ORDER BY w.CREATION_TS DESC");


PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
