CREATE  PROCEDURE `SALES_TILL_BALANCE`(
	IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN
DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';

DECLARE DATE_WHERE_CLAUSE VARCHAR(5000) DEFAULT '';
SET DATE_WHERE_CLAUSE=WHERECLAUSE;

SET DATE_WHERE_CLAUSE=replace(DATE_WHERE_CLAUSE,'t.FROM_AS_OF_DATE','t.AS_OF_DATE');
SET DATE_WHERE_CLAUSE=replace(DATE_WHERE_CLAUSE,'t.TO_AS_OF_DATE','t.AS_OF_DATE');
SET DATE_WHERE_CLAUSE=replace(DATE_WHERE_CLAUSE,'t.CREATED_BY','concat(e.FIRST_NM," ",e.LAST_NM)');
SET DATE_WHERE_CLAUSE=replace(DATE_WHERE_CLAUSE,'t.TILL_ACCOUNT','concat(c.ACCOUNT_NAME," : ",c.ACCOUNT_NO)');


SET BASE_SQL=  'select ifnull(ROUND(t.PREV_BALANCE,2),0) PREV_BALANCE,ifnull(ROUND(t.CURRENT_BALANCE,2),0) CURRENT_BALANCE,
t.CREATION_TS,t.LAST_UPDATE_TS,
DATE_FORMAT(t.AS_OF_DATE,"%d-%m-%y") AS AS_OF_DATE,
t.AS_OF_DATE AS AS_NOW_DATE,
t.CUSTOMER_NM,t.BILL_CODE,t.BILL_DATE,ifnull(ROUND(t.AMOUNT,2),0) AMOUNT,
concat(c.ACCOUNT_NAME," : ",c.ACCOUNT_NO) AS TILL_ACCOUNT,
ifnull(ROUND(t.CURRENT_BALANCE,2),0) CURRENT_BALANCE,ifnull(ROUND(t.ADJUSTED_BALANCE,2),0) ADJUSTED_BALANCE,
concat(e.FIRST_NM," ",e.LAST_NM) AS SUBMITTED_BY
from till_balance t
inner join employee e on e.EMPLOYEE_ID=t.LAST_UPDATE_USER_ID
inner join chart_of_accounts c on c.ACCOUNT_ID=t.TILL_ACCOUNT_ID';



SET @FINAL_SQL= CONCAT(BASE_SQL,DATE_WHERE_CLAUSE,' order by t.LAST_UPDATE_TS asc');

PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;

END ;;
DELIMITER ;
