CREATE  PROCEDURE `SALE_PURCHASE_PRICE_FOR_YEARLY_DATA`(
	IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN
DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';
DECLARE STOCK_WHERE_CLAUSE VARCHAR(5000) DEFAULT '';
SET STOCK_WHERE_CLAUSE=WHERECLAUSE;

SET STOCK_WHERE_CLAUSE=replace(STOCK_WHERE_CLAUSE,'st.FROM_BILL_DATE','st.STOCK_DATE');
SET STOCK_WHERE_CLAUSE=replace(STOCK_WHERE_CLAUSE,'st.TO_BILL_DATE','st.STOCK_DATE');
 

SET BASE_SQL='select i.ITEM_CD,i.ITEM_NM,s.SP_NAME,st.BATCH_NO, st.EXPIRY_DT,st.PACK,
ifnull(st.PURCHASE_DISCOUNT_PERCENTAGE,0) AS PURCHASE_DISCOUNT_PERCENTAGE, 
ifnull(st.UNIT_PURCHASE_RATE,0) AS UNIT_PURCHASE_RATE,
ifnull(st.SALE_DISCOUNT_PERCENTAGE,0) as SALE_DISCOUNT_PERCENTAGE,
ifnull(st.UNIT_SALE_RATE,0) AS UNIT_SALE_RATE, 
tc.CATEGORY_CODE as TAX_CATEGORY,
ifnull(ROUND((tc.CATEGORY_VALUE/100)*((st.QUANTITY*st.UNIT_SALE_RATE)),2),0) AS VAT_AMT,
round(st.PACK * ifnull(UNIT_PURCHASE_RATE,0) ,2) AS PURCHASE_PACK_PRICE,
round(st.PACK * ifnull(UNIT_SALE_RATE,0) ,2) AS SALE_PACK_PRICE
from stock st inner join items i on st.ITEM_ID = i.ITEM_ID
left join supplier s on s.SUPPLIER_ID=st.SUPPLIER_ID
left join taxcategory tc on tc.TAXCATEGORY_ID=st.TAX_CATEGORY_ID'; 

SET @FINAL_SQL= CONCAT(BASE_SQL,STOCK_WHERE_CLAUSE,' order by st.STOCK_DATE');

PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
