CREATE  PROCEDURE `StockUpdateByItemId`(IN `ITEMID` INT)
BEGIN
DECLARE n INT(11) DEFAULT 0;
DECLARE i INT(11) DEFAULT 0;
DECLARE globalmargin INT(11) DEFAULT 0;
DECLARE tempglobalmargin INT(11) DEFAULT 0;
DECLARE globalmarkup INT(11) DEFAULT 0;
DECLARE itemmargin INT(11) DEFAULT 0;

DECLARE puchasePrice Double(16,2) DEFAULT 0;
DECLARE purchaseDiscPer Double(16,2) DEFAULT 0;
DECLARE purchasePriceAfterDisc Double(16,2) DEFAULT 0;
DECLARE salesdiscPer Double(16,2) DEFAULT 0;
DECLARE salesDiscountPrice Double(16,2) DEFAULT 0;
DECLARE marginPrice Double(16,2) DEFAULT 0;
DECLARE markupPrice Double(16,2) DEFAULT 0;
DECLARE marginPulseMarkupPrice Double(16,2) DEFAULT 0;
DECLARE finalSalesPrice Double(16,2) DEFAULT 0;
#DECLARE itemid INT(11) DEFAULT 0;
DECLARE stockid INT(11) DEFAULT 0;
select CONFIG_VALUE from configuration where CONFIG_DESC="margin" and ACTIVE_S="Y" INTO globalmargin;
select CONFIG_VALUE from configuration where CONFIG_DESC="maxdiscount" and ACTIVE_S="Y" INTO globalmarkup;

Select COUNT(*) from stock s inner join items i on i.Item_id = s.item_id where s.item_id=ITEMID and STOCK_ID is not null INTO n;
SET i=0;
WHILE i<n DO 
  select ifnull(s.UNIT_PURCHASE_RATE,0) from stock s inner join items i on i.Item_id = s.item_id where s.item_id=ITEMID limit i,1 INTO puchasePrice;
  select ifnull(s.PURCHASE_DISCOUNT_PERCENTAGE,0) from stock s inner join items i on i.Item_id = s.item_id where s.item_id=ITEMID limit i,1 INTO purchaseDiscPer;
  select ifnull(ss.SALE_DISCOUNT_PERCENTAGE,0) from stock s inner join items i on i.Item_id = s.item_id where s.item_id=ITEMID limit i,1 INTO salesdiscPer;
  #select s.ITEM_ID from stock s limit i,1 INTO itemid;
  select STOCK_ID from stock s inner join items i on i.Item_id = s.item_id where s.item_id=ITEMID limit i,1 INTO stockid;
  
  select ic.MARGIN_PERCENTAGE from items i inner join stock s on s.ITEM_ID=i.ITEM_ID  
  inner join items_categories ic on i.ITEM_CATEGORIE_ID = ic.ITEM_CATEGORIE_ID where s.STOCK_ID=stockid and ic.MARGIN_PERCENTAGE is not null INTO itemmargin;
  
  SET purchasePriceAfterDisc = ((puchasePrice * (100 - purchaseDiscPer) / 100));
  SET salesDiscountPrice = (((puchasePrice - purchasePriceAfterDisc * (100 - salesdiscPer) / 100) - (puchasePrice - purchasePriceAfterDisc)));
 SET tempglobalmargin = globalmargin;
 IF itemmargin is not NULL and itemmargin>0 THEN
	SET globalmargin = itemmargin;
  END IF;
   
  SET marginPrice = ((purchasePriceAfterDisc * ((100 + globalmargin) / 100)));
  SET markupPrice = ((puchasePrice * ((100 + globalmarkup) / 100)));
  SET marginPulseMarkupPrice = ((marginPrice + (markupPrice - puchasePrice)));
  SET finalSalesPrice = ((marginPulseMarkupPrice - salesDiscountPrice));
   select stockid,itemmargin,purchasePriceAfterDisc,globalmargin,tempglobalmargin,FORMAT((purchasePriceAfterDisc * ((100 + globalmargin) / 100)),2),finalSalesPrice;
  update Stock s set s.UNIT_SALE_RATE = finalSalesPrice,s.MRP=finalSalesPrice where s.STOCK_ID=stockid and s.ITEM_ID=ITEMID and finalSalesPrice>0;

  SET i = i + 1;
#SET itemid=0;
SET itemmargin=0;

SET globalmargin = tempglobalmargin;
END WHILE;
END ;;
DELIMITER ;
