CREATE  PROCEDURE `stockupdatewithitemcategory`(IN `itemCategoryId` INT)
BEGIN
DECLARE n INT(11) DEFAULT 0;
DECLARE i INT(11) DEFAULT 0;
DECLARE globalmargin INT(11) DEFAULT 0;
DECLARE tempglobalmargin INT(11) DEFAULT 0;
DECLARE globalmarkup INT(11) DEFAULT 0;
DECLARE itemmargin INT(11) DEFAULT 0;

DECLARE puchasePrice Double(16,2) DEFAULT 0;
DECLARE purchaseDiscPer Double(16,2) DEFAULT 0;
DECLARE purchasePriceAfterDisc Double(16,2) DEFAULT 0;
DECLARE salesdiscPer Double(16,2) DEFAULT 0;
DECLARE salesDiscountPrice Double(16,2) DEFAULT 0;
DECLARE marginPrice Double(16,2) DEFAULT 0;
DECLARE markupPrice Double(16,2) DEFAULT 0;
DECLARE marginPulseMarkupPrice Double(16,2) DEFAULT 0;
DECLARE finalSalesPrice Double(16,2) DEFAULT 0;
DECLARE itemid INT(11) DEFAULT 0;
DECLARE stockid INT(11) DEFAULT 0;
select CONFIG_VALUE from configuration where CONFIG_DESC="margin" and ACTIVE_S="Y" INTO globalmargin;
select CONFIG_VALUE from configuration where CONFIG_DESC="maxdiscount" and ACTIVE_S="Y" INTO globalmarkup;

select count(i.Item_id) from items i inner join items_categories ic on i.ITEM_CATEGORIE_ID=ic.ITEM_CATEGORIE_ID inner join Stock s 
on s.item_id=i.item_id where ic.ITEM_CATEGORIE_ID=itemCategoryId INTO n;

SET i=0;
WHILE i<n DO 
  select ifnull(s.UNIT_PURCHASE_RATE,0) from items i inner join items_categories ic on i.ITEM_CATEGORIE_ID=ic.ITEM_CATEGORIE_ID inner join Stock s 
on s.item_id=i.item_id where ic.ITEM_CATEGORIE_ID=itemCategoryId limit i,1 INTO puchasePrice;
 
 select ifnull(s.PURCHASE_DISCOUNT_PERCENTAGE,0) from items i inner join items_categories ic on i.ITEM_CATEGORIE_ID=ic.ITEM_CATEGORIE_ID inner join Stock s 
on s.item_id=i.item_id where ic.ITEM_CATEGORIE_ID=itemCategoryId limit i,1 INTO purchaseDiscPer;
  
  select ifnull(s.SALE_DISCOUNT_PERCENTAGE,0) from items i inner join items_categories ic on i.ITEM_CATEGORIE_ID=ic.ITEM_CATEGORIE_ID inner join Stock s 
on s.item_id=i.item_id where ic.ITEM_CATEGORIE_ID=itemCategoryId limit i,1 INTO salesdiscPer;
  
  select i.Item_id from items i inner join items_categories ic on i.ITEM_CATEGORIE_ID=ic.ITEM_CATEGORIE_ID inner join Stock s 
on s.item_id=i.item_id where ic.ITEM_CATEGORIE_ID=itemCategoryId limit i,1 INTO itemid;
  
  select STOCK_ID from items i inner join items_categories ic on i.ITEM_CATEGORIE_ID=ic.ITEM_CATEGORIE_ID inner join Stock s 
on s.item_id=i.item_id where ic.ITEM_CATEGORIE_ID=itemCategoryId limit i,1 INTO stockid;
  
  select ic.MARGIN_PERCENTAGE from  items_categories ic  where ic.ITEM_CATEGORIE_ID=itemCategoryId and ic.MARGIN_PERCENTAGE is not null INTO itemmargin;
  
  SET purchasePriceAfterDisc = ((puchasePrice * (100 - purchaseDiscPer) / 100));
  SET salesDiscountPrice = (((puchasePrice - purchasePriceAfterDisc * (100 - salesdiscPer) / 100) - (puchasePrice - purchasePriceAfterDisc)));
 SET tempglobalmargin = globalmargin;
 IF itemmargin is not NULL and itemmargin>0 THEN
	SET globalmargin = itemmargin;
 END IF;
   
  SET marginPrice = ((purchasePriceAfterDisc * ((100 + globalmargin) / 100)));
  SET markupPrice = ((puchasePrice * ((100 + globalmarkup) / 100)));
  SET marginPulseMarkupPrice = ((marginPrice + (markupPrice - puchasePrice)));
  SET finalSalesPrice = ((marginPulseMarkupPrice - salesDiscountPrice));
   select stockid,itemmargin,purchasePriceAfterDisc,globalmargin,tempglobalmargin,FORMAT((purchasePriceAfterDisc * ((100 + globalmargin) / 100)),2),finalSalesPrice;

  update Stock s set s.UNIT_SALE_RATE = finalSalesPrice,s.MRP=finalSalesPrice where s.ITEM_ID=itemid and finalSalesPrice>0;



  SET i = i + 1;
#SET itemid=0;
SET itemmargin=0;

SET globalmargin = tempglobalmargin;
END WHILE;
END ;;
DELIMITER ;
