CREATE  PROCEDURE `STOCK_ITEMS_UPCOMING_EXPIRY_REPORT`(
	IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN
DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';
DECLARE SALES_WHERE_CLAUSE  VARCHAR(5000) DEFAULT '';

set SALES_WHERE_CLAUSE=WHERECLAUSE;
SET SALES_WHERE_CLAUSE=replace(SALES_WHERE_CLAUSE,'st.FROM_DATE','a.EXPIRY_DT');
SET SALES_WHERE_CLAUSE=replace(SALES_WHERE_CLAUSE,'st.TO_DATE','a.EXPIRY_DT');

SET BASE_SQL='select  b.ITEM_NM , a.QUANTITY,
a.BATCH_NO, DATE_FORMAT(a.EXPIRY_DT,"%d-%m-%y") as EXPIRY_DT, a.Invoice_No as INVOICE_NO,
 s.SP_NAME from stock a
inner join items b on a.ITEM_ID = b.ITEM_ID and a.Quantity != 0
inner join supplier s on s.SUPPLIER_ID = a.SUPPLIER_ID
';


SET @FINAL_SQL= CONCAT(BASE_SQL,SALES_WHERE_CLAUSE, 'order by 4,1,5,6');

PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;

END ;;
