CREATE  PROCEDURE `STOCK_TAKE_EXCEPTION`(
	IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN
DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';
DECLARE BASE_SQL1  VARCHAR(5000) DEFAULT '';
DECLARE NEW_WHERE_CLAUSE  VARCHAR(5000) DEFAULT '';

SET NEW_WHERE_CLAUSE=WHERECLAUSE;
SET NEW_WHERE_CLAUSE=replace(NEW_WHERE_CLAUSE,'sa.FROM_UPDATED_DATE','date_format(sa.LAST_UPDATE_TS,"%y-%m-%d")');
SET NEW_WHERE_CLAUSE=replace(NEW_WHERE_CLAUSE,'sa.TO_UPDATED_DATE','date_format(sa.LAST_UPDATE_TS,"%y-%m-%d")');

TRUNCATE TABLE stock_take_working;

set BASE_SQL1='insert into stock_take_working 
SELECT i.item_id,
i.ITEM_NM,st.INVOICE_NO,st.BATCH_NO,st.EXPIRY_DT,
ifnull(st.RACK,"") RACK,ifnull(st.SHELF,"") SHELF,sa.PHYSICAL_STOCK,sa.ADJUSTEMENT_STOCK,
e.FIRST_NM,DATE_FORMAT(sa.LAST_UPDATE_TS,"%d-%m-%y") LAST_UPDATED_DT,
sa.LAST_UPDATE_TS,sa.SYSTEM_DATE,sa.SYSTEM_DATE,sa.remarks from stock_adjustment sa  
inner join stock st on st.STOCK_ID=sa.STOCK_ID
inner join items i on i.ITEM_ID=st.ITEM_ID
INNER JOIN employee e on e.EMPLOYEE_ID=sa.LAST_UPDATE_USER_ID';

SET @FINAL_SQL= CONCAT(BASE_SQL1,NEW_WHERE_CLAUSE);

PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;

SET BASE_SQL='select i.ITEM_NM,s.BATCH_NO,s.EXPIRY_DT,s.RACK,s.SHELF,
s.INVOICE_NO,s.QUANTITY,s.LAST_UPDATE_TS,concat(e.FIRST_NM," ",e.LAST_NM) AS MODIFIED_BY from stock s 
inner join items i on i.item_id=s.item_id
left join employee e on e.EMPLOYEE_ID=s.LAST_UPDATE_USER_ID
where i.ITEM_NM not in(select sw.item_nm from stock_take_working sw)';

SET @FINAL_SQL= CONCAT(BASE_SQL);

PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;

END ;;
DELIMITER ;
