CREATE  PROCEDURE `STOCK_TAKE_EXPIRY`(
	IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN
DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';


DROP TABLE IF EXISTS `#stock_adjustment_working`;

CREATE TABLE `#stock_adjustment_working` (
  `ITEM_NM` varchar(100) DEFAULT NULL,
  `INVOICE_NO` varchar(20) DEFAULT NULL,
  `BATCH_NO` varchar(20) DEFAULT NULL,
  `EXPIRY_DT` date DEFAULT NULL,
  `RACK` varchar(50) DEFAULT NULL,
  `SHELF` varchar(50) DEFAULT NULL,
  `PHYSICAL_STOCK` int(11) DEFAULT NULL,
  `ADJUSTEMENT_STOCK` int(11) DEFAULT NULL,
  `LAST_UPDATE_USER` varchar(50) DEFAULT NULL,
  `LAST_UPDATED_DT` date DEFAULT NULL,
  `LAST_UPDATE_TS` timestamp NULL DEFAULT NULL,
  `FROM_SYSTEM_DATE` date DEFAULT NULL,
  `TO_SYSTEM_DATE` date DEFAULT NULL,
  `REMARKS` varchar(500) DEFAULT NULL,
  `PREVIOUS_AMT` double DEFAULT NULL,
  `ADJUSTED_AMT` double DEFAULT NULL,
  `PURCHASE_DISCOUNT_PERCENTAGE` int(11) DEFAULT NULL,
   `P_PRICE` double DEFAULT NULL
) ;

insert into `#stock_adjustment_working` SELECT ifnull(i.ITEM_NM,""),ifnull(st.INVOICE_NO,""),
ifnull(st.BATCH_NO,""),st.EXPIRY_DT,
ifnull(st.RACK,"") RACK,ifnull(st.SHELF,"") SHELF,sa.PHYSICAL_STOCK,sa.ADJUSTEMENT_STOCK,
concat(e.FIRST_NM," ",e.LAST_NM),DATE_FORMAT(sa.LAST_UPDATE_TS,"%d-%m-%y") LAST_UPDATED_DT,
sa.LAST_UPDATE_TS,sa.SYSTEM_DATE,sa.SYSTEM_DATE,sa.REMARKS,
round(ifnull(sa.PHYSICAL_STOCK,0) * st.UNIT_PURCHASE_RATE * ( 1 - ifnull(st.PURCHASE_DISCOUNT_PERCENTAGE,0)/100),2) AS PREVIOUS_AMT,
round(ifnull(sa.ADJUSTEMENT_STOCK,0) * st.UNIT_PURCHASE_RATE * ( 1 - ifnull(st.PURCHASE_DISCOUNT_PERCENTAGE,0)/100),2) AS ADJUSTED_AMT,
st.PURCHASE_DISCOUNT_PERCENTAGE, st.UNIT_PURCHASE_RATE from stock_adjustment sa  
inner join stock st on st.STOCK_ID=sa.STOCK_ID
inner join items i on i.ITEM_ID=st.ITEM_ID
INNER JOIN employee e on e.EMPLOYEE_ID=sa.LAST_UPDATE_USER_ID and sa.LAST_UPDATE_TS>st.expiry_dt;

SET BASE_SQL='SELECT sa.ITEM_NM,ifnull(sa.INVOICE_NO,"") INVOICE_NO,
sa.BATCH_NO,date_format(sa.EXPIRY_DT,"%d-%m-%y") EXPIRY_DT,
sa.RACK,sa.SHELF,ifnull(sa.PHYSICAL_STOCK,0) PHYSICAL_STOCK,ifnull(sa.ADJUSTEMENT_STOCK,0) ADJUSTEMENT_STOCK,
(ifnull(sa.PHYSICAL_STOCK,0)-ifnull(sa.ADJUSTEMENT_STOCK,0)) as STOCK_VALUE_CHANGE,
sa.LAST_UPDATE_USER,sa.LAST_UPDATED_DT,ifnull(sa.REMARKS,"N/A") REMARKS,
ifnull(sa.PREVIOUS_AMT,0) PREVIOUS_AMT,ifnull(sa.ADJUSTED_AMT,0) ADJUSTED_AMT ,ifnull(sa.PURCHASE_DISCOUNT_PERCENTAGE,0) AS P_DISC,
ifnull(sa.P_PRICE,0) AS P_PRICE,
DATE_FORMAT(sa.LAST_UPDATE_TS,"%d-%m-%y %h:%i %p") LAST_UPDATE_TS,
row_number() over(order by last_update_ts)  AS S_NO,
sa.FROM_SYSTEM_DATE,sa.TO_SYSTEM_DATE from `#stock_adjustment_working` sa';

SET @FINAL_SQL= CONCAT(BASE_SQL,WHERECLAUSE);

PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;

END ;;
