DELIMITER ;;
CREATE  PROCEDURE `SUPPLIER_WISE_SALES`(
	IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN 
DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';
DECLARE SALES_WHERE_CLAUSE VARCHAR(5000) DEFAULT '';

SET BASE_SQL='select distinct si.SALE_QTY,round(si.UNIT_SALE_PRICE,2)as unit_price,
CONCAT(e.FIRST_NM," ", e.LAST_NM) AS EMP_NM,
ifnull(round((si.UNIT_SALE_PRICE*si.SALE_QTY)*(si.DISCOUNT_PERCENTAGE/100),2),0) as Total_discount,
sp.SUPPLIER_ID, sp.SP_NAME as SUPPLIER_NAME ,s.BILL_DATE,
si.SALE_AMOUNT,si.BATCH_NO,i.ITEM_CD,i.ITEM_NM,round((si.SALE_QTY*si.UNIT_SALE_PRICE),2) AS SUB_TOTAL,
ifnull(round(si.UNIT_SALE_PRICE*si.SALE_QTY*(1-si.DISCOUNT_PERCENTAGE/100),2),0) as TOTAL_AMOUNT ,
 concat(e.FIRST_NM , " " , e.LAST_NM) as CREATED_BY,
concat(emp.FIRST_NM , " " , emp.LAST_NM) as MODIFIED_BY from sales_items si 
INNER JOIN sales s on s.BILL_ID = si.BILL_ID
INNER JOIN items i ON si.ITEM_ID=i.ITEM_ID
Inner join stock st on st.stock_Id = si.stock_id
inner join invoice ic on ic.grn_no = st.INVOICE_NO
inner join supplier sp on sp.SUPPLIER_ID=ic.SUPPLIER_ID 
inner join employee e on e.EMPLOYEE_ID=s.CREATION_USER_ID 
inner join employee emp on emp.EMPLOYEE_ID=s.LAST_UPDATE_USER_ID '; 


SET SALES_WHERE_CLAUSE=WHERECLAUSE;  
SET SALES_WHERE_CLAUSE=replace(SALES_WHERE_CLAUSE,'sv.FromDate','s.BILL_DATE');
SET SALES_WHERE_CLAUSE=replace(SALES_WHERE_CLAUSE,'sv.ToDate','s.BILL_DATE');
SET SALES_WHERE_CLAUSE=replace(SALES_WHERE_CLAUSE,'e.EMP_NM','CONCAT(e.FIRST_NM," ", e.LAST_NM)');

SET @FINAL_SQL= CONCAT(BASE_SQL,SALES_WHERE_CLAUSE,'ORDER BY s.BILL_DATE');

PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;
END ;;
DELIMITER ;
