CREATE  PROCEDURE `TILL_BALANCE`(
	IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN
DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';

DECLARE DATE_WHERE_CLAUSE VARCHAR(5000) DEFAULT '';
SET DATE_WHERE_CLAUSE=WHERECLAUSE;

SET DATE_WHERE_CLAUSE=replace(DATE_WHERE_CLAUSE,'t.FROM_AS_OF_DATE','tb.AS_OF_DATE');
SET DATE_WHERE_CLAUSE=replace(DATE_WHERE_CLAUSE,'t.TO_AS_OF_DATE','tb.AS_OF_DATE');

SET BASE_SQL=  'select ifnull(tb.PREV_BALANCE,0) PREV_BALANCE,
DATE_FORMAT(tb.AS_OF_DATE,"%d-%m-%y") AS AS_OF_DATE,
ifnull(tb.CURRENT_BALANCE,0) CURRENT_BALANCE,ifnull(tb.ADJUSTED_BALANCE,0) ADJUSTED_BALANCE,
concat(e.FIRST_NM," ",e.LAST_NM) AS SUBMITTED_BY,concat(c.ACCOUNT_NAME," : ",c.ACCOUNT_NO) TILL_ACCOUNT
from till_balance tb
inner join chart_of_accounts c on c.ACCOUNT_ID=tb.TILL_ACCOUNT_ID
inner join employee e on e.EMPLOYEE_ID=tb.LAST_UPDATE_USER_ID';


SET @FINAL_SQL= CONCAT(BASE_SQL,DATE_WHERE_CLAUSE);

PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
