CREATE  PROCEDURE `TRANSACTIONS_BY_ACCOUNT_TYPE`(
	IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN
DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';

truncate table transaction_by_account_type_working;

insert into transaction_by_account_type_working(
select ifnull(concat(ca.ACCOUNT_NAME," : ",ca.ACCOUNT_NO),''),
ifnull(bt.REASON,"N/A") ,
ifnull(concat(cao.ACCOUNT_NAME," : ",cao.ACCOUNT_NO),''),
bt.AMOUNT,
bt.BALANCE,bt.TRANSACTION_DATE,bt.TRANSACTION_DATE,
bt.CREATION_TS,bt.LAST_UPDATE_TS,
concat(em.FIRST_NM,' ',ifnull(em.LAST_NM,'')),bt.COUNTER_PARTY_BALANCE,bt.TRANSACTION_REF,
pat.account_type,cat.account_type,bt.STATUS,bt.MODE
from bank_transactions_history bt  
inner join employee em on em.EMPLOYEE_ID=bt.LAST_UPDATE_USER_ID
left join chart_of_accounts ca on ca.ACCOUNT_ID=bt.PARTY
left join chart_of_accounts cao on cao.ACCOUNT_ID=bt.COUNTER_PARTY
left join account_type pat on pat.account_type_id=ca.account_type
left join account_type cat on cat.account_type_id=cao.account_type

union

select ifnull(concat(ca.ACCOUNT_NAME," : ",ca.ACCOUNT_NO),''),
ifnull(ex.REASON,"N/A") ,
ifnull(concat(cao.ACCOUNT_NAME," : ",cao.ACCOUNT_NO),''),
ex.AMOUNT,
ex.BALANCE,ex.DATE,ex.DATE,
ex.CREATION_TS,ex.LAST_UPDATE_TS,
concat(em.FIRST_NM,' ',ifnull(em.LAST_NM,'')),
ex.COUNTER_PARTY_BALANCE,ex.EXPENSE_NO,pat.account_type,
cat.account_type,"Expenses",ex.MODE
from expenses ex  
inner join employee em on em.EMPLOYEE_ID=ex.LAST_UPDATE_USER_ID
left join chart_of_accounts ca on ca.ACCOUNT_ID=ex.PARTY_NO
left join chart_of_accounts cao on cao.ACCOUNT_ID=ex.COUNTER_PARTY_NO
left join account_type pat on pat.account_type_id=ca.account_type
left join account_type cat on cat.account_type_id=cao.account_type);

SET BASE_SQL='select bt.PARTY,bt.CREATION_TS,
DATE_FORMAT(bt.LAST_UPDATE_TS,"%d-%m-%y %h:%i %p") LAST_UPDATE_TS,
bt.REFERENCE,bt.COUNTER_PARTY,bt.AMOUNT,bt.FROM_AS_OF_DATE AS TXN_DATE,
bt.BALANCE,DATE_FORMAT(bt.FROM_AS_OF_DATE,"%d-%m-%y") AS FROM_DATE,
DATE_FORMAT(bt.TO_AS_OF_DATE,"%d-%m-%y") as TO_AS_OF_DATE,
bt.LAST_UPDATE_USER AS SUBMITTED_BY,bt.REF_NO,bt.PARTY_ACCOUNT_TYPE,bt.COUNTER_PARTY_ACCOUNT_TYPE,
ifnull(bt.COUNTER_PARTY_BALANCE,"N/A") COUNTER_PARTY_BALANCE,bt.STATUS,bt.MODE
from  transaction_by_account_type_working bt
left join chart_of_accounts ca on ca.ACCOUNT_NO=bt.PARTY
left join chart_of_accounts cao on cao.ACCOUNT_NO=bt.Counter_Party';

SET @FINAL_SQL= CONCAT(BASE_SQL,WHERECLAUSE,' order by bt.LAST_UPDATE_TS asc');

PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
