CREATE  PROCEDURE `UNTOUCHED_STOCK_ITEMS`(
	IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN
DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';
DECLARE STOCK_WHERE_CLAUSE VARCHAR(5000) DEFAULT '';


SET STOCK_WHERE_CLAUSE=WHERECLAUSE;  
SET STOCK_WHERE_CLAUSE=replace(STOCK_WHERE_CLAUSE,'st.FROM_UPDATED_DATE','st.STOCK_DATE');
SET STOCK_WHERE_CLAUSE=replace(STOCK_WHERE_CLAUSE,'st.TO_UPDATED_DATE','st.STOCK_DATE');

SET BASE_SQL='SELECT st.STOCK_ID,st.STOCK_NO,i.ITEM_NM,i.ITEM_NM,st.QUANTITY,
round(ifnull(st.UNIT_PURCHASE_RATE,0),2) UNIT_PURCHASE_RATE,
st.BATCH_NO,st.EXPIRY_DT,
round(ifnull(st.UNIT_SALE_RATE,0),2) UNIT_SALE_RATE,st.STOCK_DATE,
date_format(st.STOCK_DATE,"%d-%m-%y") AS STOCK_DT,
ifnull(st.PURCHASE_DISCOUNT_PERCENTAGE,0) PURCHASE_DISCOUNT_PERCENTAGE,
ifnull(st.SALE_DISCOUNT_PERCENTAGE,0) SALE_DISCOUNT_PERCENTAGE,
st.INVOICE_NO,tc.CATEGORY_VALUE 
from stock st 
inner join items i on i.ITEM_ID=st.ITEM_ID
inner join taxcategory tc on tc.TAXCATEGORY_ID=st.TAX_CATEGORY_ID';

SET @FINAL_SQL= CONCAT(BASE_SQL,STOCK_WHERE_CLAUSE,' and st.QUANTITY>0 and st.STOCK_ID not in (select stock_id from sales_items)',' order by st.CREATION_TS desc');

PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
