CREATE  PROCEDURE `UPCOMING_PAYABLES`(
	IN `WHERECLAUSE` VARCHAR(500)
)
BEGIN
DECLARE BASE_SQL  VARCHAR(5000) DEFAULT '';
DECLARE BASE_SQL_ONE  VARCHAR(5000) DEFAULT '';
DECLARE SALES_WHERE_CLAUSE VARCHAR(5000) DEFAULT '';
SET SALES_WHERE_CLAUSE=WHERECLAUSE; 

SET BASE_SQL=' select s.SP_NAME,
ap.PAYMENT_NO,
ap.SOURCE_REF
,ap.INVOICE_NO,
date_format(ap.PAYMENT_DATE,"%d-%m-%y") as PAYMENT_DATE,
ap.STATUS,
ap.TOTAL_AMOUNT_PAID,
ap.TOTAL_AMOUNT_TO_BE_PAID,
ap.PAYMENT_STATUS,
ap.SOURCE_TYPE,
concat(e.FIRST_NM," ",e.LAST_NM) as created_by ,
inv.CREDIT_DAYS
from account_payables ap 
inner join supplier s on ap.SUPPLIER_ID=s.SUPPLIER_ID
inner join employee e on e.EMPLOYEE_ID=ap.CREATION_USER_ID
inner join invoice inv on inv.INVOICE_NO = ap.INVOICE_NO ';

set BASE_SQL_ONE= ' and ap.PAYMENT_STATUS = "Pending" and ap.STATUS = "Not Approved"';

SET @FINAL_SQL= CONCAT(BASE_SQL,SALES_WHERE_CLAUSE,BASE_SQL_ONE);

PREPARE stmt FROM @FINAL_SQL;
EXECUTE  stmt;
deallocate PREPARE stmt;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
